#include <bits/stdc++.h>
using namespace std;

int id = INT_MAX;
int merge(int l, int r) {
	return min(l, r);
}

struct node {
	int val;
	int all;
	node *ch[2];
	int size;
	int sum;
	node(int v) : val(v), all(v), size(1), sum(v) {
		ch[0] = ch[1] = nullptr;
	}
};

int count(node *t) { return t == nullptr ? 0 : t->size; }
int sum(node *t) { return t == nullptr ? 0 : t->sum; }
int que(node *t) { return t == nullptr ? id : t->all; }
node *update(node *t) {
	t->size = count(t->ch[0]) + count(t->ch[1]) + 1;
	t->sum = sum(t->ch[0]) + sum(t->ch[1]) + t->val;
	t->all = merge(que(t->ch[0]), merge(t->val, que(t->ch[1])));
	return t;
}
node *rotate(node *t, int b) {
	node *s = t->ch[1 - b];
	t->ch[1 - b] = s->ch[b];
	s->ch[b] = t;
	update(t); update(s);
	return s;
}
node *splay(node *t, int k) {
	assert(t != nullptr && k < count(t));
	int c = count(t->ch[0]);
	if (k < c) {
		int cc = count(t->ch[0]->ch[0]);
		if (k < cc) {
			t->ch[0]->ch[0] = splay(t->ch[0]->ch[0], k);
			t = rotate(t, 1);
			t = rotate(t, 1);
		}
		else if (k > cc) {
			t->ch[0]->ch[1] = splay(t->ch[0]->ch[1], k - (cc + 1));
			t->ch[0] = rotate(t->ch[0], 0);
			t = rotate(t, 1);
		}
		else {
			t = rotate(t, 1);
		}
	}
	else if (k > c) {
		k -= c + 1;
		int cc = count(t->ch[1]->ch[0]);
		if (k < cc) {
			t->ch[1]->ch[0] = splay(t->ch[1]->ch[0], k);
			t->ch[1] = rotate(t->ch[1], 1);
			t = rotate(t, 0);
		}
		else if (k > cc) {
			t->ch[1]->ch[1] = splay(t->ch[1]->ch[1], k - (cc + 1));
			t = rotate(t, 0);
			t = rotate(t, 0);
		}
		else {
			t = rotate(t, 0);
		}
	}
	return t;
}
node *merge(node *l, node *r) {
	if (l == nullptr || r == nullptr) return l == nullptr ? r : l;
	l = splay(l, count(l) - 1);
	l->ch[1] = r;
	update(l);
	return l;
}
pair<node*, node*> split(node *t, int k) {
	if (t == nullptr) return make_pair(nullptr, nullptr);
	if (k >= count(t)) return make_pair(t, nullptr);
	t = splay(t, k);
	auto s = t->ch[0];
	t->ch[0] = nullptr;
	return make_pair(s, update(t));
}
node *insert(node *t, int k, int v) {
	pair<node*, node*> s = split(t, k);
	node *r = merge(s.first, new node(v));
	r = merge(r, s.second);
	return r;
}
node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	if (s2.first != nullptr) delete s2.first;
	return merge(s1.first, s2.second);
}
int find(node *t, int l, int r) {
	if (t == nullptr) return id;
	if (r < 0 || l >= count(t)) return id;
	if (l <= 0 && r >= t->size) return t->all;
	int c = count(t->ch[0]);
	return merge(t->ch[0] == nullptr ? id : find(t->ch[0], l, r), merge(l <= c && c < r ? t->val : id, t->ch[1] == nullptr ? id : find(t->ch[1], l - (c + 1), r - (c + 1))));
}
node *find(node *t, int k) {
	if (t == nullptr) return t;
	int c = count(t->ch[0]);
	return k < c ? find(t->ch[0], k) : k == c ? t : find(t->ch[1], k - (c + 1));
}
node *shift(node *t, int l, int r) {
	pair<node*, node*> s1 = split(t, l), s2 = split(s1.second, r - l), s3 = split(s2.second, 1);
	return merge(s1.first, merge(s3.first, merge(s2.first, s3.second)));
}
int cnt(node *t, int v) {
	if (t == nullptr) return 0;
	if (t->val < v) return count(t->ch[0]) + 1 + cnt(t->ch[1], v);
	if (t->val == v) return count(t->ch[0]);
	return cnt(t->ch[0], v);
}
node *change(node *t, int k, int v) {
	t = splay(t, k);
	t->val = v;
	t = update(t);
	return t;
}

int main()
{
	cin.sync_with_stdio(false);
	int n, q, x, y, z;
	cin >> n >> q;
	node *root = nullptr;
	for (int i = 0, a; i < n; i++) {
		cin >> a;
		root = insert(root, i, a);
	}
	while (q--) {
		cin >> x >> y >> z;
		if (x == 0) {
			root = shift(root, y, z);
		}
		else if (x == 1) {
			printf("%d\n", find(root, y, z + 1));
		}
		else {
			root = change(root, y, z);
		}
	}
	return 0;
}

#include<iostream>
#include<vector>
#include<algorithm>
#include<climits>
#include<string>
#include<ctime>
#include<cstdlib>
#define INF INT_MAX

using namespace std;

typedef long long ll;


template<class T>
struct Treap {

public:

  struct node_t{
    T val,mini,sum,lazy;
    node_t *lch,*rch;
    int pri,cnt;
    bool rev;

    node_t(int v,double p):val(v),mini(v),sum(v),pri(p),cnt(1){
      lch=rch=NULL;
      lazy=0;
      rev=false;
    }
  };

  node_t *root;
  Treap():root(NULL){}

private:

  T val(node_t *t){return t->val+t->lazy;}
  int count(node_t *t){return !t?0:t->cnt;}
  T sum(node_t *t){return !t?0:t->sum+t->lazy*count(t);}
  T mini(node_t *t){return !t?INF:t->mini+t->lazy;}

  node_t *update(node_t *t){

    if(!t)return t;

    t->cnt=count(t->lch)+count(t->rch)+1;
    t->sum=sum(t->lch)+sum(t->rch)+val(t);
    t->mini=min(min(mini(t->lch),mini(t->rch)),val(t));

    //if(t->val!=0){
    if(t->lazy){
      t->val+=t->lazy;
      if(t->lch)t->lch->lazy+=t->lazy;
      if(t->rch)t->rch->lazy+=t->lazy;
      t->lazy=0;
    }

    if(t->rev){
      swap(t->lch,t->rch);
      if(t->lch)t->lch->rev^=true;
      if(t->rch)t->rch->rev^=true;
      t->rev=false;
    }
    return t;
  }

  node_t *merge(node_t *l, node_t *r){

    l=update(l), r=update(r);
    if(!l || !r)return l?l:r;

    if(l->pri > r->pri){
      l->rch=merge(l->rch,r);
      return update(l);
    } else {
      r->lch=merge(l,r->lch);
      return update(r);
    }
  }

  //[0,k),[k,n)
  pair<node_t *,node_t *> split(node_t *t,int k){
    if(!update(t))return make_pair((node_t *)NULL,(node_t *)NULL);

    if(k<=count(t->lch)){
      pair<node_t *,node_t *>s=split(t->lch,k);
      t->lch=s.second;
      return make_pair(s.first,update(t));
    } else {
      pair<node_t *,node_t *>s=split(t->rch,k-count(t->lch)-1);
      t->rch=s.first;
      return make_pair(update(t),s.second);
    }
  }

  node_t *insert(node_t *t,int k,T val,int pri){
    pair<node_t *,node_t *>s=split(t,k);
    t=merge(s.first, new node_t(val,pri));
    t=merge(t,s.second);
    return update(t);
  }

  node_t *erase(node_t *t,int k){
    pair<node_t *,node_t *>s1,s2;
    s2=split(t,k+1);
    s1=split(s2.first,k);
    return update((t=merge(s1.first,s2.second)));
  }

  node_t *find(node_t *t, int k){

    int c = count(t->lch);
    if(k < c)return find(t->lch, k);
    if(k == c)return t;
    return find(t->rch, k-c-1);
  }

  T rangeMinimumQuery(int l,int r,node_t *t){

    t=update(t);

    int sz=count(t);
    if(r<=0 || sz<=l)return INF;
    if(l<=0 && sz<=r)return mini(t);

    int cnt=count(t->lch);

    T resl=rangeMinimumQuery(l,r,t->lch);
    T resr=rangeMinimumQuery(l-cnt-1,r-cnt-1,t->rch);
    T res=min(resl,resr);
    if(l<=cnt && cnt<r)res=min(res,val(t));
    return res;

  }

  T rangeSumQuery(int l,int r,node_t *t){

    t=update(t);

    int sz=count(t);
    if(r<=0 || sz<=l)return 0;
    if(l<=0 && sz<=r)return sum(t);

    int cnt=count(t->lch);
    T res=0;
    res+=rangeSumQuery(l,r,t->lch);
    res+=rangeSumQuery(l-cnt-1,r-cnt-1,t->rch);
    if(l<=cnt && cnt<r)res+=val(t);
    return res;
  }

public:

  void insert(int k,T val){ root=insert(root,k,val,rand()); }
  void erase(int k){ root=erase(root,k); }
  node_t *find(int k){ return find(root,k); }

  void add(int id,T val){
    node_t *a=find(id);
    T tmp=val(a);
    erase(id);
    insert(id,tmp+val);
  }

  void rangeAdd(int l,int r,T v){

    pair<node_t *,node_t *>s1,s2;
    s2=split(root,r);
    s1=split(s2.first,l);
    node_t *a=s1.first,*b=s1.second,*c=s2.second;   
    b->lazy+=v;
    root=merge(a,b);
    root=merge(root,c);
  }

  void update(int id,T val){
    erase(id);
    insert(id,val);
  }


  //range query [l,r),0-origin

  //Initialize INF 
  T rangeMinimumQuery(int l,int r){
    return rangeMinimumQuery(l,r,root);
  }

  //Initialize 0
  T rangeSumQuery(int l,int r){
    return rangeSumQuery(l,r,root);
  }

  /*
   reverse(1,4)
   {1,2,3,4,5} -> {1,4,3,2,5}
   */
  void reverse(int l,int r){
    pair<node_t *,node_t *>s1,s2;
    s2=split(root,r);
    s1=split(s2.first,l);
    node_t *a=s1.first,*b=s1.second,*c=s2.second;   
    b->rev^=true;
    root=merge(a,b);
    root=merge(root,c);
  }

  /*
    revolve(1,4,2)
    {1,2,3,4,5} -> {1,3,4,2,5}  
   */
  void revolve(int l,int r,int t){
    t%=(r-l);
    pair<node_t*, node_t*>a,b,c;
    c=split(root, r);
    b=split(c.first, r-t);
    a=split(b.first, l);
    root=merge(a.first, b.second);
    root=merge(root, a.second);
    root=merge(root, c.second);
  }
};

int main(void){

  srand(time(NULL));

  int n,m;
  Treap<ll> t;

  cin >> n >> m;
  for(int i=0;i<n;i++){
    int in;
    cin >> in;
