template<class T>
struct treap
{
	struct node_t
	{
		T val, sum;
		node_t *lch, *rch;
		int pri, cnt;

		node_t( T v, int p )
		:	val( v ), pri( p ), cnt( 1 ), sum( v ), lch( NULL ), rch( NULL )
		{}
	};

	static const int INF = 1<<30;
	node_t *root;
	treap()
	:	root( NULL )
	{}

	int count( node_t *t )
	{
		return t ? t->cnt : 0;
	}

	T sum( node_t *t )
	{
		return t ? t->sum : INF;
	}

	int size()
	{
		return count( root );
	}

	node_t *update( node_t *t )
	{
		t->cnt = count( t->lch ) + count( t->rch ) + 1;
		t->sum = std::min( std::min( sum( t->lch ), sum( t->rch ) ), t->val );

		return t;
	}

	node_t *merge( node_t *l, node_t *r )
	{
		if( !l || !r )
			return l?l:r;

		if( l->pri > r->pri )
		{
			l->rch = merge( l->rch, r );
			return update(l);
		}
		else
		{
			r->lch = merge( l, r->lch );
			return update(r);
		}
	}

	std::pair<node_t *, node_t *> split( node_t *t, int k )
	{
		if( !t )
			return std::make_pair( (node_t *)NULL, (node_t *)NULL );

		if( k <= count( t->lch ) )
		{
			std::pair<node_t *, node_t *> s = split( t->lch, k );
			t->lch = s.second;
			return std::make_pair( s.first, update(t) );
		}
		else
		{
			std::pair<node_t *, node_t *> s = split( t->rch, k-count(t->lch)-1 );
			t->rch = s.first;
			return std::make_pair( update(t), s.second );
		}
	}

	node_t *insert( node_t *t, int k, T val, int pri )
	{
		std::pair<node_t *, node_t *> s = split( t, k );
		t = merge( s.first, new node_t( val, pri ) );
		t = merge( t, s.second );

		return update(t);
	}
	node_t *erase( node_t *t, int k )
	{
		std::pair<node_t *, node_t *> s1, s2;
		s2 = split( t, k+1 );
		s1 = split( s2.first, k );
		t = merge( s1.first, s2.second );

		return update(t);
	}
	node_t *find( node_t *t, int k )
	{
		int c = count( t->lch );
		if( k < c )
			return find( t->lch, k );
		else if( k == c )
			return t;
		else
			return find( t->rch, k-c-1 );
	}
	void insert( int k, T val )
	{
		root = insert( root, k, val, rand() );

		return;
	}
	void erase( int k )
	{
		root = erase( root, k );

		return;
	}
	node_t *find( int k )
	{
		return find( root, k );
	}

	void shift( int l, int r )
	{
		std::pair<node_t *, node_t *> a, b, c;
		c = split( root, r );
		b = split( c.first, r-1 );
		a = split( b.first, l );
		root = merge( a.first, b.second );
		root = merge( root, a.second );
		root = merge( root, c.second );

		return;
	}
	int query( int l, int r, node_t *t )
	{
		int sz = count(t);
		if( l >= sz || r <= 0 )
			return INF;
		if( l <= 0 && r >= sz )
			return sum(t);

		int c = count(t->lch), ret = std::min( query( l, r, t->lch ), query( l-c-1, r-c-1, t->rch ) );

		if( l <= c && c < r )
			ret = std::min( ret, t->val );

		return ret;
	}
};

