    nd = merge(nd,s.second);
    return nd;
}
int query(node_t* root,int a,int b){
    int sz = count(root);
    if(a>=sz || a>b || b<0) return mod;
    if(a<=0 && sz-1<=b) {return sum(root);}
    a = max(0,a); b = min(b,sz-1);
    int x = count(root->ch[0]);
    int L = query(root->ch[0],a,b);
    int R = query(root->ch[1],a-x-1,b-x-1);
    int ret = min(L,R);
    if(a<=x&&x<=b) ret = min(ret,root->val);
    return ret;
}
