template<typename a>
struct Node {
  Node() : left(nullptr), right(nullptr), n(0), rank(0), val(0) {}
  Node(a v_) : left(nullptr), right(nullptr), n(1), rank(1), val(v_) {}
  Node(std::shared_ptr< Node<a> > l, std::shared_ptr< Node<a> > r)
    : left(l), right(r), n(l->n + r->n), rank(std::max(l->rank, r->rank) + 1), val(mergeInfo(l->val, r->val)) {} 
  std::shared_ptr< Node<a> > left;
  std::shared_ptr< Node<a> > right;
  int n;
  int rank;
  a val;
};

template<typename a>
using AVLArray = std::shared_ptr< Node<a> >;

template<typename a>
AVLArray<a> merge(AVLArray<a> left, AVLArray<a> right) {
  if( left.get() == nullptr and right.get() == nullptr ) assert(0);
  if( left.get() == nullptr ) return right;
  if( right.get() == nullptr ) return left;
  if( left->rank - right->rank >= 2 ) {
    if( left->left->rank >= left->right->rank ) {
      return AVLArray<a>(new Node<a>(left->left, merge(left->right, right)));
    }
    else {
      return AVLArray<a>(new Node<a>(merge(left->left, left->right->left), merge(left->right->right, right)));
    }
  }
  if( left->rank - right->rank <= -2 ) {
    if( right->right->rank >= right->left->rank ) {
      return AVLArray<a>(new Node<a>(merge(left, right->left), right->right));
    }
    else {
      return AVLArray<a>(new Node<a>(merge(left, right->left->left), merge(right->left->right, right->right)));
    }
  }
  return AVLArray<a>(new Node<a>(left, right));
}

template<typename a>
std::pair<AVLArray<a>, AVLArray<a>> split(AVLArray<a> root, int k) {
  if( root.get() == nullptr ) return std::make_pair(AVLArray<a>(nullptr), AVLArray<a>(nullptr));
  if( k == 0 ) return std::make_pair(AVLArray<a>(nullptr), root);
  if( k == root->n ) return std::make_pair(root, AVLArray<a>(nullptr));
  assert( root->n != 1 );
  if( k <= root->left->n ) {
    auto s = split(root->left, k);
    return std::make_pair(s.first, merge(s.second, root->right));
  }
  else {
    auto s = split(root->right, k - root->left->n);
    return std::make_pair(merge(root->left, s.first), s.second);
  }
}

template<typename a>
AVLArray<a> newNode(a v) {
  return AVLArray<a>(new Node<a>(v));
}

