class NodeHeap {
public:
  std::vector<Node*> xss;
  int n;
  NodeHeap() : n(262144) {}
  Node* next() {
    if( n == 262144 ) {
      n = 0;
      Node *p = new Node[262144];
      xss.push_back(p);
    }
    return &xss[xss.size()-1][n++];
  }
};
NodeHeap nheap;

Node* initLeaf(int v) {
  //Node *res = new Node;
  Node *res = nheap.next();
  res->left = res->right = nullptr;
  res->num = 1;
  res->value = v;
  res->min = v;
  return res;
}

Node* initNode(Node* base, Node* left, Node* right) {
#ifdef Persistent
  //Node *res = new Node;
  Node *res = nheap.next();
#else
  Node *res = base != nullptr ? base : nheap.next();
#endif
  res->left = left;
  res->right = right;
  res->num = 0;
  res->value = 0;
  res->min = (1 << 30);
  return res;
}

bool isLeaf(Node* p) {
  if( p == nullptr ) return false;
  return p->left == nullptr and p->right == nullptr;
}

int getNum(Node* p) {
  if( p == nullptr ) return 0;
  if( isLeaf(p) ) return 1;
  return p->num;
}

Node* getLeft(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->left;
}

Node* getRight(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->right;
}

