struct RBST_node{
	int val,mv,size;
	RBST_node *l_child,*r_child;

	RBST_node(int v){
		val=mv=v;
		size=1;
		l_child=r_child=NULL;
		srand(time(NULL));
	}
};
typedef pair<RBST_node*, RBST_node*> P;

RBST_node* update(RBST_node* x){
	x->size = 1;
	x->mv = x->val;
	if(x->l_child){
		x->size += x->l_child->size;
		x->mv = min(x->mv,x->l_child->mv);
	}
	if(x->r_child){
		x->size += x->r_child->size;
		x->mv = min(x->mv,x->r_child->mv);
	}
	return x;
}

RBST_node* merge(RBST_node* x, RBST_node* y){
	if(!x) return y;
	if(!y) return x;

	int m=x->size, n=y->size;
	if(rand() % (m+n) < m){
		x->r_child = merge(x->r_child,y);
		return update(x);
	}else{
		y->l_child = merge(x,y->l_child);
		return update(y);		
	}
}

int node_size(RBST_node* x){
	if(!x) return 0;
	else return x->size;
}

//[,pos) [pos,)????????¢????????????
P split(RBST_node* x,int pos){
	if(!x) return P(NULL,NULL);
	if(node_size(x->l_child)<pos){
		P tmp = split(x->r_child,pos-node_size(x->l_child)-1);
		x->r_child = tmp.first;
		return P(update(x),tmp.second);
	}else{
		P tmp = split(x->l_child,pos);
		x->l_child = tmp.second;
		return P(tmp.first,update(x));
	}
}

RBST_node* insert(RBST_node* x,int val,int pos){
	RBST_node *p = new RBST_node(val);
	P tmp = split(x,pos);
	RBST_node *l = merge(tmp.first,p),*r=tmp.second;
	return merge(l,r); 
}

RBST_node* erase(RBST_node *x,int pos){
	P tmp = split(x,pos);
	RBST_node *l =tmp.first;
	RBST_node *r = split(tmp.second,1).second;
	return merge(l,r);
}

