const int INF = 1001001001;
int main() {
    TreapArray<int, INF> a;
    int n, q;
    cin >> n >> q;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        a.push_back(x);
    }

    auto rotate = [&](int L, int R) {
        int len = R - L + 1;
        Treap<int, INF>::Node *l, *m1, *m2, *r;
        tie(l, r) = a.split(a.root, L);
        tie(m1, r) = a.split(r, len);
        tie(m1, m2) = a.split(m1, len - 1);
        m1 = a.merge(m2, m1);
        r = a.merge(m1, r);
        a.root = a.merge(l, r);
    };

    while (q--) {
        int x, y, z;
        cin >> x >> y >> z;
        if (x == 0) {
            rotate(y, z);
        } else if (x == 1) {
            cout << a.query(y, z + 1) << endl;
        } else {
            a.change(y, z);
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int INF=1001001001;

struct RBST{
    struct node{
        int val,cnt,mi;
        node *left,*right;
        node(int val):val(val),cnt(1),mi(val){
            left=right=NULL;
        }
    };

    RBST():root(NULL){srand((unsigned)time(NULL));}

    inline int cnt(node *t){return t?t->cnt:0;}
    inline int mi(node *t){return t?t->mi:INF;}

    node *update(node *t){
        if(t==NULL)return NULL;
        t->cnt=cnt(t->left)+cnt(t->right)+1;
        t->mi=min(min(mi(t->left),mi(t->right)),t->val);
        return t;
    }

    node *root;

    node *merge(node *l,node *r){
        if(!l||!r)return l?l:r;
        int tmp=cnt(l)+cnt(r);
        if(rand()%tmp<cnt(l)){
            l->right=merge(l->right,r);
            return update(l);
        }
        else{
            r->left=merge(l,r->left);
            return update(r);
        }
    }

    pair<node *,node *>split(node *t,int k){//[0,k) [k,n)
        if(!t)return make_pair((node *)NULL,(node *)NULL);
        if(k<=cnt(t->left)){
            pair<node *,node *>s=split(t->left,k);
            t->left=s.second;
            return make_pair(s.first,update(t));
        }
        else{
            pair<node *,node *>s=split(t->right,k-cnt(t->left)-1);
            t->right=s.first;
            return make_pair(update(t),s.second);
        }
    }

    node  *insert(node *t,int k,int val){
        pair<node *,node *>s=split(t,k);
        t=merge(s.first,new node(val));
        t=merge(t,s.second);
        return t;
    }

    node *erase(node *t,int k){
        pair<node *,node *>s1,s2;
        s1=split(t,k-1);
        s2=split(s1.second,1);
        return merge(s1.first,s2.second);
    }

    int getMin(node *t,int l,int r){
        if(r<=0||cnt(t)<=l)return INF;
        if(l<=0&&cnt(t)<=r)return mi(t);

        int vl=getMin(t->left,l,r);
        int vr=getMin(t->right,l-cnt(t->left)-1,r-cnt(t->left)-1);
        int res=min(vl,vr);
        if(l<=cnt(t->left)&&cnt(t->left)<r)res=min(res,t->val);
        return res;
    }

    void insert(int k,int val){root=insert(root,k,val);}
    void erase(int k){root=erase(root,k);}

    void quary0(int l,int r){
        pair<node *,node *>s1,s2,s3;
        s1=split(root,l);//[0,l),[l,n)
        s2=split(s1.second,r-l-1);
        s3=split(s2.second,1);

        root=merge(s1.first,s3.first);
        root=merge(root,s2.first);
        root=merge(root,s3.second);
    }

    int quary1(int l,int r){
        return getMin(root,l,r);
    }

    void quary2(int k,int x){
        erase(k);
        insert(k,x);
    }

    void debug(node *t){
        if(!t)return;
        debug(t->left);
        printf("%d ",t->val);
        debug(t->right);
    }
    void debug(){debug(root);puts("");}
};

RBST T;
