        static T min_(node* t) { return t ? t->min_val : std::numeric_limits<T>::max(); }
        static node* update(node *t) {
            node* l = t->left; node* r = t->right;
            t->st_size = size(l) + size(r) + 1;
            t->min_val = min({min_(l), min_(r), t->val});
