int main() {
  int n, q;
  scanf("%d %d", &n, &q);
  vector< int > v(n);
  for(int i = 0; i < n; i++) scanf("%d", &v[i]);

  auto f = [](int a, int b) { return min(a, b); };
  const int INF = 1 << 30;
  RedBlackTree< int, int > rbt(5000000, f, INF);
  auto root = rbt.build(v);
  for(int i = 0; i < q; i++) {
    int x, y, z;
    scanf("%d %d %d", &x, &y, &z);
    if(x == 0) {
      int v = rbt.query(root, z, z + 1);
      rbt.erase(root, z);
      rbt.insert(root, y, v);
    } else if(x == 1) {
      printf("%d\n", rbt.query(root, y, z + 1));
    } else if(x == 2) {
      rbt.set_element(root, y, z);
    }
  }
}

