void update(Node * t){
    t->cnt = count(t->ch[0]) + count(t->ch[1]) + 1;
    t->sum = sum(t->ch[0]) + sum(t->ch[1]) + t->val;
    t->min = min({ min(t->ch[0]), min(t->ch[1]), t->val });
}

Node * merge(Node * l, Node * r){
    if(l == np || r == np) return l == np ? r : l;
    if(l->pri > r->pri){
        l->ch[1] = merge(l->ch[1],r);
        update(l);
        return l;
    } else {
        r->ch[0] = merge(l,r->ch[0]);
        update(r);
        return r;
    }
}

pair<Node*,Node*> split(Node * t, int k){
    if(t == np) return make_pair(np,np);
    if(k <= count(t->ch[0])){
        auto s = split(t->ch[0],k);
        t->ch[0] = s.second;
        update(t);
        return make_pair(s.first, t);
    } else {
        k -= count(t->ch[0]) + 1;
        auto s = split(t->ch[1],k);
        t->ch[1] = s.first;
        update(t);
        return make_pair(t,s.second);
    }
}

Node * erase(Node * t, int k){
    Node *l,*m,*r;
    tie(l,m) = split(t,k);
    tie(m,r) = split(m,1);
    //delete m;
    return merge(l,r);
}

Node * at(Node * t, int k){
    int lc = count(t->ch[0]);
    if(k < lc) return at(t->ch[0],k);
    else if(k == lc) return t;
    else return at(t->ch[1], k-lc-1);
}

void set(Node * t, int k, int x){
    int lc = count(t->ch[0]);
    if(k < lc) set(t->ch[0], k, x);
    else if(k == lc) t->val = x;
    else if(k > lc) set(t->ch[1], k-lc-1, x);
    update(t);
}

Node * insert(Node * t, int k, int v){
    Node *l,*m = new Node(v,xor128()), *r;
    tie(l,r) = split(t,k);
    return merge(merge(l,m),r);
}

int min(Node * t, int l, int r){
    if(r - l <= 0) return inf;
    if(r - l == count(t)) return min(t);
    int lc = count(t->ch[0]);
    if(l == lc && r - lc == 1) return t->val;
    int res = inf;
    if(l < lc) res = min(res, min(t->ch[0], l, min(lc,r)));
    if(l <= lc && lc < r) res = min(res, min(t, lc, lc+1));
    if(lc+1 < r) res = min(res, min(t->ch[1], max(0,l-lc-1), r-lc-1));
    return res;
}

