/*
verify: http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3177198#1

template<ValueMonoid, OperatorMonoid, Modifier>
class Treap

ValueMonoid
	- 役割
		- 扱う要素の値
	-	要求
		- value_type
		- identity() -> value_type : 単位元を返す
		- operation(value_type, value_type) -> value_type : 演算結果を返す

OperatorMonoid
	- 役割
		- 扱う要素に適用させる値
	- 要求
		- value_type
		- identity() -> value_type : 単位元を返す
		- operation(value_type, value_type) -> value_type : 作用素を結合する

Modifier<ValueMonoid, OperatorMonoid>
	- 役割
		- OperatorMonoidをValueMonoidに適用させる
	- 要求
		- operation(value_type, operator_type, size_type) -> value_type
			: (size)個の要素の結合に作用素を適用させた結果を返す

Treap
	- 提供
		- query(size_type l, size_type r) -> value_type
			- 計算量 O(log N)
			- [l, r)までの計算結果

		- update(size_type l, size_type r, operator_type x)
			- 計算量 O(log N)
			- [l, r)にxを適用させた結果に変更する

		- insert(size_type k, value_type v)
			- 計算量 O(log N)
			- k番目にvを挿入する

		- erase(size_type k)
			- 計算量 O(log N)
			- k番目の要素を削除する

		- dump(size_type l, size_type r) -> vector<value_type>
			- 計算量 O(| [l, r) |)
			- [l, r)の要素を列として返す

		- insert_from_iterator(InputIterator first, InputIterator last, size_type k)
			- 計算量 O((last-first) log N)
			- iteratorのfirstからlastまでの要素をk番目から挿入する
			- kが未指定の場合は末尾

		- kth_element(size_type k) -> value_type
			- 計算量 O(log N)
			- k番目の要素を返す


		* 未実装
		- search(function f) -> size_type
			- 計算量 O(log N)?
			- f([0, k)) is true and f([0, k+1)) is falseとなるkを返す
*/

#include<bits/stdc++.h>
using namespace std;

template<class T>
struct node{
  T val;
  T acm;
  inline T f(T a,T b){return a<=b?a:b;};
  size_t sz;
  node *parent,*left,*right;
  node():parent(nullptr),left(nullptr),right(nullptr),sz(1){}
  node(T const& v):val(v),parent(nullptr),left(nullptr),right(nullptr),sz(1){}
  int state(){
      if(!this->parent)return 0;
      if(this->parent->left==this)return 1;
      if(this->parent->right==this)return -1;
      return 0;
  }
  void rotate(){
      node<T> *pp,*p,*c;
      p = this->parent;
      pp = p->parent;
      if(p->left==this){
        c = this->right;
        this->right = p;
        p->left = c;
      }else{
        c = this->left;
        this->left = p;
        p->right = c;
      }
      if(pp && pp->left==p)pp->left = this;
      if(pp && pp->right==p)pp->right = this;
      this->parent = pp;
      p->parent = this;
      if(c)c->parent = p;
      p->update();
      this->update();
  }
  void splay(){
      while(this->state()!=0){
        if(this->parent->state()==0){
          this->rotate();
        }
        else if(this->state()==this->parent->state()){
          this->parent->rotate();
          this->rotate();
        }
        else{
          this->rotate();
          this->rotate();
        }
      }
  }
  void update(){
    this->sz = 1;
    this->acm = this->val;
    if(this->left){
      this->sz += this->left->sz;
      acm = f(acm,this->left->acm);
    }
    if(this->right){
      this->sz += this->right->sz;
      acm = f(acm,this->right->acm);
    }
  }
};

template<class T>
node<T>* get(int k,node<T>* root){
  node<T>* tmp = root;
  while(1){
    int lsz = tmp->left?tmp->left->sz:0;
    if(k<lsz){
      tmp = tmp->left;
    }
    if(k==lsz){
      tmp->splay();
      return tmp;
    }
    if(k>lsz){
      tmp = tmp->right;
      k = k-lsz-1;
    }
  }
}

template<class T>
node<T>* merge(node<T>* lroot,node<T>* rroot){
  if(!lroot)return rroot;
  if(!rroot)return lroot;
  lroot = get(lroot->sz-1,lroot);
  lroot->right = rroot;
  rroot->parent = lroot;
  lroot->update();
  return lroot;
}

template<class T>
pair<node<T>*,node<T>*> split(int left_cnt,node<T>* root){
  if(left_cnt==0)return make_pair(nullptr,root);
  if(left_cnt==root->sz)return make_pair(root,nullptr);
  root = get(left_cnt,root);
  node<T> *lroot,*rroot;
  lroot = root->left;
  rroot = root;
  rroot->left = nullptr;
  lroot->parent = nullptr;
  rroot->update();
  return make_pair(lroot,rroot);
}

template<class T>
node<T>* insert(int k,node<T>* tmp,node<T>* root){
  auto trees = split(k,root);
  node<T>* lroot = trees.first;
  node<T>* rroot = trees.second;
  return merge(merge(lroot,tmp),rroot);
}

template<class T>
pair<node<T>*,node<T>*> erase(int k,node<T>* root){
  root = get(k,root);
  node<T>* lroot = root->left;
  node<T>* rroot = root->right;
  if(lroot)lroot->parent = nullptr;
  if(rroot)rroot->parent = nullptr;
  root->left = nullptr;
  root->right = nullptr;
  root->update();
  return make_pair(merge(lroot,rroot),root);
}

template<class T>
node<T>* shift(int l,int r,node<T>* root){
  auto tmp = erase(r,root);
  root = tmp.first;
  node<T>* n = tmp.second;
  return insert(l,n,root);
}

template<class T>
pair<node<T>*,T> rmq(int l,int r,node<T>* root){
  node<T> *lroot,*croot,*rroot;
  auto tmp = split(r+1,root);
  rroot = tmp.second;
  tmp = split(l,tmp.first);
  lroot = tmp.first;
  croot = tmp.second;
  T res = croot->acm;
  return make_pair(merge(merge(lroot,croot),rroot),res);
}

