typedef pair<int,int> pii;
typedef vector<pii> vp;
typedef vector<int> vi;

//Segment Tree for Range Minimum Query
class SegmentTree{
  int n;
  vp node;
public:
  SegmentTree(int n_){
    n=1;
    while(n<n_)n*=2;
    node = vp(2*n-1);
  }

  SegmentTree(vector<int> a){
    int n_ = a.size();
    n=1;
    while(n<n_)n*=2;
    node.resize(2*n-1, pii(1e9, 1e9));
    for(int i=0;i<n_;i++)node[n-1+i] = pii(a[i],i);
    for(int i=n-2;i>=0;i--)node[i] = min(node[2*i+1], node[2*i+2]);
  }

  void update(int k, int v){
    int cur = k + n-1;
    node[cur] = pii(v,k);
    while(cur>0){
      cur = (cur-1)/2;
      node[cur] = min(node[cur*2+1],node[cur*2+2]);
    }
  }

  //return minimum value in [a,b). ( [l,r) is interval in which k is.)
  pii RMQ(int a,int b,int k=0,int l=0,int r=0){
    if(l>=r)r = n;
    if(r<=a || b<=l)return pii(1e9,1e9);
    if(a<=l && r<=b)return node[k];
    pii vl = RMQ(a,b,2*k+1,l,(l+r)/2);
    pii vr = RMQ(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
  }
};

struct FenwickTree{
  int n;
  vector<int> bit;
  FenwickTree(int x = 0):n(x){bit = vector<int>(x+1,0);}

  inline void add(int i, int x){
    i++;
    int cnt=0;
    while(i <= n){
      bit[i] += x;
      i += i & -i;
      assert(cnt++<100);
    }
  }

  inline int sum(int i){
    i++;
    int res = 0;
    int cnt=0;
    while(i > 0){
      res += bit[i];
      i -= i & -i;
      assert(cnt++<100);
    }
    return res;
  }
};

int main(){
  int n,q;
  scanf("%d%d",&n,&q);

  vi a(n),x(q),y(q),z(q);
  rep(i,n)scanf("%d",&a[i]);
  vi cnt(n,0);
  rep(i,q){
    scanf("%d%d%d",&x[i],&y[i],&z[i]);
    if(x[i]==0)cnt[y[i]]++;
  }

  vi id(n);
  int len = 0;
  rep(i,n){
    len += cnt[i];
    id[i] = len;
    len++;
  }

  FenwickTree bit(len);
  rep(i,q){
    if(x[i]==0){
      z[i] = id[z[i]] + bit.sum(id[z[i]]);
      bit.add(id[y[i]],-1);
      y[i] = id[y[i]] + bit.sum(id[y[i]]);
      bit.add(id[z[i]]+1,+1);
    }else if(x[i] == 1){
      y[i] = id[y[i]] + bit.sum(id[y[i]]);
      z[i] = id[z[i]] + bit.sum(id[z[i]]);
    }else{
      y[i] = id[y[i]] + bit.sum(id[y[i]]);
    }
  }      

  vi v(len,1e9);
  rep(i,n)v[id[i]] = a[i];

  SegmentTree st(v);
  rep(i,q){
    if(x[i] == 0){
      st.update(y[i],v[z[i]]);
      st.update(z[i],1e9);
      v[y[i]] = v[z[i]]; v[z[i]] = 1e9;
    }else if(x[i] == 1){
      printf("%d\n",st.RMQ(y[i],z[i]+1).first);
    }else{
      st.update(y[i],z[i]);
      v[y[i]] = z[i];
    }
  }
}

