using namespace std;
struct Tree{
	Tree(int v){
		size = 1;
		min = val = v;
		l = r = 0;
		index = 0;	
	}
	Tree(){};
	int val, size, min, index;
	Tree *l, *r;
};

#define INF (1<<30)
typedef pair<Tree*, Tree*> PTree;
Tree *root;

int size(Tree *a){
	return a?a->size:0;
}

int minimum(Tree *a){
	return a?a->min:INF;
}

Tree* update(Tree *a){
	if(a == 0)return 0;
	a->size = size(a->r) + size(a->l) + 1;
	a->min = min(a->val, min(minimum(a->r), minimum(a->l)));
	a->index = size(a->l);
	return a;
}

Tree *merge(Tree *a, Tree *b){
	int p = size(a), q = size(b);
	if(p == 0)return b;
	if(q == 0)return a;
	if(rand()%(p+q) < p){
		Tree *tmp = merge(a->r, b);
		a->r = tmp;
		return update(a);
	}
	else{
		Tree *tmp = merge(a, b->l);
		b->l = tmp;
		return update(b);
	}

}

PTree split(Tree *a, int pos){
	if(pos == 0)return PTree(0, a);
	if(size(a) == pos)return PTree(a, 0);
	if(size(a->l) < pos){
		PTree tmp = split(a->r, pos - 1 - size(a->l));
		a->r = tmp.first;
		tmp.first = update(a);
		return tmp;
	}
	else{
		PTree tmp = split(a->l, pos);
		a->l = tmp.second;
		tmp.second = update(a);
		return tmp;
	}
}

Tree *insert(Tree *a, int pos, int val){
	PTree tmp = split(a, pos);
	tmp.first = merge(tmp.first, new Tree(val));
	return merge(tmp.first, tmp.second);
}

Tree *erase(Tree *a, int pos){
	PTree tmp = split(a, pos);
	return merge(tmp.first, split(tmp.second, 1).second);
}

int minval(Tree *a, int left, int right){
	if(left <= 0 && size(a) <= right)return minimum(a);
	if(right <= 0 || size(a) <= left)return INF;
	int lmin = minval(a->l, left, right);
	int rmin = minval(a->r, left - size(a->l) - 1, right - size(a->l) - 1);
	int res = min(lmin, rmin);
	if(left <= a->index && a->index < right)res = min(a->val, res);
	return res;
}

Tree *changeval(Tree *a, int pos, int val){
	if(a->index == pos){
		a->val = val;
	}
	if(a->index < pos){
		changeval(a->r, pos - size(a->l) - 1, val);
	}
	if(a->index > pos){
		changeval(a->l, pos, val);
	}
	return update(a);
}

int value(Tree *a, int pos){
	if(a->index == pos){
		return a->val;
	}
	if(a->index < pos){
		return value(a->r, pos - size(a->l) - 1);
	}
	if(a->index > pos){
		return value(a->l, pos);
	}
}


int main(){
	int n, q, num, x, y, z;
	cin >> n >> q;
	cin >> num;
	root = new Tree(num);
	for(int i = 1;i < n;i++){
		cin >> num;
		root = merge(root, new Tree(num));
	}
	for(int i = 0;i < q;i++){
		cin >> x >> y >> z;
		if(x == 0){
			int num = value(root, z);
			root = erase(root, z);
			root = insert(root, y, num);
		}
		if(x == 1){
			cout << minval(root, y, z + 1) << endl;
		}
		if(x == 2){
			root = changeval(root, y, z);
		}
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

using T = int;
const T id = INT_MAX;
T op(T l, T r) {
	return min(l, r);
}

enum COL { BLACK, RED };

struct node;
node *update(node *t);
struct node {
	T val, all;
	node *ch[2];
	COL color;
	int level;
	int size;
	node() {}
	void init(T v) {
		val = v;
		all = v;
		color = BLACK;
		level = 0;
		size = 1;
		ch[0] = ch[1] = nullptr;
	}
	void init(node *l, node *r, COL c) {
		val = id;
		color = c;
		ch[0] = l;
		ch[1] = r;
		update(this);
	}
};

const int pmax = 1e7;
node pool[pmax];
queue<int> deleted;
int it = 0;

int count(node *t) { return !t ? 0 : t->size; }

T que(node *t) { return !t ? id : t->all; }

node *update(node *t) {
	t->size = count(t->ch[0]) + count(t->ch[1]) + (!t->ch[0] || !t->ch[1]);
	t->all = op(que(t->ch[0]), op(t->val, que(t->ch[1])));
	t->level = t->ch[0] ? t->ch[0]->level + (t->ch[0]->color == BLACK) : 0;
	return t;
}

node *new_leaf(T v) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(v);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(v);
	return pool + it++;
}

node *new_node(node *l, node *r, COL c) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(l, r, c);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(l, r, c);
	return pool + it++;
}

node *rotate(node *t, int b) {
	node *s = t->ch[1 - b];
	t->ch[1 - b] = s->ch[b];
	s->ch[b] = t;
	update(t);
	return update(s);
}

node *submerge(node *l, node *r) {
	if (l->level < r->level) {
		node *c = submerge(l, r->ch[0]);
		r->ch[0] = c;
		if (r->color == BLACK && c->color == RED && c->ch[0] && c->ch[0]->color == RED) {
			if (r->ch[1]->color == BLACK) {
				r->color = RED;
				c->color = BLACK;
				return rotate(r, 1);
			}
			c->color = BLACK;
			r->ch[1]->color = BLACK;
			r->color = RED;
			return update(r);
		}
		return update(r);
	}
	if (l->level > r->level) {
		node *c = submerge(l->ch[1], r);
		l->ch[1] = c;
		if (l->color == BLACK && c->color == RED && c->ch[1] && c->ch[1]->color == RED) {
			if (l->ch[0]->color == BLACK) {
				l->color = RED;
				c->color = BLACK;
				return rotate(l, 0);
			}
			l->ch[0]->color = BLACK;
			c->color = BLACK;
			l->color = RED;
			return update(l);
		}
		return update(l);
	}
	return new_node(l, r, RED);
}

node *merge(node *l, node *r) {
	if (!l) return r;
	if (!r) return l;
	node *c = submerge(l, r);
	c->color = BLACK;
	return c;
}

pair<node*, node*> split(node *t, int k) {
	if (!t) return make_pair(nullptr, nullptr);
	if (k == 0) return make_pair(nullptr, t);
	if (k >= count(t)) return make_pair(t, nullptr);
	int c = count(t->ch[0]);
	node *l = t->ch[0], *r = t->ch[1];
	deleted.push(t - pool);
	if (k < c) {
		pair<node*, node*> p = split(l, k);
		return make_pair(p.first, merge(p.second, r));
	}
	if (k > c) {
		pair<node*, node*> p = split(r, k - c);
		return make_pair(merge(l, p.first), p.second);
	}
	return make_pair(l, r);
}

node *insert(node *t, int k, T v) {
	pair<node*, node*> s = split(t, k);
	return merge(merge(s.first, new_leaf(v)), s.second);
}

node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	return merge(s1.first, s2.second);
}

T find(node *t, int l, int r) {
	if (!t) return id;
	if (r < 0 || l >= count(t)) return id;
	if (l <= 0 && r >= t->size) return t->all;
	int c = count(t->ch[0]), d = c + (!t->ch[0] || !t->ch[1]);
	return op(!t->ch[0] ? id : find(t->ch[0], l, r), op(l <= c && c < r ? t->val : id, !t->ch[1] ? id : find(t->ch[1], l - d, r - d)));
}

node *find(node *t, int k) {
	if (!t) return t;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	return c == 0 && b ? t : k < c ? find(t->ch[0], k) : find(t->ch[1], k - c - b);
}

