template<typename T> struct RBST{
public:
	struct Node{
		T v;// 値
		int sz,mv;//部分木のサイズ,最小値
		Node *l,*r;// l,r
		Node(T v):v(v),sz(1),mv(v){
			l=r=NULL;
		}
	};

	int size(){return size(root);}
	int size(Node* t){return !t?0:t->sz;}
	T mv(Node* t){return !t?INF<T>():t->mv;}

	Node* root;
	RBST():root(NULL){};

	Node* update(Node* t){
		t->sz=size(t->l)+size(t->r)+1;
		t->mv=min(min(mv(t->l),mv(t->r)),t->v);
		return t;
	}

	Node* merge(Node* l,Node* r){
		if(!l || !r)return l?l:r;
		if(rand()%(size(l)+size(r))<size(l)){
			l->r = merge(l->r,r);
			return update(l);
		}else{
			r->l = merge(l,r->l);
			return update(r);
		}
	}

	pair<Node*,Node*> split(Node* t,int k){//[0,k) [k,n)
		if(!t)return make_pair((Node*)NULL,(Node*)NULL);
		if(k<=size(t->l)){
			auto s=split(t->l,k);
			t->l=s.second;
			return make_pair(s.first,update(t));
		}else{
			auto s=split(t->r,k - (size(t->l)+1));
			t->r=s.first;
			return make_pair(update(t),s.second);
		}
	}

	Node* insert(int k,T v){return root=insert(root,k,v);}
	Node* insert(Node* t,int k,T v){
		pair<Node*,Node*> s=split(t,k);
		t=merge(s.first,new Node(v));
		t=merge(t,s.second);
		return update(t);
	}

	Node* erase(int k){return root=erase(root,k);}
	Node* erase(Node* t,int k){
		pair<Node*,Node*> sr=split(t,k+1),sl=split(sr.first,k);	
		t = merge(sl.first,sr.second);
		return update(t);
	}

	Node* find(int k){
		Node* v=root;
		while(v){
			unsigned cl=size(v->l);
			if(k==cl)return v;
			else if(k<cl) v=v->l;
			else {
				v=v->r;
				k -= cl+1;
			}
		}
		return v;
	}

	Node* shift(int l,int r){
		pair<Node*,Node*> s1,s2,s3;
		s3=split(root,r);s2=split(s3.first,r-1);s1=split(s2.first,l);
		return root=update(merge(merge(merge(s1.first,s2.second),s1.second),s3.second));
	}

	T query(int l,int r){return query(l,r,root);}

	T query(int l,int r,Node* t){
		int sz=size(t);
		if(sz<=l || r<=0)return INF<T>();
		if(l<=0 && sz<=r)return mv(t);

		int c=size(t->l);
		T res=min(query(l,r,t->l),query(l-c-1,r-c-1,t->r));
		if(l<=c && c < r)res=min(res,t->v);
		return res;
	}
};


class Main{
	public:
	void run(){
		int n,q;
		RBST<int> t;

		cin >> n >> q;
		REP(i,n){
			int a;cin >> a;t.insert(i,a);
		}

