using key_t = int;
const key_t INF = 1000000000;
const int MAX_N = 5000010;
enum { L, R };
struct node {
  key_t key;
  node *ch[2];
  int size;
  key_t min;

  static node *const nil;

  node() : node(0) {}

  node(const key_t &x) : key(x), size(1), min(x) { ch[L] = ch[R] = node::nil; }

  node(node *left_, node *right_, int size_, const key_t &min_)
      : size(size_), min(min_) {
    ch[L] = left_;
    ch[R] = right_;
  }

  void *operator new(std::size_t) {
    static node pool[MAX_N];
    static int p = 0;
    return pool + p++;
  }

  bool is_leaf() const { return size == 1; }
};

using np = node *;
using cnp = const node *;
using npair = std::pair<np, np>;

node *const node::nil = new node(nullptr, nullptr, 0, INF);

struct rbst {
  np root;

  rbst() : root(node::nil) {}

  rbst(np root_) : root(root_) {}

  rbst(key_t *left, key_t *right) : root(make_tree(left, right)) {}

  np make_tree(key_t *left, key_t *right) {
    int sz = right - left;
    key_t *mid = left + sz / 2;
    if (sz == 0) {
      return node::nil;
    } else if (sz == 1) {
      return new node(*mid);
    } else {
      np lc = make_tree(left, mid);
      np rc = make_tree(mid, right);
      return new node(lc, rc, sz, std::min(lc->min, rc->min));
    }
  }

  int size() const { return root->size; }

  void set(int k, const key_t &x) { set(root, k, x); }

  void set(np n, int k, const key_t &x) {
    if (n->is_leaf()) {
      n->key = n->min = x;
    } else {
      if (k < n->ch[L]->size)
        set(n->ch[L], k, x);
      else
        set(n->ch[R], k - n->ch[L]->size, x);
      update(n);
    }
  }

  key_t get(cnp n, int k) const {
    if (n->size == 1)
      return n->key;
    else if (k < n->ch[L]->size)
      return get(n->ch[L], k);
    else
      return get(n->ch[R], k - n->ch[L]->size);
  }

  key_t range_min(int l, int r) const { return range_min(root, l, r); }

  key_t range_min(cnp n, int l, int r) const {
    l = std::max(l, 0);
    r = std::min(r, n->size);
    if (l >= r)
      return INF;
    if (l == 0 && r == n->size)
      return n->min;
    key_t res = INF;
    int sl = n->ch[L]->size;
    res = std::min(res, range_min(n->ch[L], l, r));
    res = std::min(res, range_min(n->ch[R], l - sl, r - sl));
    return res;
  }

  // ???????????????????????¨??¢??°??§??¨???????????¶???????????\??????
  np merge(np l, np r) const {
    return l == node::nil ? r : r == node::nil ? l : merge_sub(l, r);
  }

  // ???????????????????????????
  np merge_sub(np l, np r) const {
    // size???????????°????????§?????¨??????????????°??????????????????-1??????
    int sl = l->size - 1, sr = r->size - 1;
    int rand = xor128() % (sl + 1 + sr);
    if (rand < sl) {
      l->ch[R] = merge_sub(l->ch[R], r);
      return update(l);
    } else if (rand == sl) { // ?????????????????¨????????????
      return new node(l, r, l->size + r->size, std::min(l->min, r->min));
    } else {
      r->ch[L] = merge_sub(l, r->ch[L]);
      return update(r);
    }
  }

  // ???????????????????????¨??¢??°??§??¨???????????¶???????????\??????
  npair split(np n, int k) const {
    return n == node::nil ? npair(node::nil, node::nil) : split_sub(n, k);
  }

  // ???????????????????????????
  npair split_sub(np n, int k) const {
    if (n->is_leaf()) {
      return k == 0 ? npair(node::nil, n) : npair(n, node::nil);
    } else if (k < n->ch[L]->size) {
      npair p = split_sub(n->ch[L], k);
      n->ch[L] = p.second;
      return npair(p.first, update(n));
    } else if (k == n->ch[L]->size) {
      return npair(n->ch[L], n->ch[R]);
    } else {
      npair p = split_sub(n->ch[R], k - n->ch[L]->size);
      n->ch[R] = p.first;
      return npair(update(n), p.second);
    }
  }

  np update(np n) const {
    assert(!n->is_leaf());
    n->size = n->ch[L]->size + n->ch[R]->size;
    n->min = std::min(n->ch[L]->min, n->ch[R]->min);
    return n;
  }

  void shift_split_merge(int l, int r) {
    np a, b, c, d;
    std::tie(a, b) = split(root, l);
    std::tie(b, c) = split(b, r - l);
    std::tie(c, d) = split(c, 1);
    np ac = merge(a, c);
    np bd = merge(b, d);
    root = merge(ac, bd);
  }
};

