class Splay_Tree{
	private:
	int n;
	vi L,R,par,val,date,sub;
	void Fix(int k){
		sub[k]=sub[L[k]]+sub[R[k]]+1;
	date[k]=min({val[k],date[L[k]],date[R[k]]});
	}
	void Set(int k,int l,int r,int p,bool B=0){
		if(B) swap(l,r);
		L[k]=l;R[k]=r;par[k]=p;
		if(l!=n) par[l]=k;
		if(r!=n) par[r]=k;
		Fix(k);
	}
	void Clear(int v){
		L[v]=R[v]=par[v]=n;
		val[v]=date[v]=inf;
		sub[v]=1;
	}
	int Ch(int v,bool B){return (B?R[v]:L[v]);}
	int Splay(int u){
		while(par[u]!=n){
			int v=par[u],w=par[v];
			bool A=(R[v]==u),B=(R[w]==v);
			if(w==n){
				Set(v,Ch(u,!A),Ch(v,!A),u,A);
				Set(u,Ch(u,A),v,n,A);
				continue;
			}
			int w_=par[w];
			if(w_!=n){
				if(L[w_]==w) L[w_]=u;
				else R[w_]=u;
			}
			if(A^B){
				Set(w,Ch(w,A),Ch(u,A),u,A);
				Set(v,Ch(u,!A),Ch(v,!A),u,A);
				Set(u,w,v,w_,A);
			}
			else{
				Set(w,Ch(v,!A),Ch(w,!A),v,A);
				Set(v,Ch(u,!A),w,u,A);
				Set(u,Ch(u,A),v,w_,A);
			}
		}
	}
	public:
	Splay_Tree(int N){
		n=N;
		L=R=par=vi(n+2,n);
		val=date=vi(n+2,inf);
		sub=vi(n+2,1);
		sub[n]=0;
		for(int i=1;i<n;i++) Set(i,i-1,n,i+1);
	}
	int Find(int v,int k){
		Splay(v);
		while(1){
			int t=sub[L[v]];
			if(t==k) break;
			if(k<t) v=L[v];
			else k-=t+1,v=R[v];
		}
		Splay(v);
		return v;
	}
	void Update(int k,int x){
		k=Find(0,k);
		val[k]=x;date[k]=min(date[k],x);
	}
	int Sub(int v){
		Splay(v);
		return sub[v];
	}
	void Insert(int v,int k,int id){
//		cout<<v<<' '<<k<<' '<<id<<endl;
		int N=Sub(v);
		if(!k||k==N){
			k=Find(v,(k?k-1:0));
			Set(id,n,k,n,k);
			return;
		}
		int l=Find(v,k-1),r=Find(v,k);
		Splay(l);Splay(r);
//		cout<<l<<' '<<r<<endl;
		par[l]=par[r]=id;
		Set(r,n,R[r],id);
		Set(id,l,r,n);
	}
	void Erase(int v,int k){
		if(!k){
			Clear(Find(v,k));
			return;
		}
		int l=Find(v,k-1),r=Find(v,k);
		Splay(l);Splay(r);
		if(R[r]!=n) par[R[r]]=l;
		Set(l,L[l],R[r],n);
		Clear(r);
	}
	void Erase_id(int v){
		Splay(v);
		Erase(v,sub[L[v]]);
	}
	void Merge(int l,int r){
//		cout<<l<<' '<<r<<endl;
		Splay(l);Splay(r);
		Set(n+1,l,r,n);
		Erase(l,sub[l]);
//		for(int i=0;i<n+2;i++) Open(i);
//		cout<<endl;
	}
	int Split(int v,int k){
		Insert(v,k,n+1);
//		cout<<v<<' '<<k<<endl;
//		for(int i=0;i<n+2;i++) Open(i);
//		cout<<endl;
		int t=Find(v,k+1);
//		for(int i=0;i<n+2;i++) Open(i);
//		cout<<endl;
		Splay(n+1);
		if(L[n+1]!=n) par[L[n+1]]=n;
		if(R[n+1]!=n) par[R[n+1]]=n;
		Clear(n+1);
//		for(int i=0;i<n+2;i++) Open(i);
//		cout<<endl;
//		cout<<t<<"!!!!"<<endl;
		return t;
	}
	int Query(int l,int r){
		if(l>=r) return inf;
		l=Find(0,l);if(r!=n) r=Find(0,r);
		Splay(l);if(r!=n) Splay(r);
		return min(val[l],date[R[l]]);
	}
	void Open(int v){
		cout<<v<<':'<<(L[v]==n?-1:L[v])<<' '<<(R[v]==n?-1:R[v])<<' '<<(par[v]==n?-1:par[v])<<' '<<sub[v]<<' '<<val[v]<<' '<<date[v]<<endl;
	}
};

