using namespace std;

#define INF (1 << 30)

struct treap_n{
  int value, pri, minimum, count;
  treap_n* right, *left;
  treap_n(int v){
    value = v;
    pri = rand() % INF;
    count = 1;
    minimum = v;
    right = left = 0;
  }
};

int node_count(const treap_n* r){
  if(r == 0)return 0;
  return r -> count;
}


int node_min(const treap_n* r){
  if(r == 0)return INF;
  return r -> minimum;
}

treap_n* update(treap_n* r){
  r -> count = node_count(r -> left) + node_count(r -> right) + 1;
  r -> minimum = min(node_min(r -> left), node_min(r -> right));
  r -> minimum = min(r -> minimum, r -> value);
  return r;
}

treap_n* merge(treap_n* a, treap_n *b){
  if(a == 0)return update(b);
  if(b == 0)return update(a);
  if(a -> pri > b -> pri){
    treap_n* tmp = a -> right;
    a -> right = merge(tmp, b);
    return update(a);
  }
  else{
    treap_n* tmp = b -> left;
    b -> left = merge(a, tmp);
    return update(b);
  }
}

pair<treap_n*, treap_n*> split(treap_n* r,int pos){
  if(r == 0) return make_pair((treap_n*)0, (treap_n*)0);
  int left_count = node_count(r -> left);
  if(pos > left_count){
    pair<treap_n*, treap_n*> tmp;
    tmp = split(r -> right, pos - left_count - 1);
    r -> right = tmp.first;
    return make_pair(update(r), tmp.second);
  }
  else{
    pair<treap_n*, treap_n*> tmp;
    tmp = split(r -> left, pos);
    r -> left = tmp.second;
    return make_pair(tmp.first, update(r));
  }
}

treap_n* insert(treap_n* r, int pos, treap_n* n){
  pair<treap_n*, treap_n*>tmp;
  tmp = split(r, pos - 1);
  r = merge(tmp.first, n);
  r = merge(r, tmp.second);
  return r;
}

treap_n* remove(treap_n* r,int pos){
  pair<treap_n*, treap_n*>tmp;
  tmp = split(r, pos - 1);
  r = merge(tmp.first, split(tmp.second, 1).second);
  return r;
} 

treap_n* node(treap_n* r, int pos){
  int left_count = node_count(r -> left);
  if(pos == left_count + 1){
    return r;
  }
  if(pos > left_count){
    return node(r -> right, pos - left_count - 1);
  }
  else{
    return node(r -> left, pos);
  }
}

treap_n* shift(treap_n* r, int left, int right){
  treap_n* tmp = node(r, right);
  r = remove(r, right);
  r = insert(r, left, tmp);
  return r;
}

int minimum(treap_n* r, int left, int right){
  pair<treap_n*, treap_n*> tmp1, tmp2 ;
  int res;
  tmp1 = split(r, left - 1);
  tmp2 = split(tmp1.second , right - left + 1);
  res = node_min(tmp2.first);
  r = merge(tmp1.first, merge(tmp2.first, tmp2.second));
  return res;
}

treap_n* change(treap_n* r, int pos, int val){
  r = remove(r, pos);
  r = insert(r, pos, new treap_n(val));
  return r;
}



int main(){
  int tmp, n, q, x, y, z;
  srand((unsigned int)time(0));
  cin >> n >> q;
  cin >> tmp;
  treap_n root(tmp);
  treap_n* r = &root;
  for(int i = 2;i <= n;i++){
    cin >> tmp;
    r = insert(r, i, new treap_n(tmp));
  }
  for(int i = 0;i < q;i++){
    cin >> x >> y >> z;
    if(x == 0){
      y++,z++;
      r = shift(r, y, z);
    }
    if(x == 1){
      y++,z++;
      cout << minimum(r, y, z) << endl;
    }
    if(x == 2){
      y++;
      r = change(r, y, z);
    }
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct RMQ {
	using type = int;
	static type id() { return INT_MAX; }
	static type op(type l, type r) { return min(l, r); }
};

template <typename M>
class avl_tree {
	using T = typename M::type;
	struct node {
		T val, all;
		node *ch[2];
		int dep, size;
		node(T v, node* l = nullptr, node* r = nullptr)
			: val(v), all(v), ch{ l, r }, dep(1), size(1) {}
	};
	int depth(node *t) const { return t ? t->dep : 0; }
	int count(node *t) const { return t ? t->size : 0; }
	T que(node *t) const { return t ? t->all : M::id(); }
	node *update(node *t) {
		t->dep = max(depth(t->ch[0]), depth(t->ch[1])) + 1;
		t->size = count(t->ch[0]) + 1 + count(t->ch[1]);
		t->all = M::op(que(t->ch[0]), M::op(t->val, que(t->ch[1])));
		return t;
	}
	node *rot_l(node *t) {
		node *s = t->ch[1];
		t->ch[1] = s->ch[0];
		s->ch[0] = t;
		update(t);
		return update(s);
	}
	node *rot_r(node *t) {
		node *s = t->ch[0];
		t->ch[0] = s->ch[1];
		s->ch[1] = t;
		update(t);
		return update(s);
	}
	node *fix(node *t) {
		if (!t) return t;
		if (depth(t->ch[0]) - depth(t->ch[1]) == 2) {
			if (depth(t->ch[0]->ch[1]) > depth(t->ch[0]->ch[0])) {
				t->ch[0] = rot_l(t->ch[0]);
			}
			t = rot_r(t);
		}
		else if (depth(t->ch[0]) - depth(t->ch[1]) == -2) {
			if (depth(t->ch[1]->ch[0]) > depth(t->ch[1]->ch[1])) {
				t->ch[1] = rot_r(t->ch[1]);
			}
			t = rot_l(t);
		}
		return t;
	}
	node *insert(node *t, int k, T v) {
		if (!t) return new node(v);
		int c = count(t->ch[0]);
		if (k <= c)
			t->ch[0] = insert(t->ch[0], k, v);
		else
			t->ch[1] = insert(t->ch[1], k - (c + 1), v);
		return fix(update(t));
	}
	node *erase(node *t) {
		if (!t) return t;
		if (!t->ch[0] && !t->ch[1]) return nullptr;
		if (!t->ch[0] || !t->ch[1]) return t->ch[t->ch[0] == nullptr];
		return fix(update(new node(find(t->ch[1], 0)->val, t->ch[0], erase(t->ch[1], 0))));
	}
	node *erase(node *t, int k) {
		if (!t) return t;
		int c = count(t->ch[0]);
		if (k < c) {
			t->ch[0] = erase(t->ch[0], k);
			update(t);
		}
		else if (k > c) {
			t->ch[1] = erase(t->ch[1], k - (c + 1));
			update(t);
		}
		else {
			t = erase(t);
		}
		return fix(t);
	}
	node *find(node *t, int k) const {
		if (!t) return t;
		int c = count(t->ch[0]);
		return k < c ? find(t->ch[0], k) : k == c ? t : find(t->ch[1], k - (c + 1));
	}
	T find(node *t, int l, int r) const {
		if (!t || r <= 0 || t->size <= l) return M::id();
		if (l <= 0 && t->size <= r) return t->all;
		int c = count(t->ch[0]);
		return M::op(find(t->ch[0], l, r), M::op((l <= c && c < r ? t->val : M::id()), find(t->ch[1], l - (c + 1), r - (c + 1))));
	}
	node *root;
public:

	avl_tree() : root(nullptr) {}
	int size() const {
		return count(root);
	}
	void insert(int k, T b) {
		root = insert(root, k, b);
	}
	void erase(int k) {
		root = erase(root, k);
	}
	T find(int k) const {
		return find(root, k)->val;
	}
	T find(int l, int r) const {
		return find(root, l, r);
	}
};

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q;
	cin >> n >> q;
	avl_tree<RMQ> tree;
	for (int i = 0; i < n; i++) {
		int a;
		cin >> a;
		tree.insert(i, a);
	}
	while (q--) {
		int x, y, z;
		cin >> x >> y >> z;
		if (x == 0) {
			int val = tree.find(z);
			tree.erase(z);
			tree.insert(y, val);
		}
		else if (x == 1) {
			printf("%d\n", tree.find(y, z + 1));
		}
		else {
			tree.erase(y);
			tree.insert(y, z);
		}
	}
	return 0;
}

