template<class T>
struct Treap {
    Node<T> *root;
    int size;
    Treap() : root(Node<T>::nil), size(0) {
        root->nil->cnt = 0;
        root->nil->min_ = inf;
        root->nil->sum_ = 0;
    }
    // ~Treap(){
    //     delete root;
    // }
    void shift(int l, int r){
        T tmp = root->at(r-1)->val;
        root = root->erase(r-1);
        root = root->insert(l, tmp);
    }
    void set(int k, T x){
        root->set(k, x);
    }
    T min(int l, int r){
        return root->min(l, r);
    }
    void push_back(T x){
        if(size == 0) root = new Node<T>(x, xor128()), size++;
        else root = root->insert(size++,x);
    }
};

