/*-----8<-----template-----8<-----*/

/*
RandomizedBinarySearchTree(n, f, M1):= ノードを n 個用意する。
　f は2つの区間の要素をマージする二項演算,
　M1 はモノイドの単位元である。
RandomizedBinarySearchTree(n, f, g, h, M1, OM0):= ノードを n 個用意する。
　f は2つの区間の要素をマージする二項演算, 
　g は要素と作用素をマージする二項演算(第三引数は対応する区間の長さ), 
　h は作用素同士をマージする二項演算, 
　M1 はモノイドの単位元, 
　OM0 は作用素の単位元である。
merge(l, r):= 木 l と木 r を併合する。
split(t, k):= 木 t を [0,k)[k,n) で分割する。
build(v):= 配列 v をもとに木を構築する(O(n))。
dump(r):= 木 r の各ノードを通りがけ順に格納したものを返す(O(n))。
insert(t, k, v):= 木 t の位置 k にノード v を挿入する。
erase(t, k):= 木 t の位置 k のノードを削除する。
query(t, l, r):= 木 t の区間 [l,r) の値を二項演算した結果を返す。
set_propagate(t, a, b, p):= 木 t の区間 [a,b) に作用素 p を適用する。
set_element(t, k, x):= 木 t の k 番目の値を x に変更する。
size(t):= 木 t のノード数を返す。
makeset():= 空木を返す。
*/
template< class Monoid, class OperatorMonoid = Monoid >
struct RandomizedBinarySearchTree {
	using F = function< Monoid(Monoid, Monoid) >;
	using G = function< Monoid(Monoid, OperatorMonoid, ll) >;
	using H = function< OperatorMonoid(OperatorMonoid, OperatorMonoid) >;

	inline ll xor128() {
		static ll x = 123456789;
		static ll y = 362436069;
		static ll z = 521288629;
		static ll w = 88675123;
		ll t = x ^ (x << 11);
		x = y;
		y = z;
		z = w;
		return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
	}

	struct Node {
		ll cnt;
		Monoid key, sum;
		OperatorMonoid lazy;
		Node *l, *r;
		Node() = default;
		Node(const Monoid &k, const OperatorMonoid &p) : cnt(1), key(k), sum(k), lazy(p), l(nullptr), r(nullptr) {}
	};

	vector< Node > pool;
	ll ptr;
	const F f;
	const G g;
	const H h;
	const Monoid M1;
	const OperatorMonoid OM0;

	RandomizedBinarySearchTree(ll sz, const F &f, const Monoid &M1) :
			pool(sz), ptr(0), f(f), g(G()), h(H()), M1(M1), OM0(OperatorMonoid()) {}

	RandomizedBinarySearchTree(ll sz, const F &f, const G &g, const H &h,
								 const Monoid &M1, const OperatorMonoid &OM0) :
			pool(sz), ptr(0), f(f), g(g), h(h), M1(M1), OM0(OM0) {}

	inline Node *alloc(const Monoid &key) { return &(pool[ptr++] = Node(key, OM0)); }

	virtual Node *clone(Node *t) { return t; }

	inline ll count(const Node *t) { return t ? t->cnt : 0; }

	inline Monoid sum(const Node *t) { return t ? t->sum : M1; }

	inline Node *update(Node *t) {
		t->cnt = count(t->l) + count(t->r) + 1;
		t->sum = f(f(sum(t->l), t->key), sum(t->r));
		return t;
	}

	Node *propagate(Node *t) {
		t = clone(t);
		if(t->lazy != OM0) {
			t->key = g(t->key, t->lazy, 1);
			if(t->l) {
				t->l = clone(t->l);
				t->l->lazy = h(t->l->lazy, t->lazy);
				t->l->sum = g(t->l->sum, t->lazy, count(t->l));
			}
			if(t->r) {
				t->r = clone(t->r);
				t->r->lazy = h(t->r->lazy, t->lazy);
				t->r->sum = g(t->r->sum, t->lazy, count(t->r));
			}
			t->lazy = OM0;
		}
		return update(t);
	}

	Node *merge(Node *l, Node *r) {
		if(!l || !r) return l ? l : r;
		if(xor128() % (l->cnt + r->cnt) < l->cnt) {
			l = propagate(l);
			l->r = merge(l->r, r);
			return update(l);
		} else {
			r = propagate(r);
			r->l = merge(l, r->l);
			return update(r);
		}
	}

	pair< Node *, Node * > split(Node *t, ll k) {
		if(!t) return {t, t};
		t = propagate(t);
		if(k <= count(t->l)) {
			auto s = split(t->l, k);
			t->l = s.second;
			return {s.first, update(t)};
		} else {
			auto s = split(t->r, k - count(t->l) - 1);
			t->r = s.first;
			return {update(t), s.second};
		}
	}

	Node *build(ll l, ll r, const vector< Monoid > &v) {
		if(l + 1 >= r) return alloc(v[l]);
		return merge(build(l, (l + r) >> 1, v), build((l + r) >> 1, r, v));
	}

	Node *build(const vector< Monoid > &v) {
		ptr = 0;
		return build(0, (ll) v.size(), v);
	}

	void dump(Node *r, typename vector< Monoid >::iterator &it) {
		if(!r) return;
		r = propagate(r);
		dump(r->l, it);
		*it = r->key;
		dump(r->r, ++it);
	}

	vector< Monoid > dump(Node *r) {
		vector< Monoid > v((size_t) count(r));
		auto it = begin(v);
		dump(r, it);
		return v;
	}

	string to_string(Node *r) {
		auto s = dump(r);
		string ret;
		for(ll i = 0; i < (ll)s.size(); i++) ret += std::to_string(s[i]) + ", ";
		return (ret);
	}

	void insert(Node *&t, ll k, const Monoid &v) {
		auto x = split(t, k);
		t = merge(merge(x.first, alloc(v)), x.second);
	}

	void erase(Node *&t, ll k) {
		auto x = split(t, k);
		t = merge(x.first, split(x.second, 1).second);
	}

	Monoid query(Node *&t, ll a, ll b) {
		auto x = split(t, a);
		auto y = split(x.second, b - a);
		auto ret = sum(y.first);
		t = merge(x.first, merge(y.first, y.second));
		return ret;
	}

	void set_propagate(Node *&t, ll a, ll b, const OperatorMonoid &p) {
		auto x = split(t, a);
		auto y = split(x.second, b - a);
		y.first->lazy = h(y.first->lazy, p);
		t = merge(x.first, merge(propagate(y.first), y.second));
	}

	void set_element(Node *&t, ll k, const Monoid &x) {
		t = propagate(t);
		if(k < count(t->l)) set_element(t->l, k, x);
		else if(k == count(t->l)) t->key = t->sum = x;
		else set_element(t->r, k - count(t->l) - 1, x);
		t = update(t);
	}

	ll size(Node *t) {
		return count(t);
	}

	bool empty(Node *t) {
		return !t;
	}

	Node *makeset() {
		return nullptr;
	}
};
//kth_element は k(0-indeed) 番目に小さい値を返す。
template< class T >
struct OrderedMultiSet : RandomizedBinarySearchTree< T > {
	using RBST = RandomizedBinarySearchTree< T >;
	using Node = typename RBST::Node;

	OrderedMultiSet(ll sz) : RBST(sz, [&](T x, T y) { return x; }, T()) {}

	T kth_element(Node *t, ll k) {
		if(k < RBST::count(t->l)) return kth_element(t->l, k);
		if(k == RBST::count(t->l)) return t->key;
		return kth_element(t->r, k - RBST::count(t->l) - 1);
	}

	virtual void insert_key(Node *&t, const T &x) {
		RBST::insert(t, lower_bound(t, x), x);
	}

	void erase_key(Node *&t, const T &x) {
		if(!count(t, x)) return;
		RBST::erase(t, lower_bound(t, x));
	}

	ll count(Node *t, const T &x) {
		return upper_bound(t, x) - lower_bound(t, x);
	}

	ll lower_bound(Node *t, const T &x) {
		if(!t) return 0;
		if(x <= t->key) return lower_bound(t->l, x);
		return lower_bound(t->r, x) + RBST::count(t->l) + 1;
	}

	ll upper_bound(Node *t, const T &x) {
		if(!t) return 0;
		if(x < t->key) return upper_bound(t->l, x);
		return upper_bound(t->r, x) + RBST::count(t->l) + 1;
	}
};
template< class T >
struct OrderedSet : OrderedMultiSet< T > {
	using SET = OrderedMultiSet< T >;
	using RBST = typename SET::RBST;
	using Node = typename RBST::Node;

	OrderedSet(ll sz) : OrderedMultiSet< T >(sz) {}

	void insert_key(Node *&t, const T &x) override {
		if(SET::count(t, x)) return;
		RBST::insert(t, SET::lower_bound(t, x), x);
	}
};

