np build(int *l, int *r) {
    int n = r - l;
    if (n <= 0) return nullptr;
    int *m = l + n / 2;
    np res = new avl_node(*m);
    res->left = build(l, m);
    res->right = build(m + 1, r);
    return update(res);
}

