Random rnd;

typedef unsigned int uint;

template<class T>
struct Node {
	T value, mini;
	Node *child[2];
	uint priority;
	int size;

	Node(){}
	Node(T val, uint pri):
		value(val), mini(val), priority(pri), size(1)
	{
		child[0] = child[1] = 0;
	}
};

template<class T>
inline Node<T> *allocateNode(T value, uint priority) {
	return new Node<T>(value, priority);
}

template<class T>
inline void freeNode(Node<T> *node) {
	free(node);
}

template<class T>
inline int getSize(Node<T> *r) {
	return !r ? 0 : r->size;
}

template<class T>
inline Node<T> *getNode(Node<T>* r, int k) {
	int left = getSize(r->child[0]), which = (k > left);
	if (left == k) {
		return r;
	}
	return getNode(r->child[which], k - (which ? (left + 1) : 0));
}

template<class T>
inline Node<T> *update(Node<T> *r) {
	r->size = getSize(r->child[0]) + getSize(r->child[1]) + 1;
	r->mini = r->value;
	for (int i = 0; i < 2; ++i) if (r->child[i]) {
		r->mini = min(r->mini, r->child[i]->mini);
	}
	return r;
}

template<class T>
inline Node<T> *updateValue(Node<T> *r, int k, T val) {
	int left = getSize(r->child[0]), which = (k > left);
	if (left == k) {
		r->value = val;
		return update(r);
	}
	r->child[which] = updateValue(r->child[which], k - (which ? (left + 1) : 0), val);
	return update(r);
}

template<class T>
inline T queryValue(Node<T> *r, int from, int to) {
	if (to <= from) {
		return INF;
	}
	if (to - from == getSize(r)) {
		return r->mini;
	}
	int left = getSize(r->child[0]);
	if (to <= left) {
		return queryValue(r->child[0], from, to);
	}
	if (left < from) {
		return queryValue(r->child[1], from - left - 1, to - left - 1);
	}
	return min(r->value,
			min(queryValue(r->child[0], from ,left),
				queryValue(r->child[1], 0, to - left - 1)));
}

template<class T>
inline Node<T> *rotate(Node<T> *r, int which) { 
	Node<T> *opposite = r->child[which^1];
	r->child[which^1] = opposite->child[which];
	opposite->child[which] = r;
	update(r);
	update(opposite);
	return opposite;
}

template<class T>
inline Node<T> *insert(Node<T> *r, int k, T value, uint priority) {
	if (!r) {
		return allocateNode(value, priority);
	}
	int left = getSize(r->child[0]), which = (k > left);
	r->child[which] = insert(r->child[which], k - (which ? (left + 1) : 0), value, priority);
	update(r);
	if (r->priority > r->child[which]->priority) {
		r = rotate(r, which^1);
	}
	return r;
}

template<class T>
inline Node<T> *insert(Node<T> *r, int k, T value) {
	return insert(r, k, value, rnd.rand());
}

template<class T>
inline Node<T> *erase(Node<T> *r, int k) {
	if (r->size == 1) {
		freeNode(r);
		return 0;
	}
	int left = getSize(r->child[0]), which = (k > left);
	if (left == k) {
		r = rotate(r, left > 0);
		return erase(r, k);
	}
	r->child[which] = erase(r->child[which], k - (which ? (left + 1) : 0));
	update(r);
	return r;
}




