Treap* merge(Treap* l, Treap* r){
  if(l == nullptr) return r;
  if(r == nullptr) return l;

  if(l->p > r->p){
	l->ch[1] = merge(l->ch[1], r);
	return update(l);
  }
  else{
	r->ch[0] = merge(l, r->ch[0]);
	return update(r);
  }
}

// split <[0,k),[k,n)>
pair<Treap*,Treap*> split(Treap* t, int k){
  if(t == nullptr) return MP(nullptr, nullptr);

  pair<Treap*,Treap*> res;
  if(k <= count(t->ch[0])){
	res = split(t->ch[0], k);
	t->ch[0] = res.second;
	res.second = update(t);
  }
  else{
	res = split(t->ch[1], k - count(t->ch[0]) - 1);
	t->ch[1] = res.first;
	res.first = update(t);
  }
  return res;
}

Treap* insert(Treap* t, int k, int v){
  auto sp = split(t, k);
  Treap* u = new Treap(v);
  return merge(merge(sp.first, u), sp.second);
}

Treap* updateVal(Treap* t, int k, int v){
  auto sp1 = split(t, k);
  auto sp2 = split(sp1.second, 1);
  sp2.first->value = sp2.first->mn = v;
  return merge(sp1.first, merge(sp2.first, sp2.second));
}

Treap* rmq(Treap* t, int l, int r, Value& res){
  auto sp1 = split(t, l);
  auto sp2 = split(sp1.second, r-l);
  res = sp2.first->mn;
  return merge(sp1.first, merge(sp2.first, sp2.second));
}

Treap* shift(Treap* t, int l, int r){
  auto sp1 = split(t, l);
  auto sp2 = split(sp1.second, r-l);
  auto rot = split(sp2.first, r-l-1);

  return merge(sp1.first, merge(merge(rot.second, rot.first), sp2.second));
}

