        return x?x->m:1145141919;
    }
    Node* Update(){
        s=1+Size(l)+Size(r);
        m=min({v,Mini(l),Mini(r)});
        return this;
    }
    int Pos(){
        if(p&&p->l==this) return -1;
        if(p&&p->r==this) return 1;
        return 0;
    }
    void Rotate(){
        Node *q=p,*c;
        if(Pos()==1){
            c=l;
            l=p;
            p->r=c;
        }else{
            c=r;
            r=p;
            p->l=c;
        }
        if(c) c->p=p;
        p=p->p;
        q->p=this;
        if(p&&p->l==q) p->l=this;
        if(p&&p->r==q) p->r=this;
        q->Update();
    }
    Node* Splay(){
        while(p){
            int a=Pos(),b=p->Pos();
            if(b&&a==b) p->Rotate();
            if(b&&a!=b) Rotate();
            Rotate();
        }
        return Update();
    }
    Node* Idx(int i){
        if(i<Size(l)) return l->Idx(i);
        else if(i>Size(l)) return r->Idx(i-Size(l)-1);
        return Splay();
    }
