int main() {
    TreapArray<int> a;
    int n, q;
    cin >> n >> q;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        a.push_back(x);
    }

    auto rotate = [&](int L, int R) {
        int len = R - L + 1;
        Treap<int>::Node *l, *m1, *m2, *r;
        tie(l, r) = a.split(a.root, L);
        tie(m1, r) = a.split(r, len);
        tie(m1, m2) = a.split(m1, len - 1);
        m1 = a.merge(m2, m1);
        r = a.merge(m1, r);
        a.root = a.merge(l, r);
    };
    auto get_min = [&](int L, int R) {
        int len = R - L + 1;
        Treap<int>::Node *l, *m, *r;
        tie(l, r) = a.split(a.root, L);
        tie(m, r) = a.split(r, len);
        int mn = a.eval(m);
        r = a.merge(m, r);
        a.root = a.merge(l, r);
        return mn;
    };
    auto update = [&](int p, int x) {
        Treap<int>::Node *l, *m, *r;
        tie(l, r) = a.split(a.root, p);
        tie(m, r) = a.split(r, 1);
        m->val = x;
        m->cached = false;
        a.update(m);
        r = a.merge(m, r);
        a.root = a.merge(l, r);
    };

    while (q--) {
        int x, y, z;
        cin >> x >> y >> z;
        if (x == 0) {
            rotate(y, z);
        } else if (x == 1) {
            cout << get_min(y, z) << endl;
        } else {
            update(y, z);
        }
    }
    return 0;
}

