        ch[0] = ch[1] = np;
    }
};

void destory(Node * t){
    if(t == np) return;
    destory(t->ch[0]);
    destory(t->ch[1]);
    delete t;
}

int count(Node * t){
    return t == np ? 0 : t->cnt;
}
int sum(Node * t){
    return t == np ? 0 : t->sum;
}

int const inf = 1e9;

int min(Node * t){
