struct Node {
        Node *l, *r, *par;
        int size;
        //頂点の情報
        ll value;
        ll minimum = INF;
        Node(){
            l = nullptr;
            r = nullptr;
            par = nullptr;
            size = 1;
        }
        bool is_root(){
            return !par or (par->l != this and par->r != this);
        }
    };
struct SplayTree{
    Node *dat, *root;
    SplayTree(int n){
        dat = new Node[n];
    }
    void connect(int n){//size nの配列
        REP(i, n){
            dat[i + 1].l = &dat[i];
            dat[i].par = &dat[i + 1];
        }
        REP(i, n + 1) update(&dat[i]);
        root = &dat[n];
    }
     void connect(vector<ll> s){//size nの配列
        int n = s.size();
        REP(i, n){
            dat[i + 1].l = &dat[i];
            dat[i].par = &dat[i + 1];
            dat[i].value = s[i];
        }
        REP(i, n + 1) update(&dat[i]);
        root = &dat[n];
     }
    void update(Node *me){//情報の更新
        me->size = 1;
        if (me->l) me->size += me->l->size;
        if (me->r) me->size += me->r->size;

        me->minimum = me->value;
        if (me->l) me->minimum = min(me->minimum, me->l->minimum);
        if (me->r) me->minimum = min(me->minimum, me->r->minimum);
    };
    void rotate(Node* me){
        Node *p, *pp, *c;
        p = me->par;
        pp = p->par;
        if(p->l == me){
            c = me->r; p->l = c; me->r = p;
        }
        else{
            c = me->l; p->r = c; me->l = p;
        }
        if (pp and pp->l == p) pp->l = me;
        if (pp and pp->r == p) pp->r = me;
        me->par = pp; p->par = me;
        if (c) c->par = p;
        update(p); update(me);
    };
    int state(Node *me){
    if (!me->par) return 0;
    if (me->par->l == me) return 1;
    if (me->par->r == me) return -1;
    return 0;
    }
    void splay(Node *me){
        while(state(me) != 0){
            if (state(me->par) == 0) {
                rotate(me);
            }
            else if (state(me) == state(me->par)){
                rotate(me->par); rotate(me);
            }
            else{
                rotate(me); rotate(me);
            }
        }
    };
    Node* get(int index, Node* croot){
            Node *now = croot;
            while(1){
                int lsize = (now->l ? now->l->size : 0);
                if (index == lsize) {
                    splay(now);
                    root = now;
                    return now;
                }
                if (index < lsize) {
                    now = now->l;
                }
                if (index > lsize) {
                    now = now->r;
                    index = index - lsize - 1;
                }
            }
    }
    Node* get(int index){
        return root = get(index, root);
    }
    Node* merge(Node* lroot, Node* rroot){
        if (!lroot) return rroot;
        if (!rroot) return lroot;
        lroot = get(lroot->size - 1, lroot);
        lroot->r = rroot;
        rroot->par = lroot;
        update(lroot);
        return lroot;
    }
    pair<Node*, Node*> split(int index, Node* croot){
        if (index == 0) return {nullptr, croot};
        if (index == croot->size) return {croot, nullptr};
        croot = get(index, croot);
        Node *lroot, *rroot;
        lroot = croot->l;
        rroot = croot;
        lroot->par = nullptr;
        rroot->l = nullptr;
        update(rroot);
        return {lroot, rroot};
    }
    Node* insert(int index, Node* x, Node* croot){
        Node *lroot, *rroot;
        auto lrroot = split(index, croot);
        lroot = lrroot.first, rroot = lrroot.second;
        return merge(merge(lroot, x), rroot);
    }
    Node* insert(int index, Node* x){
        return root = insert(index, x, root);
    }
    pair<Node*, Node*> remove(int index, Node* croot){
        croot = get(index, croot);
        Node *lroot, *rroot;
        lroot = croot->l, rroot = croot->r;
        if(lroot) lroot->par = nullptr;
        if(rroot) rroot->par = nullptr;
        croot->l = nullptr;
        croot->r = nullptr;
        update(croot);
        return {merge(lroot, rroot), croot};
    }
    pair<Node*, Node*> remove(int index){//root, removed
        auto res = remove(index, root);
        root = res.first;
        return res;
    }
    Node query(int l, int r){ //[l, r] 注意!!!!!!
        Node *lroot, *rroot, *croot, res;
        auto now = split(r + 1, root);
        rroot = now.second;
        now = split(l, now.first);
        croot = now.second;
        lroot = now.first;
        res = *croot;
        root = merge(merge(lroot, croot), rroot);
        return res;
    }
};

