#include <bits/stdc++.h>
using namespace std;

mt19937 rnd;

template<typename T, typename Func_mv>
struct TreapArray{
    struct Node{
        T val, sum;
        int pri, cnt;
        Node *lch, *rch;
        Node(T v):val(v), sum(v), pri(rnd()), cnt(1){
            lch = rch = nullptr;
        }
    };

    Node* node;
    Func_mv merge_values;
    T te;

    TreapArray(Func_mv merge_values, T te, Node* n=nullptr):merge_values(merge_values), te(te){ node = n; }
    TreapArray(Func_mv merge_values, T te, T v):merge_values(merge_values), te(te){ node = new Node(v); }

    int count(Node* t){ return !t ? 0 : t->cnt; }
    T   sum  (Node* t){ return !t ? te : t->sum; }
    int size(){ return count(node); }

    Node* update(Node* t){
        t->cnt = count(t->lch) + count(t->rch) + 1;
        t->sum = merge_values(merge_values(sum(t->lch), t->val), sum(t->rch));
        return t;
    }

    Node* merge(Node* l, Node* r){
        if(!l || !r) return !l ? r : l;
        if(l->pri > r->pri){
            l->rch = merge(l->rch, r);
            return update(l);
        }else{
            r->lch = merge(l, r->lch);
            return update(r);
        }
    }

    pair<Node*, Node*> split(Node* t, int k){
        if(!t) return make_pair(nullptr, nullptr);
        if(k <= count(t->lch)){
            auto s = split(t->lch, k);
            t->lch = s.second;
            return {s.first, update(t)};
        }else{
            auto s = split(t->rch, k - count(t->lch) - 1);
            t->rch = s.first;
            return {update(t), s.second};
        }
    }
    pair<TreapArray*, TreapArray*> split(int k){
        auto p = split(node, k);
        node = p.first;
        auto t2 = new TreapArray(merge_values, te, p.second);
        return make_pair(this, t2);
    }

    void insert(int k, T v){
        auto s = split(node, k);
        auto n = new Node(v);
        node = merge(s.first, n);
        node = merge(node, s.second);
    }

    void erase(int k){
        auto s1 = split(node, k);
        auto s2 = split(s1.second, 1);
        node = merge(s1.first, s2.second);
    }

    T kth_element(Node* t, int k){
        int my_idx = count(t->lch);
        if(k == my_idx){
            return t->val;
        }else if(k < my_idx){
            return kth_element(t->lch, k);
        }else{
            return kth_element(t->rch, k-my_idx-1);
        }
    }
    T kth_element(int k){
        return kth_element(node, k);
    }

    void change_kth_element(Node* t, int k, T v){
        int my_idx = count(t->lch);
        if(k == my_idx){
            t->val = v;
        }else if(k < my_idx){
            change_kth_element(t->lch, k, v);
        }else{
            change_kth_element(t->rch, k-my_idx-1, v);
        }
        update(t);
    }
    void change_kth_element(int k, T v){ change_kth_element(node, k, v); }

    T get_between(Node* t, int l, int r){
        int last_idx = count(t)-1;
        if(r < 0 || l > last_idx) return te;
        if(l <= 0 && last_idx <= r) return sum(t);

        T res = get_between(t->lch, l, r);
        int my_idx = count(t->lch);
        if(l <= my_idx && my_idx <= r) res = merge_values(res, t->val);
        res = merge_values(res, get_between(t->rch, l-my_idx-1, r-my_idx-1));
        return res;
    }
    T get_between(int l, int r){ return get_between(node, l, r); }

    void dump(Node* t, vector<T>& ret){
        if(!t) return;
        dump(t->lch, ret);
        ret.push_back(t->val);
        dump(t->rch, ret);
    }
    vector<T> dump(){
        vector<T> ret;
        dump(node, ret);
        return ret;
    }
};

