struct STree {
    typedef ll D;
    const static D INF = 1LL<<55;
    struct Node;
    typedef Node* NP;
    static Node last_d;
    static NP last;
    struct Node {
        NP l, r;
        int sz;
        D v, mi;
        Node(D v) :l(last), r(last), sz(1), v(v), mi(v) {}
        Node(NP l, NP r, int sz = 0) :l(l), r(r), sz(sz) {} 
        void push() {
        }
        NP update() {
            sz = 1+l->sz+r->sz;
            mi = v;
            if (l->sz) {
                mi = min(mi, l->mi);
            }
            if (r->sz) {
                mi = min(mi, r->mi);
            }
            return this;
        }
        void print() {
            if (!sz) return;
            l->print();
            printf("%lld ", v);
            r->print();
        }
    } *n;


    static NP built(int l, int r, D d[]) {
        if (l == r) return last;
        int md = (l+r)/2;
        NP x = new Node(d[md]);
        x->l = built(l, md, d);
        x->r = built(md+1, r, d);
        return x->update();
    }

    static uint xor128(){
        static uint x=123456789,y=362436069,z=521288629,w=88675123;
        uint t;
        t=(x^(x<<11));x=y;y=z;z=w; return( w=(w^(w>>19))^(t^(t>>8)) );
    }
    static NP merge(NP l, NP r) {
        if (!l->sz) return r;
        if (!r->sz) return l; 
        l->push(); r->push();
        if (xor128() % (l->sz + r->sz) < l->sz) {
            l->r = merge(l->r, r);
            return l->update();
        } else {
            r->l = merge(l, r->l);
            return r->update();
        }
    }
    static pair<NP, NP> split(NP x, int k) {
        if (!x->sz) return {last, last};
        x->push();
        if (k <= x->l->sz) {
            auto y = split(x->l, k);
            x->l = y.second;
            y.second = x->update();
            return y;
        } else {
            auto y = split(x->r, k- x->l->sz -1);
            x->r = y.first;
            y.first = x->update();
            return y;
        }
    }

    STree(NP n) : n(n) {}
    STree(int sz, D d[]) {
        n = built(0, sz, d);
    }
    int sz() {
        return n->sz;
    }
    void merge(STree r) {
        n = merge(n, r.n);
    }
    STree split(int k) {
        auto u = split(n, k);
        n = u.first;
        return STree(u.second);
    }
    void insert(int k, D x) {
        auto u = split(n, k);
        n = merge(merge(u.first, new Node(x)), u.second);
    }
    void erase(int k) {
        auto u = split(n, k);
        n = merge(u.first, split(u.second, 1).second);
    }
    ll get(int l, int r) {
        auto u0 = split(n, l);
        auto u1 = split(u0.second, r-l);
        ll res = u1.first->mi;
        n = merge(u0.first, merge(u1.first, u1.second));
        return res;
    }
    void set(int l, D x) {
        auto u0 = split(n, l);
        auto u1 = split(u0.second, 1);
        u1.first->v = x;
        n = merge(u0.first, merge(u1.first, u1.second));
    }
    void print() {
        n->print();
        printf("\n");
    }
};
