      RBST::Tree tml, tmr;
      tie(tml, tmr) = RBST::split(tm, r - l - 1);
      tm = RBST::merge(tmr, tml);
      t = RBST::merge(RBST::merge(tl, tm), tr);
    } else if (type == 1) {
