mt19937 mt_rand(time(NULL));
using Value = int;

struct Treap {
  Value v;
  int cnt;
  int p;
  int seg_min;
  Treap *ch[2];
  Treap(Value v) : v(v), p(mt_rand()) {
    cnt = 1;
    seg_min = v;
    ch[0] = ch[1] = NULL;
  };
};
inline int count(Treap *t) { return t ? t->cnt : 0; }
inline int seg_min(Treap *t) { return t ? t->seg_min : INF; }
Treap *update(Treap *t) {
  if (t == NULL) return t;
  t->cnt = count(t->ch[0]) + count(t->ch[1]) + 1;
  t->seg_min = min({ seg_min(t->ch[0]), seg_min(t->ch[1]), t->v });
  return t;
}
Treap *merge(Treap *l, Treap *r) {
  if (l == NULL) return r;
  if (r == NULL) return l;
  if (l->p > r->p) {
    l->ch[1] = merge(l->ch[1], r);
    return update(l);
  }
  else {
    r->ch[0] = merge(l, r->ch[0]);
    return update(r);
  }
}

// [0, k), [k, n)
pair<Treap *, Treap *> split(Treap *t, int k) {
  if (t == NULL) return {NULL, NULL};
  if (k <= count(t->ch[0])) {
    auto s = split(t->ch[0], k);
    t->ch[0] = s._2;
    return { s._1, update(t) };
  }
  else {
    auto s = split(t->ch[1], k - count(t->ch[0]) - 1);
    t->ch[1] = s._1;
    return { update(t), s._2 };
  }
}

Treap *insert(Treap *t, int k, Value v) {
  Treap *l, *r;
  tie(l, r) = split(t, k);
  Treap *u = new Treap(v);
  return merge(merge(l, u), r);
}

pair<Treap *, Treap *> erase(Treap *t, int k) {
  Treap *l, *r, *u;
  tie(l, r) = split(t, k+1);
  tie(l, u) = split(l, k);
  return { merge(l, r), u };
}

int count_less(Treap *t, int x) {
  if (t == NULL) return 0;
  if (t->v <= x) {
    return count(t->ch[0]) + 1 + count_less(t->ch[1], x);
  }
  else {
    return count_less(t->ch[0], x);
  }
}
Treap *get(Treap *t, int k) {
  int l = count(t->ch[0]);
  if (k < l) return get(t->ch[0], k);
  if (k > l) return get(t->ch[1], k-l-1);
  return t;
}
void update_ancestor(Treap *t, int n) {
  int l = count(t->ch[0]);
  if (n < l) update_ancestor(t->ch[0], n);
  if (n > l) update_ancestor(t->ch[1], n-l-1);
  update(t);
}
Treap *shift(Treap *t) {
  if (t == NULL) return NULL;
  Treap *u;
  tie(t, u) = split(t, count(t)-1);
  return merge(u, t);
}

int N, Q;
signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N >> Q;

  Treap *treap = NULL;
  rep(i, N) {
    int a; cin >> a;
    treap = insert(treap, i, a);
  }

  rep(i, Q) {
    int t, a, b;
    cin >> t >> a >> b;
    if (t == 0) {
      // shift [a, b]
      Treap *l, *u, *r;
      tie(l, r) = split(treap, b+1);
      tie(l, u) = split(l, a);
      u = shift(u);
      assert(count(u) == b-a+1);
      treap = merge(merge(l, u), r);
    }
    else if (t == 1) {
      // min [a, b]
      Treap *l, *u, *r;
      tie(l, r) = split(treap, b+1);
      tie(l, u) = split(l, a);
      assert(count(u) == b-a+1);
      cout << seg_min(u) << "\n";
      treap = merge(merge(l, u), r);
    }
    else {
      // update(a, b)
      get(treap, a)->v = b;
      update_ancestor(treap, a);
    }
  }
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define L 250

#define INF 1e9

struct RMQ {
	vector< vector<int> > v;
	vector<int> m;
	void shift(int l, int r) {
		int pos = 0;
		int rv = -1;
		for (int i = 0; i < v.size(); ++i) {
			int np = pos+v[i].size();
			if (pos <= r && r < np) {
				int j = r-pos;
				rv = v[i][j];
				v[i].erase(v[i].begin()+j);
				break;
			}
			pos = np;
		}

		pos = 0;
		for (int i = 0; i < v.size(); ++i) {
			int np = pos+v[i].size();
			if (pos <= l && l < np) {
				int j = l-pos;
				v[i].insert(v[i].begin()+j, rv);
			}
			pos = np;
		}
	}
	int get(int l, int r) {
		int ret = INF;
		int pos = 0;
		for (int i = 0; i < v.size(); ++i) {
			int np = pos+v[i].size();
			if (l <= pos && np-1 <= r) {
				ret = min(ret, m[i]);
			}
			else if (pos <= r || l < np) {
				for (int j = 0; j < v[i].size(); ++j) {
					if (l <= pos+j && pos+j <= r) {
						ret = min(ret, v[i][j]);
					}
				}
			}
			pos = np;
		}
		return ret;
	}
	void update(int x, int val) {
		int pos = 0;
		for (int i = 0; i < v.size(); ++i) {
			int np = pos+v[i].size();
			if (pos <= x && x < np) {
				for (int j = 0; j < v[i].size(); ++j) {
					if (pos+j == x) {
						v[i][j] = val;
						break;
					}
				}
				int nv = INF;
				for (int j = 0; j < v[i].size(); ++j) {
					nv = min(nv, v[i][j]);
				}
				m[i] = nv;
				return;
			}
			pos = np;
		}
	}
	void smooth() {
		vector<int> a;
		for (int i = 0; i < v.size(); ++i) {
			for (int j = 0; j < v[i].size(); ++j) {
				a.push_back(v[i][j]);
			}
		}
		init(a);
	}
	void init(vector<int> a) {
		int N = a.size();
		v.clear(); v.resize((N-1)/L+1); // N > 0
		m = vector<int>(v.size(), INF);

		int pos = 0;
		for (int i = 0; i < v.size(); ++i) {
			for (int j = 0; j < L; ++j) {
				if (pos+j < N) {
					v[i].push_back(a[pos+j]);
					m[i] = min(m[i], a[pos+j]);
				}
			}
			pos += L;
		}
	}
};

int main() {
	RMQ rmq;
	int N, Q; cin >> N >> Q;
	vector<int> v(N);
	for (int i = 0; i < N; ++i) {
		cin >> v[i];
	}
	rmq.init(v);
	for (int t = 0; t < Q; ++t) {
		int x, y, z; cin >> x >> y >> z;
		switch (x) {
			case 0:
				rmq.shift(y, z);
				break;

			case 1:
				cout << rmq.get(y, z) << endl;
				break;

			case 2:
				rmq.update(y, z);
				break;
		}
		if (t % L == 0) {
			rmq.smooth();
		}
	}
}

