using namespace std;
typedef long long int ll;
typedef pair<int, int> P;
const int INF=1e9;
random_device rnd;
mt19937 mt(rnd());
uniform_real_distribution<> rnd1(0, 1.0);

struct node_t{
	int val;
	node_t *lch;
	node_t *rch;
	double pri;
	int cnt;
	int mn;
	node_t(ll v, double p):val(v), pri(p), cnt(1), mn(v), lch(nullptr), rch(nullptr){}

};

int count(node_t *t){
	return !t ? 0 : t->cnt;
}

int min(node_t *t){
	return !t ? INF : t->mn;
}

node_t *update(node_t *t){
	t->cnt=count(t->lch)+count(t->rch)+1;
	t->mn=min(t->val, min(min(t->lch), min(t->rch)));
	return t;
}

node_t *merge(node_t *l, node_t *r){
	if(!l || !r) return !l ? r : l;
	if(l->pri > r->pri){
		l->rch=merge(l->rch, r);
		return update(l);
	}else{
		r->lch=merge(l, r->lch);
		return update(r);
	}
}
pair<node_t*, node_t*> split(node_t *t, int k){ //[0, k), [k,n)
	if(!t) return make_pair(nullptr, nullptr);
	if(k <= count(t->lch)){
		pair<node_t*, node_t*> s=split(t->lch, k);
		t->lch=s.second;
		return make_pair(s.first, update(t));
	}else{
		pair<node_t*, node_t*> s=split(t->rch, k-1-count(t->lch));
		t->rch=s.first;
		return make_pair(update(t), s.second);
	}
}

node_t *shift(node_t *t, int l, int r){
	pair<node_t*, node_t*> s=split(t, l);
	pair<node_t*, node_t*> s2=split(s.second, r-l);
	pair<node_t*, node_t*> s3=split(s2.second, 1);
	return merge(merge(s.first, s3.first), merge(s2.first, s3.second));
}

node_t *insert(node_t *t, int pos, int x){
	pair<node_t*, node_t*> s=split(t, pos);
	pair<node_t*, node_t*> s2=split(s.second, 1);
	return merge(merge(s.first, new node_t(x, rnd1(mt))), s2.second);
}

int find(node_t *t, int l, int r){
	pair<node_t*, node_t*> s=split(t, l);
	pair<node_t*, node_t*> s2=split(s.second, r-l+1);
	int ans=min(s2.first);
	t=merge(s.first, merge(s2.first, s2.second));
	return ans;
}

node_t *init(node_t *t, int a){
	return merge(t, new node_t(a, rnd1(mt)));
}

int main()
{
	int n, q;
	cin>>n>>q;
	node_t* s=nullptr;
	for(int i=0; i<n; i++){
		int a; cin>>a;
		s=init(s, a);
	}
	for(int i=0; i<q; i++){
		int x, y, z;
		cin>>x>>y>>z;
		if(x==0){
			s=shift(s, y, z);
		}else if(x==1){
			cout<<find(s, y, z)<<endl;
		}else{
			s=insert(s, y, z);
		}
	}
    return 0;
}

