struct SplayTree{
	struct Node{
		int x,sz,mini;
		Node *l,*r,*p;
		Node(int x,Node *p):x(x),sz(1),mini(x),p(p),l(NULL),r(NULL){}
	};

	Node *root;

	SplayTree():root(NULL){}

	void Update(Node *n){
		if(n==NULL) return;
		n->mini=n->x;
		n->sz=1;
		if(n->l!=NULL){
			n->mini=min(n->mini,n->l->mini);
			n->sz+=n->l->sz;
		}
		if(n->r!=NULL){
			n->mini=min(n->mini,n->r->mini);
			n->sz+=n->r->sz;
		}
	}

	void Rotate(Node *n){
		Node *p=n->p,*pp=p->p;

		n->p=pp;
		if(pp==NULL) root=n;
		else{
			if(p==pp->l) pp->l=n;
			else pp->r=n;
		}

		p->p=n;
		if(p->l==n){
			p->l=n->r;
			if(n->r!=NULL) n->r->p=p;
			n->r=p;
		}else{
			p->r=n->l;
			if(n->l!=NULL) n->l->p=p;
			n->l=p;
		}
		Update(p);
		Update(n);
	}

	void Splay(Node *n){
		while(n->p){
			Node *p=n->p;
			if(!p->p){
				//zig
				Rotate(n);
			}else{
				Node *pp=p->p;
				if(pp->l==p){
					if(p->l==n){
						//zig-zig
						Rotate(p);
						Rotate(n);
					}else{
						//zig-zag
						Rotate(n);
						Rotate(n);
					}
				}else if(pp->r==p){
					if(p->l==n){
						//zig-zag
						Rotate(n);
						Rotate(n);
					}else{
						//zig-zig
						Rotate(p);
						Rotate(n);
					}
				}
			}
		}
	}

	Node* Find(Node *t,int k){	//1-indexed
		if(t==NULL) return NULL;
		int l_sz=Size(t->l),r_sz=Size(t->r);

		if(l_sz+1==k) return t;
		if(k<=l_sz) return Find(t->l,k);
		return Find(t->r,k-l_sz-1);
	}

	void Insert(Node *t,int k,int x){
		Node *p=Find(t,k);
		if(p==NULL){ //木が空
			root=new Node(x,NULL);
			return;
		}

		Splay(p);
		dump(p->x);
		Node *n=new Node(x,p);
		n->r=p->r;
		p->r=n;
		Splay(n);
	}

	void Erase(Node *t,int k){
		Node *n=Find(t,k+1);
		if(n==NULL) return;
		Splay(n);

		if(n->l==NULL){
			root=n->r;
			n->r->p=NULL;
			delete n;
			return;
		}

		Node *new_root=Max(n->l);
		Node *p=new_root->p;
		new_root->p->r=NULL;
		new_root->p=NULL;
		new_root->r=n->r;
		n->r->p=new_root;
		root=new_root;
		while(p!=NULL){
			Update(p);
			p=p->p;
		}
	}

	Node *Max(Node *t){
		if(t==NULL) return NULL;
		while(t->r!=NULL) t=t->r;
		return t;
	}

	Node* Merge(Node *l,Node *r){
		if(l==NULL) return r;
		if(r==NULL) return l;
		l=Max(l);
		Splay(l);
		Splay(r);
		l->r=r;
		r->p=l;
		Update(l);
		root=l;
		return l;
	}

	pair<Node*,Node*> Split(Node *t,int k){ //[,k),[k,)
		if(k==0) return make_pair((Node*)NULL,t);
		if(k==Size(t)) return make_pair(t,(Node*)NULL);
		if(k<0||Size(t)<k){
			dump("split failed");
			dump(Size(t));
			return make_pair((Node*)NULL,(Node*)NULL);
		}
		Node *l=Find(t,k);
		Splay(l);
		Node *r=l->r;
		if(r!=NULL) r->p=NULL;
		l->r=NULL;
		Update(l);
		return make_pair(l,r);
	}

	int Size(Node *t){
		if(t==NULL) return 0;
		return t->sz;
	}

	void ShowTree(Node *t){
		if(t==NULL) return;
		cerr << "[";
		ShowTree(t->l);
		cerr << "]<-";
		cerr << t->x;
		cerr << "->[";
		ShowTree(t->r);
		cerr << "]";
	}

	void Query0(int l,int r){
		pair<Node*,Node*> p1=Split(root,l);
		pair<Node*,Node*> p2=Split(p1.second,r-l-1);
		pair<Node*,Node*> p3=Split(p2.second,1);

		//[p1.first,p2.first,p3.first,p3.second]
		dump(Size(p1.first));
		dump(Size(p2.first));
		dump(Size(p3.first));
		dump(Size(p3.second));

		Merge(Merge(p1.first,p3.first),Merge(p2.first,p3.second));
	}

	void Query1(int l,int r){
		dump("qry1");
		cout << Query1Sub(l,r,root,0,root->sz) << endl;
	}

	int Query1Sub(int a,int b,Node *n,int l,int r){
		if(n==NULL||r<=a||b<=l) return INF;
		dump(n->x);
		dump(l);
		dump(r);
		if(a<=l&&r<=b) return n->mini;
		int res=INF,k=l+Size(n->l);
		if(a<=k&&k<b) res=n->x;
		return min({res,Query1Sub(a,b,n->l,l,r-Size(n->r)-1),Query1Sub(a,b,n->r,l+Size(n->l)+1,r)});
	}

	void Query2(int k,int x){
		Node *n=Find(root,k+1);
		Splay(n);
		n->x=x;
		Update(n);
	}
};

