using key_type = int;

enum { L, R };

struct node {
    key_type key;
    std::array<node*, 2> ch;
    int size;
    int height;

    int min;

    static node* const nil;

    node() : node(-1) { }
    node(key_type key) : node(key, nil, nil, 1, 1, key) { }
    node(const key_type key, node *left, node *right, int size, int height, key_type min)
        : key(key), ch({{left, right}}), size(size), height(height), min(min) { }

    void *operator new(size_t) {
        static int p = 0;
        static node pool[1000000];
        return pool + p++;
    }
};

node *const node::nil = new node(key_type(), nullptr, nullptr, 0, 0, 1e9);
node *const nil = node::nil;
namespace trush { auto ___ = []() { return nil->ch = {{nil, nil}}; }; };

using np = node*;
using cnp = const node*;

// ok
np update(np n) {
    n->size = n->ch[L]->size + 1 + n->ch[R]->size;
    n->height = std::max(n->ch[L]->height, n->ch[R]->height) + 1;

    n->min = std::min({n->ch[L]->min, n->key, n->ch[R]->min});
    return n;
}

// ok
template <int dir>
np rotate(np n) {
    assert(n->ch[!dir] != nil);
    np root = n->ch[!dir];
    n->ch[!dir] = root->ch[dir];
    root->ch[dir] = n;
    update(n);
    update(root);
    return root;
}

// ok
int bfactor(np n) {
    assert(n != nil);
    return n->ch[R]->height - n->ch[L]->height;
}

// ok
np balance(np n) {
    assert(abs(bfactor(n)) <= 2);
    if (bfactor(n) == +2) {
        if (bfactor(n->ch[R]) < 0) n->ch[R] = rotate<R>(n->ch[R]);
        return rotate<L>(n);
    } else if (bfactor(n) == -2) {
        if (bfactor(n->ch[L]) > 0) n->ch[L] = rotate<L>(n->ch[L]);
        return rotate<R>(n);
    } else {
        return n;
    }
}

// ok
np insert_at(np n, int k, key_type x) {
    assert(0 <= k && k <= n->size);
    if (n == nil) return new node(x);
    int sl = n->ch[L]->size;
    if (k <= sl) n->ch[L] = insert_at(n->ch[L], k, x);
    else n->ch[R] = insert_at(n->ch[R], k - sl - 1, x);
    return balance(update(n));
}

// ok
template <int dir>
std::pair<np, np> remove_most(np n) {
    assert(n != nil);
    if (n->ch[dir] != nil) {
        np most;
        std::tie(n->ch[dir], most) = remove_most<dir>(n->ch[dir]);
        return {balance(update(n)), most};
    } else {
        np res = n->ch[!dir];
        n->ch[!dir] = nil;
        return {res, update(n)};
    }
}

// ok
std::pair<np, key_type> remove_at(np n, int k) {
    assert(n != nil);
    int sl = n->ch[L]->size;
    if (k < sl) {
        key_type most;
        std::tie(n->ch[L], most) = remove_at(n->ch[L], k);
        return {balance(update(n)), most};
    } if (k == sl) {
        if (n->ch[R] == nil) {
            return {n->ch[L], n->key};
        } else {
            np most;
            std::tie(n->ch[R], most) = remove_most<L>(n->ch[R]);
            most->ch = n->ch;
            // delete n;
            return {balance(update(most)), n->key};
        }
    } else {
        key_type most;
        std::tie(n->ch[R], most) = remove_at(n->ch[R], k - sl - 1);
        return {balance(update(n)), most};
    }
}

// ok
np merge_with_root(np l, np root, np r) {
    // Members of `root` except root->key may not be valid for performance.
    if (abs(l->height - r->height) <= 1) {
        root->ch = {{l, r}};
        return update(root);
    } else if (l->height > r->height) {
        l->ch[R] = merge_with_root(l->ch[R], root, r);
        return balance(update(l));
    } else {
        r->ch[L] = merge_with_root(l, root, r->ch[L]);
        return balance(update(r));
    }
}

// ok
np merge(np l, np r) {
    if (l == nil) return r;
    if (r == nil) return l;
    np m;
    if (l->height > r->height) std::tie(r, m) = remove_most<L>(r);
    else std::tie(l, m) = remove_most<R>(l);
    return merge_with_root(l, m, r);
}

template <typename Iterator>
np build(Iterator left, Iterator right) {
    int n = right - left;
    Iterator mid = left + n / 2;
    if (n == 0) return nil;
    np l = build(left, mid);
    np r = build(mid + 1, right);
    np m = new node(*mid);
    m->ch = {{l, r}};
    return update(m);
}

// ok
std::pair<np, np> split_at(np n, int k) {
    assert(0 <= k && k <= n->size);
    if (n == nil) return {nil, nil};
    int sl = n->ch[L]->size;
    np l = n->ch[L];
    np r = n->ch[R];
    n->ch[L] = n->ch[R] = nil;
    // Members of node passed to `merge` must be valid,
    // but ones for `merge_with_root` doesn't have to.
    np nl, nr;
    if (k < sl) {
        std::tie(nl, nr) = split_at(l, k);
        return {nl, merge_with_root(nr, n, r)};
    } else if (k == sl) {
        update(n);
        return {l, merge(n, r)};
    } else {
        std::tie(nl, nr) = split_at(r, k - sl - 1);
        return {merge_with_root(l, n, nl), nr};
    }
}

void update_at(np n, int k, key_type x) {
    assert(0 <= k && k <= n->size - 1);
    int sl = n->ch[L]->size;
    if (k < sl) {
        update_at(n->ch[L], k, x);
    } else if (k == sl) {
        n->key = x;
    } else {
        update_at(n->ch[R], k - sl - 1, x);
    }
    update(n);
}

key_type range_min(np n, int l, int r) {
    assert(0 <= l && l <= r);
    assert(l <= r && r <= n->size);
    if (n == nil) return 1e9;
    if (l == 0 && r == n->size) {
        return n->key;
    }
    int sl = n->ch[L]->size;
    int res = 1e9;
    if (l < sl) {
        res = std::min(res, range_min(n->ch[L], l, std::min(r, sl)));
    }
    if (l <= sl && sl < r) {
        res = std::min(res, n->key);
    }
    if (sl < r) {
        res = std::min(res, range_min(n->ch[R], std::max(0, l - sl - 1), r - sl - 1));
    }
    return res;
}

