        if (n->size != real_size(n)) return false;
        if (n->height != real_height(n)) return false;
        if (n->size != l->size + 1 + r->size) return false;
        if (n->height != std::max(l->height, r->height) + 1) return false;
        if (abs(bfactor(n)) >= 2) return false;
        return true;
    }
}

