      bit.add(id[y[i]],-1);
      y[i] = id[y[i]] + bit.sum(id[y[i]]);
      bit.add(id[z[i]]+1,+1);
    }else if(x[i] == 1){
      y[i] = id[y[i]] + bit.sum(id[y[i]]);
      z[i] = id[z[i]] + bit.sum(id[z[i]]);
    }else{
