int min(const vector<int>& v, int l, int r){
	int min = v[l];
	for(int i = l + 1; i <= r; i++){
		if(min > v[i]){
			min = v[i];
		}
	}
	return min;
}

vector<int> shift(const vector<int>& v, int l, int r){
	vector<int> v1;
	copy(v.begin(), v.end(), back_inserter(v1));
	v1.insert(v1.begin() + (l - 1), v[r]);
	v1.erase(v1.begin() + (r + 1));
	return v1; 
}


