    int val, mini, cnt;
    Node() {
        lch = rch = NULL;
        val = mini = 0;
        cnt = 1;
    }
};

typedef pair<Node*, Node*> PPNode;

int getcnt(Node *t) { return t ? t->cnt : 0; }
int getmin(Node *t) { return t ? t->mini : 1 << 29; }

Node* update(Node *t)
{
    t->cnt = getcnt(t->lch) + getcnt(t->rch) + 1;
    t->mini = min(min(getmin(t->lch), getmin(t->rch)), t->val);
    return t;
}

Node* merge(Node *l, Node *r)
{
    if (!l || !r) return l ? l : r;
    if (l->pri > r->pri) {
        l->rch = merge(l->rch, r);
        return update(l);
    } else {
        r->lch = merge(l, r->lch);
        return update(r);
    }
}

PPNode split(Node *t, int k)
{
    if (!t) return PPNode(NULL, NULL);
    if (k <= getcnt(t->lch)) {
        PPNode p = split(t->lch, k);
        t->lch = p.second;
        return PPNode(p.first, update(t));
    } else {
        PPNode p = split(t->rch, k - getcnt(t->lch) - 1);
        t->rch = p.first;
        return PPNode(update(t), p.second);
    }
}

