template<class T> class rbst{
public:
	struct node{
        T val,min;
        node* left,*right;
        unsigned sz;
        node(T val):val(val),min(val),left(NULL),right(NULL),sz(1){}
    };

    node* root;
    rbst():root(NULL){}

    unsigned size(){ return size(root); }
    unsigned size(node*v){ return v?v->sz:0; }
    T min(node* v){ return v?v->min:numeric_limits<T>::max(); }

	node* update(node* x){
		x->sz=size(x->left)+size(x->right)+1;
        x->min=std::min({x->val,min(x->left),min(x->right)});
		return x;
	}

	node* merge(node* x,node* y){
        if(!x or !y) return x?x:y;

		int m=x->sz,n=y->sz;
		if(xor128::rand()%(m+n)<m){
			x->right=merge(x->right,y);
			return update(x);
		}
        y->left=merge(x,y->left);
        return update(y);
	}

    //[0,pos),[pos,sz)
	pair<node*,node*> split(node *v,unsigned pos){
        if(!v) return pair<node*,node*>(NULL,NULL);
        if(pos<=size(v->left)){
            pair<node*,node*> s=split(v->left,pos);
            v->left=s.second;
            return make_pair(s.first,update(v));
        }
        auto s=split(v->right,pos-size(v->left)-1);
        v->right=s.first;
        return make_pair(update(v),s.second);
    }


    node* insert(unsigned pos,T val){ return root=insert(root,pos,val); }
	node* insert(node* x,int pos,T val){
        auto y=split(x,pos);
        x=merge(y.first,new node(val));
        x=merge(x,y.second);
        return update(x);
    }

    node* erase(int pos){ return root=erase(root,pos); }
	node* erase(node* x,int pos){
		auto tmp=split(x,pos-1);
		node* l=tmp.first;
		node* r=split(tmp.second,1).second;
		return merge(l,r);
    }

    node* at(unsigned pos){
        node* x=root;
        while(x){
            unsigned sz=size(x->left);
            if(sz>pos) x=x->left;
            else if(sz==pos) return x;
            else{
                x=x->right;
                pos-=sz+1;
            }
        }
        return x;
    }

    //[l,r)
    node* rotate(int l,int r){
        auto u=split(root,r),v=split(u.first,r-1),w=split(v.first,l);
        return root=merge(merge(w.first,v.second),merge(w.second,u.second));
    }

    //[l,r)
    T min(int l,int r){
        auto u=split(root,r),v=split(u.first,l);
        auto res=min(v.second);
        root=merge(merge(v.first,v.second),u.second);
        return res;
    }

    node* update(int pos,int val){
        auto u=split(root,pos+1),v=split(u.first,pos);
        v.second->val=val;
        update(v.second);
        return root=merge(merge(v.first,v.second),u.second);
    }
};

