        // puts("b");
        // treap(b).show_array();
        // puts("c");
        // treap(c).show_array();
        // puts("d");
        // treap(d).show_array();

        np ac = __merge(a, c);
        np bd = __merge(b, d);
        root = __merge(ac, bd);
    }
};

