template<class T> class rbst{
public:
	struct node{
        T val,min;
        node* left,*right;
        unsigned sz;
        node(T val):val(val),min(val),left(NULL),right(NULL),sz(1){}
    };

    node* root;
    rbst():root(NULL){}

    unsigned size(){ return size(root); }
    unsigned size(node*v){ return !v?0:v->sz; }
    T min(node* v){ return v?v->min:numeric_limits<T>::max(); }

	node* update(node* x){
		x->sz=size(x->left)+size(x->right)+1;
        x->min=std::min({x->val,min(x->left),min(x->right)});
		return x;
	}

	node* merge(node* x,node* y){
        if(!x or !y) return x?x:y;

		int m=x->sz,n=y->sz;
		if(xor128::rand()%(m+n)<m){
			x->right=merge(x->right,y);
			return update(x);
		}else{
			y->left=merge(x,y->left);
			return update(y);
		}
	}

    //[0,pos),[pos,n)
	pair<node*,node*> split(node* x,unsigned pos){
		if(!x) return make_pair<node*,node*>(NULL,NULL);
		if(size(x->left)<=pos){
			auto tmp=split(x->right,pos-size(x->left));
			x->right=tmp.first;
			return make_pair(x,tmp.second);
		}else{
			auto tmp=split(x->left,pos);
			x->left=tmp.second;
			return make_pair(x,tmp.first);
		}
	}

    node* insert(unsigned pos,T val){ return root=insert(root,pos,val); }
	node* insert(node* x,int pos,T val){
		node* p=new node(val);
		auto tmp=split(x,pos-1);
		node*l=merge(tmp.first,p),*r=tmp.second;
		return merge(l,r);
    }

    node* erase(int pos){ return root=erase(root,pos); }
	node* erase(node* x,int pos){
		auto tmp=split(x,pos-1);
		node* l=tmp.first;
		node* r=split(tmp.second,1).second;
		return merge(l,r);
    }

    node* at(unsigned pos){
        node* x=root;
        while(x){
            unsigned sz=size(x->left);
            if(sz>pos) x=x->left;
            else if(sz==pos) return x;
            else{
                x=x->right;
                pos-=sz+1;
            }
        }
        return x;
    }

    //[l,r)
    void shift(int l,int r){
        pair<node*,node*> u,v,w;
        u=split(root,r);
        v=split(u.first,r-1);
        w=split(v.first,l);
        merge(merge(w.first,v.second),merge(w.second,u.second));
    }

    T min(int l,int r){
        pair<node*,node*> u,v;
        u=split(root,r);
        v=split(u.first,l);
        auto res=min(v.second);
        merge(merge(v.first,v.second),u.second);
        return res;
    }

    void update(int pos,int val){
        pair<node*,node*> u,v;
        u=split(root,pos+1);
        v=split(u.first,pos);
        v.second->val=val;
        update(v.second);
        merge(merge(v.first,v.second),u.second);
    }
};

void solve(){
    int n,q;
