template <typename T> class Treap
{
    function<double(void)> dice;
public:
    struct node{
        T val, min_val;
        int st_size;   // ??¨?????¨????????????
        double  pri;   // ?????????
        node* left; node* right;
        using pnn = pair<node*,node*>;
        node(T v, double p) : val(v), left(nullptr), right(nullptr), pri(p), st_size(1), min_val(v){}
        ~node() { delete left; delete right; }
        inline static int size(node* t) { return t ? t->st_size : 0; }
        inline static T min_(node* t) { return t ? t->min_val : std::numeric_limits<T>::max(); }
        inline static node* update(node *t) {
            node* l = t->left; node* r = t->right;
            t->st_size = size(l) + size(r) + 1;
            t->min_val = min({min_(l), min_(r), t->val});
            return t;
        }
        inline static node* merge(node* l, node* r){   //??????????????????????????°??????????????????
            if (!l || !r) return (!l) ? r : l;
            update(l); update(r);
            if(rand() % (size(l) + size(r)) < size(l)){
                l->right = merge(l->right, r);
                return update(l);
            }else{
                r->left = merge(l, r->left);
                return update(r);
            }
        }
        inline static pnn split(node* t, int k){   //??¨???????????????(k,n-k)??¨???????????????????????????
            if(!t) return pnn(nullptr, nullptr);
            update(t);
            if(k <= size(t->left)){
                pnn s = split(t->left, k);
                t->left = s.second;
                return pnn(s.first,update(t));
            }else{
                pnn s = split(t->right, k-size(t->left)-1);
                t->right = s.first;
                return pnn(update(t), s.second);
            }
        }
        inline static node* insert(node* t, int k, node* u){
            pnn s = split(t, k);
            return merge(merge(s.first, u), s.second);
        }
        inline static pnn erase(node* t, int k){
            pnn sr = split(t, k+1);
            pnn sl = split(sr.first, k);
            return pnn(merge(sl.first, sr.second), sl.second);
        }
    };
    node *root;
    Treap() : root(nullptr) {
        random_device rnd;
        dice = std::bind(std::uniform_real_distribution<double>(0.0,1.0), std::mt19937(rnd()));
    }
    ~Treap() {}
    void insert(int k, T val){
        root = node::insert(root, k, new node(val, dice()));
    }
    void erase(int k) {
        node *p;
        tie(root, p) = node::erase(root, k);
        p->left = p->right = nullptr;
        delete p;
    }
    T get(int k){
        node* v = root;
        while(v) {
            int s = node::size(v->left);
            if(s > k){
                 v = v->left;
            }else if(s == k){
                return v->val;
            }else{
                v = v->right;
                k -= s+1;
            }
        }
        return v->val;
    }
    //cri??\??????????´???°(???????????????????????§????????´??????????????¨???)
    int index(T cri){
        int res = 0;
        node* v = root;
        while(v){
            if(cri < v->val){
                v = v->left;
            }else{
                res += node::size(v->left) + 1;
                v = v->right;
            }
        }
        return res;
    }
    //k???????????????val????????´
    void set(int k, T val) {
        auto sr = node::split(root, k+1);
        auto sl = node::split(sr.first, k);
        auto lr = sl.second;
        lr->val = val;
        root = node::merge(node::merge(sl.first, lr), sr.second);
    }
    //???????????§?????°?????????
    void shift(int l,int r)
    {
        auto sr = node::split(root, r);
        auto sl = node::split(sr.first, l);
        auto sm = node::split(sl.second, r-l-1);
        root = node::merge(node::merge(sl.first,sm.second),node::merge(sm.first,sr.second));
    }
    T query(int l, int r) {
        auto sr = node::split(root, r);
        auto sl = node::split(sr.first, l);
        auto lr = sl.second;
        T val = node::min_(lr);
        root = node::merge(node::merge(sl.first, lr), sr.second);
        return val;
    }
};

