class Node {
public:
  Node *left, *right;
  int num;
  int value;
  int min;
  Node() {}
};

class NodeHeap {
public:
  std::vector<Node*> xss;
  int n;
  NodeHeap() : n(262144) {}
  Node* next() {
    if( n == 262144 ) {
      n = 0;
      Node *p = new Node[262144];
      xss.push_back(p);
    }
    return &xss[xss.size()-1][n++];
  }
  int getNumNode() {
    return n + ((int)xss.size() - 1) * 262144;
  }
};
NodeHeap nheap;

inline Node* initLeaf(int v) {
  //Node *res = new Node;
  Node *res = nheap.next();
  res->left = res->right = nullptr;
  res->num = 1;
  res->value = v;
  res->min = v;
  return res;
}

inline Node* initLeaf(Node* base, int v) {
#ifdef Persistent
  //Node *res = new Node;
  Node *res = nheap.next();
#else
  Node *res = base != nullptr ? base : nheap.next();
#endif  
  //Node *res = new Node;
  //Node *res = nheap.next();
  res->left = res->right = nullptr;
  res->num = 1;
  res->value = v;
  res->min = v;
  return res;
}


inline Node* initNode(Node* base, Node* left, Node* right) {
#ifdef Persistent
  //Node *res = new Node;
  Node *res = nheap.next();
#else
  Node *res = base != nullptr ? base : nheap.next();
#endif
  res->left = left;
  res->right = right;
  res->num = 0;
  res->value = 0;
  res->min = (1 << 30);
  return res;
}

inline bool isLeaf(Node* p) {
  if( p == nullptr ) return false;
  return p->left == nullptr and p->right == nullptr;
}

inline int getNum(Node* p) {
  if( p == nullptr ) return 0;
  if( isLeaf(p) ) return 1;
  return p->num;
}

inline Node* getLeft(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->left;
}

inline Node* getRight(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->right;
}

inline int getValue(Node* p) {
  if( p == nullptr ) return (1 << 30);
  return p->value;
}

inline int getMin(Node* p) {
  if( p == nullptr ) return (1 << 30);
  return p->min;
}

// checker
