const int INF = 200000000;
tr1::mt19937 mt;

struct RBST{
	int count;
	int value;
	int minimum;
	RBST *l, *r;
	RBST(int value = 0):count(1), value(value), minimum(value), l(NULL), r(NULL){}
	static int size(RBST *a){
		return a ? a->count : 0;
	}
	static int get_min(RBST *a){
		return a ? a->minimum : INF;
	}
	RBST *update(){
		count = 1 + size(l) + size(r);
		minimum = min({get_min(l), get_min(r), value});
		return this;
	}
	// aとbを連結する(破壊的)
	static RBST *merge(RBST *a, RBST *b){
		if(!a || !b) return a?a:b;
		if( (int)(mt() % (size(a) + size(b))) < size(a)){ // aの方が優先度が高い
			a->r = merge(a->r, b);
			return a->update();
		}else{
			b->l = merge(a, b->l);
			return b->update();
		}
	}

	// [0,k)と[k,n)の2つの木に分割する
	static pair<RBST*,RBST*> split(RBST *a, int k){
		if(!a) return make_pair<RBST*,RBST*>(NULL, NULL);
		if(k <= size(a->l)){
			pair<RBST*,RBST*> t = split(a->l, k);
			a->l = t.second;
			return make_pair(t.first, a->update());
		}else{
			pair<RBST*,RBST*> t = split(a->r, k - size(a->l) - 1);
			a->r = t.first;
			return make_pair(a->update(), t.second);
		}
	}
};


RBST nodes[200000];
int p;
int x,y,z;
int main(){
	int n,k;
	scanf("%d%d",&n,&k);
	RBST *s;
	for(int i=0;i<n;i++){
		int a;
		scanf("%d", &a);
		nodes[p] = RBST(a);
		s = RBST::merge(s, &nodes[p++]);
	}
	for(;k--;){
		scanf("%d%d%d",&x,&y,&z);
		if(x==0){
			z++;
			auto t1 = RBST::split(s, y);
			auto t2 = RBST::split(t1.second, z - y);
			auto t3 = RBST::split(t2.first, RBST::size(t2.first) - 1);
			s = RBST::merge(RBST::merge(t1.first,RBST::merge(t3.second, t3.first)), t2.second);
		}else if(x==1){
			z++;
			auto t1 = RBST::split(s, y);
			auto t2 = RBST::split(t1.second, z - y);
			printf("%d\n",RBST::get_min(t2.first));
			s = RBST::merge(t1.first,RBST::merge(t2.first,t2.second));
		}else{
			auto t1 = RBST::split(s,y);
			auto t2 = RBST::split(t1.second, 1);
			*t2.first = RBST(z);
			s = RBST::merge(t1.first,RBST::merge(t2.first,t2.second));
		}
	}
}

