struct rbst {
	rbst *lch, *rch;
	int sz;
	int val, mi;
	rbst(int _val) : lch(NULL), rch(NULL), sz(1), val(_val), mi(_val) {}
};
typedef pair<rbst*, rbst*> P;

int sz(rbst* x) { return x ? x->sz : 0; }
int mi(rbst* x) { return x ? x->mi : INT_MAX; }

rbst* update(rbst* x) {
	x->sz = 1 + sz(x->lch) + sz(x->rch);
	x->mi = min(x->val, min(mi(x->lch), mi(x->rch)));
	return x;
}

rbst* merge(rbst* x, rbst* y) {
	if (!x) return y;
	if (!y) return x;
	if (dc(x->sz + y->sz) < x->sz) {
		x->rch = merge(x->rch, y);
		return update(x);
	}
	else {
		y->lch = merge(x, y->lch);
		return update(y);
	}
}

rbst* merges(vector<rbst*> xs) {
	rbst* x = NULL;
	for (rbst* y: xs) x = merge(x, y);
	return x;
}

P split(rbst* x, int i) {
	if (!x) return P();
	if (i <= sz(x->lch)) {
		P p = split(x->lch, i);
		x->lch = p.second;
		return P(p.first, update(x));
	}
	else {
		P p = split(x->rch, i - sz(x->lch) - 1);
		x->rch = p.first;
		return P(update(x), p.second);
	}
}

vector<rbst*> splits(rbst* x, vector<int> is) {
	reverse(is.begin(), is.end());
	vector<rbst*> xs;
	for (int i: is) {
		P p = split(x, i);
		x = p.first;
		xs.pb(p.second);
	}
	xs.pb(x);
	reverse(xs.begin(), xs.end());
	return xs;
}

int get_val(rbst* x, int i) {
	int lsz = sz(x->lch);
	if (i < lsz) return get_val(x->lch, i);
	else if (i > lsz) return get_val(x->rch, i - lsz - 1);
	else return x->val;
}

void set_val(rbst* x, int i, int val) {
	int lsz = sz(x->lch);
	if (i < lsz) set_val(x->lch, i, val);
	else if (i > lsz) set_val(x->rch, i - lsz - 1, val);
	else x->val = val;
	update(x);
}

int get_mi(rbst* x, int l, int r) {
	if (!x || r < 0 || x->sz <= l) return INT_MAX;
	if (l <= 0 && x->sz <= r) return x->mi;
	int lsz = sz(x->lch), mi = INT_MAX;
	if (l <= lsz && lsz < r) mi = x->val;
	mi = min(mi, get_mi(x->lch, l, r));
	mi = min(mi, get_mi(x->rch, l - lsz - 1, r - lsz - 1));
	return mi;
}

int lower_bound(rbst* x, int val) {
	if (!x) return 0;
	if (val <= x->val) return lower_bound(x->lch, val);
	else return sz(x->lch) + 1 + lower_bound(x->rch, val);
}

