      int l=-1,r=n;
      while(r-l>1){
	int m = (l+r)/2;
	if( m+bit.sum(m) >= y[i])r = m;
	else l = m;
      }
      bit.add(r,1);
    }
  }

  vi id(n);
  rep(i,n){
    id[i] = i + bit.sum(i);
  }

  vi v(n+bit.sum(n+1),1e9);
  rep(i,n)v[id[i]] = a[i];

  //rep(azu,v.size())cout << v[azu] << " "; cout << endl;
  SegmentTree st(v);
