inline int xor32()
{
  static int y = 2463534242;
  y = y ^ (y << 13); y = y ^ (y >> 17);
  return(y = y ^ (y << 5));
}

struct Node {
  int Value;
  int SubTreeSize;
  Node *Lch, *Rch;

  int RMQ;

  Node(int V):Value(V), SubTreeSize(1), RMQ(INF) {
    Lch = (Node *)NULL;
    Rch = (Node *)NULL;
  };
};
inline int Count(Node *t)
{
  if(t == (Node *)NULL) return(0);
  else return(t -> SubTreeSize);
}
inline int Sum(Node *t)
{
  if(t == (Node *)NULL) return(INF);
  else return(t -> RMQ);
}

inline Node *Update(Node *t)
{
  t -> SubTreeSize = Count(t -> Lch) + Count(t -> Rch) + 1;
  t -> RMQ = min(Sum(t -> Lch), min(Sum(t -> Rch), t -> Value));
  return(t);
}
inline void Push(Node *t) 
{
}

inline Node *MakeRoot(int value)
{
  return(new Node(value));
}

Node *Merge(Node *l, Node *r)
{
  Push(l), Push(r);
  if(l == (Node *)NULL) return(r);
  if(r == (Node *)NULL) return(l);
  int Left  = l -> SubTreeSize;
  int Right = r -> SubTreeSize;
  if(xor32() % (Left + Right) < Left) { // ???(left)??????
    l -> Rch = Merge(l -> Rch, r);
    return(Update(l));
  } else {                              // ???(right)??????
    r -> Lch = Merge(l, r -> Lch);
    return(Update(r));
  }
}

pair< Node*, Node* > Split(Node *t, int k) // [0, k), [k, n)
{
  if(t == (Node *)NULL) return(make_pair((Node *)NULL, (Node *)NULL));
  Push(t);
  if(k <= Count(t -> Lch)) { // ?????´?????????
    pair< Node *, Node *> s = Split(t -> Lch, k);
    t -> Lch = s.second;
    return(make_pair(s.first, Update(t)));
  } else {                   // ?????´?????????
    pair< Node *, Node *> s = Split(t -> Rch, k - Count(t -> Lch) - 1);
    t -> Rch = s.first;
    return(make_pair(Update(t), s.second));
  }
}

Node *Insert(Node *root, int k, int value)
{
  pair< Node *, Node *> s = Split(root, k);
  return(Update(Merge(Merge(s.first, MakeRoot(value)), s.second)));
}
Node *Erase(Node *root, int k)
{
  pair< Node *, Node *> s = Split(root, k + 1);
  pair< Node *, Node *> t = Split(s.first, k);
  return(Update(Merge(t.first, s.second)));
}

void Dump(Node *root)
{
  if(root == (Node *)NULL) return;
  cout << "(";
  Dump(root -> Lch);
  cout << "" << root -> Value << "";
  Dump(root -> Rch);
  cout << ")";
}

