{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q, x, y, z, a;
	cin >> n >> q;
	RedBlackTree rbt;
	for (int i = 0; i < n; i++) {
		cin >> a;
		rbt.insert(i, a);
	}
	while (q--) {
		cin >> x >> y >> z;
		if (x == 0) {
