/*--------------------template--------------------*/


pii place(vector<vi> &v, int p)
{
	int cnt = 0;
	for(int i = 0;; i++)
	{
		if (cnt + v[i].size() <= p)
		{
			cnt += v[i].size();
		}
		else return pii(i, p - cnt);
	}
}

void copy(vector<vi> &to, vi &from, int s)
{
	REP(i, from.size())
	{
		to[i/s].push_back(from[i]);
	}
}

int main()
{
	int n, q;
	cin >> n >> q;
	int s = ceil(sqrt(n));
	vector<vi> v(s);
	vi a(n), mn(s);
	REP(i, n) cin >> a[i];
	copy(v, a, s);
	REP(i, v.size()) mn[i] = (v[i].size() > 0 ? *min_element(ALL(v[i])) : INF);
	REP(op, q)
	{
		if (op % (s - 1) == 0)
		{
			vector<vi> nv(s);
			vi tmp;
			REP(i, v.size())REP(j, v[i].size()) tmp.push_back(v[i][j]);
			copy(nv, tmp, s);
			v = nv;
		}
		int a,b,c;
		cin >> a >> b >> c;
		int lx = place(v, b).first, ly = place(v, b).second;
		if(a == 0)
		{
			int rx = place(v, c).first, ry = place(v, c).second;
			int t = v[rx][ry];
			v[rx].erase(v[rx].begin() + ry);
			v[lx].insert(v[lx].begin() + ly, t);
			mn[lx] = *min_element(ALL(v[lx]));
			mn[rx] = (v[rx].size() > 0 ? *min_element(ALL(v[rx])) : INF);
		}
		else if(a == 1)
		{
			int rx = place(v, c).first, ry = place(v, c).second;
			int ans = INF;
			FOR(i, ly, v[lx].size()) chmin(ans, v[lx][i]);
			FOR(i, lx + 1, rx) chmin(ans, mn[i]);
			if(rx!=lx) REP(i, ry) chmin(ans, v[rx][i]);
			cout << ans << endl;
		}
		else
		{
			v[lx][ly] = c;
			mn[lx] = *min_element(ALL(v[lx]));
		}
	}
	return 0;
}

