class Node {
public:
  Node *left, *right;
  int num;
  int value;
  int min;
  Node() {}
};

Node *root;

Node* initLeaf(int v) {
  Node *res = new Node;
  res->left = res->right = nullptr;
  res->num = 1;
  res->value = v;
  res->min = v;
  return res;
}

Node* initNode(Node* left, Node* right) {
  Node *res = new Node;
  res->left = left;
  res->right = right;
  res->num = 0;
  res->value = 0;
  res->min = (1 << 30);
  return res;
}

bool isLeaf(Node* p) {
  if( p == nullptr ) return false;
  return p->left == nullptr and p->right == nullptr;
}


int getNum(Node* p) {
  if( p == nullptr ) return 0;
  if( isLeaf(p) ) return 1;
  return p->num;
}

Node* getLeft(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->left;
}

Node* getRight(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->right;
}

int getValue(Node* p) {
  if( p == nullptr ) return (1 << 30);
  //assert( p != nullptr );
  return p->value;
}


