            int p;
            int x = 0;
            for (int i = 0; i < a.size(); ++i) {
                if (r < x + a[i].size()) {
                    p = a[i][r - x];
                    a[i].erase(a[i].begin() + r - x);
                    b[i] = 1 << 30;
                    for (int j : a[i])
                        b[i] = min(b[i], j);
                    break;
                }
                x += a[i].size();
            }
            x = 0;
            for (int i = 0; i < a.size(); ++i) {
                if (l < x + a[i].size()) {
                    a[i].insert(a[i].begin() + l - x, p);
                    b[i] = 1 << 30;
                    for (int j : a[i])
                        b[i] = min(b[i], j);
                    break;
                }
                x += a[i].size();
            }
        } else if (z == 1) {
            ++r;
            int mn = 1 << 30;
            int x = 0;
            for (int i = 0; i < a.size(); ++i) {
                int p = l < x ? 0 : l < x + a[i].size() ? 1 : 2;
                int q = r < x + a[i].size() ? 1 : 2;
                if (p == 1 || q == 1) {
                    int sz = min<int>(a[i].size(), r - x);
                    for (int j = max(0, l - x); j < sz; ++j)
                        mn = min(mn, a[i][j]);
                } else if (p == 0 && q == 2) {
                    mn = min(mn, b[i]);
                }
                if (q == 1) break;
                x += a[i].size();
            }
            cout << mn << endl;
        } else {
            int x = 0;
            for (int i = 0; i < a.size(); ++i) {
                if (l < x + a[i].size()) {
                    a[i][l - x] = r;
                    b[i] = 1 << 30;
                    for (int j : a[i])
                        b[i] = min(b[i], j);
                    break;
                }
                x += a[i].size();
            }
        }
        int i = int(Q / sqrt(N));
        if (h % (i + 1) == i) {
            vector<deque<int>> c(1);
            for (auto& p : a) {
                for (int i : p) {
                    if (c.back().size() == M)
                        c.emplace_back();
                    c.back().emplace_back(i);
                }
            }
            a = move(c);
            for (int i = 0; i < a.size(); ++i) {
                b[i] = 1 << 30;
                for (int i : a[i])
                    b[i] = min(b[i], i);
            }
        }
    }
    return 0;
}

