}

// [0, k), [k, size)
std::pair<Node*, Node*> split(Node* p, int k) {
  if( getNum(p) == k ) return std::pair<Node*, Node*>(p, nullptr);
  if( k == 0 ) return std::pair<Node*, Node*>(nullptr, p);
  if( k <= getNum(getLeft(p)) ) {
    Node *left, *right;
    std::tie(left, right) = split(getLeft(p), k);
    return std::pair<Node*, Node*>(left, merge(right, getRight(p)));
  }
  else {
    Node *left, *right;
    std::tie(left, right) = split(getRight(p), k - getNum(getLeft(p)));
    return std::pair<Node*, Node*>(merge(getLeft(p), left), right);
  }
}

// [l, r)
int minimum(Node* p, int l, int r) {
  if( isLeaf(p) ) return p->value;
  //if( l == 0 and r == getNum(p) ) return p->min;
  if( r <= getNum(getLeft(p)) ) {
    return minimum(getLeft(p), l, r);
  }
  else if( getNum(getLeft(p)) <= l ) {
    return minimum(getRight(p), l - getNum(getLeft(p)), r - getNum(getLeft(p)));
  }
  else {
    int leftmin  = minimum(getLeft(p), l, getNum(getLeft(p)));
    int rightmin = minimum(getRight(p), 0, r - getNum(getLeft(p)));
    return std::min(leftmin, rightmin);
  }
}


