	return min(l, r);
}

struct node {
	int val;
	int all;
	node *lch, *rch;
	unsigned int pri;
	int size;
	node(int v, unsigned int p) : val(v), all(v), pri(p), size(1) {
		lch = rch = nullptr;
	}
};

random_device rd;

int count(node *t) { return t == nullptr ? 0 : t->size; }
int que(node *t) { return t == nullptr ? id : t->all; }
node *update(node *t) {
	t->size = count(t->lch) + count(t->rch) + 1;
	t->all = merge(que(t->lch), merge(t->val, que(t->rch)));
	return t;
}
node *merge(node *l, node *r) {
	if (l == nullptr || r == nullptr) return l == nullptr ? r : l;
	if (l->pri > r->pri) {
		l->rch = merge(l->rch, r);
		return update(l);
	}
	else {
		r->lch = merge(l, r->lch);
		return update(r);
	}
}
pair<node*, node*> split(node *t, int k) {
	if (t == nullptr) return make_pair(nullptr, nullptr);
	if (k <= count(t->lch)) {
		pair<node*, node*> s = split(t->lch, k);
		t->lch = s.second;
		return make_pair(s.first, update(t));
	}
	else {
		pair<node*, node*> s = split(t->rch, k - count(t->lch) - 1);
		t->rch = s.first;
		return make_pair(update(t), s.second);
	}
}
node *insert(node *t, int k, int v, unsigned int pri) {
	pair<node*, node*> s = split(t, k);
	node *r = merge(s.first, new node(v, pri));
	r = merge(r, s.second);
	return r;
}
node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	if (s2.first != nullptr) delete s2.first;
	return merge(s1.first, s2.second);
}
node *find(node *t, int k) {
	if (t == nullptr) return t;
	int c = count(t->lch);
	return k < c ? find(t->lch, k) : k == c ? t : find(t->rch, k - (c + 1));
}
//int find(node *t, int l, int r) {
//	if (t == nullptr) return id;
//	if (r < 0 || l >= count(t)) return id;
//	if (l <= 0 && r >= count(t)) return t->all;
//	int c = count(t->lch);
//	return merge(t->lch == nullptr ? id : find(t->lch, l, r), merge(l <= c && c < r ? t->val : id, t->rch == nullptr ? id : find(t->rch, l - (c + 1), r - (c + 1))));
//}
node *find(node *t, int l, int r, int& res) {
	auto t1 = split(t, l);
	auto t2 = split(t1.second, r - l);
	res = t2.first->all;
	return merge(t1.first, merge(t2.first, t2.second));
}
int cnt(node *t, int v) {
	if (t == nullptr) return 0;
	if (t->val < v) return count(t->lch) + 1 + cnt(t->rch, v);
	if (t->val == v) return count(t->lch);
	return cnt(t->lch, v);
}
node *shift(node *t, int l, int r) {
	pair<node*, node*> s1 = split(t, l), s2 = split(s1.second, r - l), s3 = split(s2.second, 1);
	return merge(s1.first, merge(s3.first, merge(s2.first, s3.second)));
}
node *change(node *t, int k, int v) {
	if (t == nullptr) return nullptr;
	int c = count(t->lch);
	if (k < c) {
		t->lch = change(t->lch, k, v);
		update(t);
	}
	else if (k > c) {
		t->rch = change(t->rch, k - (c + 1), v);
		update(t);
	}
	else {
		t->val = v;
		update(t);
	}
	return t;
}

