void view(vvi const& a){
    rep(i, a.size()){
        rep(j, a[i].size()){
            if (a[i][j] == inf) cout << "inf";
            else {
                if (a[i][j] >= 100) cout << a[i][j] / 1000;
                else cout << a[i][j];
            }
            if (j != a[i].size() - 1) cout << " ";
        }
        if (i != a.size() - 1) cout << "|";
    }
