pair<int, int> index(const vvi& tree, int k){
    int s = 0;
    int i = 0;
    while (s + (int)tree[i].size() <= k){
        s += tree[i].size();
        i++;
    }
    int j = 0;
    while (s + j < k) j++;
    return make_pair(i, j);
}

int solve(){

    int w = sqrt(n);
    if (w*w != n) w++;
    vvi tree(w, vi(w, inf));
    vi rmq(w, inf);
    rep(i, w){
        rep(j, w){
            int x = a[i*w + j];
            rmq[i] = min(x, rmq[i]);
            tree[i][j] = x;
        }
    }

    //view(tree);

    rep(_, q){
        int x, y, z; scanf("%d%d%d", &x, &y, &z);
        //printf("----------\n%d %d %d\n", x, y, z);
        if (x == 0){

            // shift
            int L = y, R = z;
            auto p = index(tree, L), q = index(tree, R);
            int i1 = p.first, j1 = p.second;
            int i2 = q.first, j2 = q.second;
            int t = tree[i2][j2];
            tree[i2].erase(tree[i2].begin() + j2);
            tree[i1].insert(tree[i1].begin() + i2, t);

        }
        else if (x == 1){

            // rmq
            int L = y, R = z;
            auto p = index(tree, L), q = index(tree, R);
            int i1 = p.first, j1 = p.second;
            int i2 = q.first, j2 = q.second;
            int res = inf;
            if (i1 == i2){
                loop(t, j1, j2 + 1){
                    res = min(res, tree[i1][t]);
                }
            }
            else{
                loop(t, j1, tree[i1].size()){
                    res = min(res, tree[i1][t]);
                }
                loop(t, i1 + 1, i2){
                    res = min(res, rmq[t]);
                }
                loop(t, 0, j2 + 1){
                    res = min(res, tree[i2][t]);
                }
            }
            printf("%d\n", res);

        }
        else if (x == 2){

            // update
            int k = y, x = z;
            auto p = index(tree, k);
            tree[p.first][p.second] = x;
            rmq[p.first] = min(rmq[p.first], x);

        }

        //view(tree);
    }
    return 0;
}

int main(){
    while (scanf("%d%d", &n, &q) != EOF){
        rep(i, 300000) a[i] = inf;
        rep(i, n) scanf("%d", a + i);
        solve();
    }
}

