#define INF (1 << 30)
struct Node{
    int val, min, size;
    Node *l, *r;
    Node(int v){
	size = 1;
	val = v;
	min = v;
	l = r = NULL;
    }
};

typedef pair<Node*, Node*> P;

Node *root = new Node(0);

Node *update(Node *a){
    if(a == 0)return a;
    a->min = min(a->l?a->l->min:INF, a->r?a->r->min:INF);
    a->min = min(a->min, a->val);
    a->size = 1 + (a->l?a->l->size:0) + (a->r?a->r->size:0);
    return a;
}

Node *merge(Node *a, Node *b){
    if(a == NULL)return b;
    if(b == NULL)return a;
    if(rand() % (a->size + b->size) < a->size){
	a->r = merge(a->r, b);
	return update(a);
    }
    else{
	b->l = merge(a, b->l);
	return update(b);
    }
}

P split(Node *p, int v){
    if(v == 0)return P(NULL, p);
    int lsize = (p->l)?p->l->size:0;
    if(lsize < v){
	P tmp = split(p->r, v - lsize - 1);
	p->r = tmp.first;
	return P(update(p), update(tmp.second));
    }
    else{
	P tmp = split(p->l, v);
	p->l = tmp.second;
	return P(update(tmp.first), update(p));
    }
}

void shift(int l, int r){
    P tmpr = split(root, r + 1);
    P tmpl = split(tmpr.first, l);
    P tmpc = split(tmpl.second, r - l);
    tmpl.second = merge(tmpc.second, tmpc.first);

    tmpr.first = merge(tmpl.first, tmpl.second);
    root = merge(tmpr.first, tmpr.second);
}

int solve(int l, int r){
    P tmpr = split(root, r);
    P tmpl = split(tmpr.first, l);
    int ans = tmpl.second->min;
    tmpr.first = merge(tmpl.first, tmpl.second);
    root = merge(tmpr.first, tmpr.second);
    return ans;
}

void setnum(int x, int v){
    P tmpr = split(root, x);
    P tmpl = split(tmpr.second, 1);
    tmpr.second = merge(new Node(v), tmpl.second);
    root = merge(tmpr.first, tmpr.second);
}

