    int sum(Node* t)
    {
        return t == nullptr ? 0 : t->sum;
    }

    int rmin(Node* t)
    {
        return t != nullptr ? t->min : INF;
    }

    Node* update(Node* t)
    {
        t->cnt = count(t->lch) + count(t->rch) + 1;
        t->sum = sum(t->lch) + sum(t->rch) + t->val;
        t->min = min(min(rmin(t->lch), rmin(t->rch)), t->val);
        return t;
    }

    Node* merge(Node* l, Node* r)
    {
        if (l == nullptr || r == nullptr) {
            return (l == nullptr ? r : l);
        }

        if (l->pri > r->pri) {
            l->rch = merge(l->rch, r);
            return update(l);
        } else {
            r->lch = merge(l, r->lch);
            return update(r);
        }
    }

    pair<Node*, Node*> split(Node* t, int k)
    {
        if (t == nullptr) {
            return {nullptr, nullptr};
        }

        if (k <= count(t->lch)) {
            auto s = split(t->lch, k);
            t->lch = s.second;
            return {s.first, update(t)};
        } else {
            auto s = split(t->rch, k - count(t->lch) - 1);
            t->rch = s.first;
            return {update(t), s.second};
        }
    }

    Node* insert(Node* t, int k, int val, int pri)
    {
        auto s = split(t, k);
        t = merge(s.first, new Node{val, pri});
        t = merge(t, s.second);
        return update(t);
    }

    Node* erase(Node* t, int k)
    {
        auto s1 = split(t, k + 1);
        auto s2 = split(s1.first, k);
        t = merge(s2.first, s1.second);
        return update(t);
    }

    int range_min(Node* t, int l, int r)
    {
        l = max(l, 0); r = min(r, count(t));
        if (l >= r) return INF;
        if (l == 0 && r == count(t)) {
            return t->min;
        }

        int sl = count(t->lch);
        int res = min(range_min(t->lch, l, r),
                      range_min(t->rch, l - sl - 1, r - sl - 1));

        if (l <= sl && sl < r) {
            res = min(res, t->val);
        }

        return res;            
    }

  public:
    Treap() : root{nullptr} {}

    int size()
    {
        return count(root);
    }

    void insert(int k, int val)
    {
        root = insert(root, k, val, rand());
    }

    void erase(int k)
    {
        root = erase(root, k);
    }

    void update(int k, int val)
    {
        erase(k);
        insert(k, val);
    }

    void shift(int l, int r)
    {
        auto s1 = split(root, r);
        auto s2 = split(s1.first, r - 1);
        auto s3 = split(s2.first, l);
        root = merge(s3.first, s2.second);
        root = merge(root, s3.second);
        root = merge(root, s1.second);
    }   

    int range_min(int l, int r)
    {
        return range_min(root, l, r + 1);
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, Q;
    cin >> N >> Q;

    Treap t;
    for (int i = 0; i < N; i++) {
        int a;
        cin >> a;
        t.insert(i, a);
    }

    while (Q--) {
        int x, y, z;
        cin >> x >> y >> z;

        switch (x) {
            case 0:
                t.shift(y, z + 1);
                break;

            case 1:
                cout << t.range_min(y, z) << endl;
                break;

            case 2:
                t.update(y, z);
                break;
        }
    }    
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using T = int;
const T id = INT_MAX;
T op(T l, T r) {
	return min(l, r);
}

using COL = bool;
const COL RED = false, BLACK = true;

struct node {
	COL color;
	int size;
	int level;
	T val, all;
	node *p, *ch[2];
	node() : color(BLACK), size(0), level(0), val(id), all(id), p(nullptr), ch{ nullptr, nullptr } {}
	node(COL c, T v, node *par, node *l, node *r) : color(c), size(1), level(0), val(v), all(v), p(par), ch{ l, r } {}
};

node* const NIL = new node();

node* new_node(T val) {
	return new node(RED, val, NIL, NIL, NIL);
}
void update(node *x) {
	x->size = x->ch[0]->size + 1 + x->ch[1]->size;
	x->level = x->ch[0]->level + (x->color == BLACK);
	x->all = op(op(x->ch[0]->all, x->val), x->ch[1]->all);
}
void update(node *root, node *x) {
	while (x != NIL) update(x), x = x->p;
}
void rotate(node *&root, node *x, int b) {
	node *y = x->ch[1 - b];
	x->ch[1 - b] = y->ch[b];
	if (y->ch[b] != NIL) {
		y->ch[b]->p = x;
	}
	y->p = x->p;
	if (x->p == NIL) {
		root = y;
	}
	else {
		x->p->ch[x != x->p->ch[0]] = y;
	}
	y->ch[b] = x;
	x->p = y;
	update(x);
	update(y);
}
void insert_fix(node *&root, node *x) {
	while (x->p->color == RED) {
		int b = (x->p != x->p->p->ch[0]);
		node *y = x->p->p->ch[1 - b];
		if (y->color == RED) {
			x->p->color = BLACK;
			y->color = BLACK;
			x->p->p->color = RED;
			x = x->p->p;
			continue;
		}
		if (x == x->p->ch[1 - b]) {
			x = x->p;
			rotate(root, x, b);
		}
		x->p->color = BLACK;
		x->p->p->color = RED;
		rotate(root, x->p->p, 1 - b);
	}
	root->color = BLACK;
}
void transplant(node *&root, node *u, node *v) {
	if (u->p == NIL) {
		root = v;
	}
	else {
		u->p->ch[u != u->p->ch[0]] = v;
	}
	v->p = u->p;
}
void erase_fix(node *&root, node *x) {
	while (x != root && x->color == BLACK) {
		int b = (x != x->p->ch[0]);
		node *w = x->p->ch[1 - b];
		if (w->color == RED) {
			w->color = BLACK;
			x->p->color = RED;
			rotate(root, x->p, b);
			w = x->p->ch[1 - b];
		}
		if (w->ch[b]->color == BLACK && w->ch[1 - b]->color == BLACK) {
			w->color = RED;
			x = x->p;
			continue;
		}
		if (w->ch[1 - b]->color == BLACK) {
			w->ch[b]->color = BLACK;
			w->color = RED;
			rotate(root, w, 1 - b);
			w = x->p->ch[1 - b];
		}
		w->color = x->p->color;
		x->p->color = BLACK;
		w->ch[1 - b]->color = BLACK;
		rotate(root, x->p, b);
		x = root;
	}
	x->color = BLACK;
}
node* find(node *&root, int k) {
	if (k < 0 || root->size <= k) return NIL;
	node *x = root;
	while (x->ch[0]->size != k) {
		if (k < x->ch[0]->size) {
			x = x->ch[0];
		}
		else {
			k -= x->ch[0]->size + 1;
			x = x->ch[1];
		}
	}
	return x;
}
void insert(node *&root, int k, T val) {
	node *y = NIL, *v = new_node(val);
	if (root == NIL) {
		root = v;
	}
	else if (k == 0) {
		y = find(root, 0);
		y->ch[0] = v;
	}
	else {
		y = find(root, k - 1);
		if (y->ch[1] == NIL) {
			y->ch[1] = v;
		}
		else {
			y = find(y->ch[1], 0);
			y->ch[0] = v;
		}
	}
	v->p = y;
	update(root, y);
	insert_fix(root, v);
}
void erase(node *&root, node *x) {
	if (x == NIL) return;
	node *y = x, *z;
	COL c = y->color;
	if (x->ch[0] == NIL) {
		z = x->ch[1];
		transplant(root, x, x->ch[1]);
	}
	else if (x->ch[1] == NIL) {
		z = x->ch[0];
		transplant(root, x, x->ch[0]);
	}
	else {
		y = find(x->ch[1], 0);
		c = y->color;
		z = y->ch[1];
		if (y->p == x) {
			z->p = y;
		}
		else {
			transplant(root, y, y->ch[1]);
			y->ch[1] = x->ch[1];
			y->ch[1]->p = y;
		}
		transplant(root, x, y);
		y->ch[0] = x->ch[0];
		y->ch[0]->p = y;
		y->color = x->color;
		update(y);
	}
	update(root, z->p);
	if (c == BLACK) {
		erase_fix(root, z);
	}
}
void erase(node *&root, int k) {
	node *x = find(root, k);
	erase(root, x);
}
T find(node *t, int l, int r) {
	if (t == NIL || r <= 0 || t->size <= l) return id;
	if (l <= 0 && t->size <= r) return t->all;
	T res = id;
	res = op(res, find(t->ch[0], l, r));
	int c = t->ch[0]->size;
	if (l <= c && c < r) res = op(res, t->val);
	res = op(res, find(t->ch[1], l - (c + 1), r - (c + 1)));
	return res;
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q, x, y, z, a;
	cin >> n >> q;
	node *root = NIL;
	for (int i = 0; i < n; i++) {
		cin >> a;
		insert(root, i, a);
	}
	while (q--) {
		cin >> x >> y >> z;
		if (x == 0) {
			node* t = find(root, z);
			int val = t->val;
			erase(root, t);
			insert(root, y, val);
		}
		else if (x == 1) {
			printf("%d\n", find(root, y, z + 1));
		}
		else {
			node *t = find(root, y);
			t->val = z;
			update(root, t);
		}
	}
	return 0;
}

