/*--------------------template--------------------*/


pii place(vector<vi> &v, int p)
{
	int cnt = 0;
	REP(i, v.size())
	{
		if (cnt <= p && p < cnt+v[i].size())
		{
			return pii(i, p - cnt);
		}
		else cnt += v[i].size();
	}
}

void copy(vector<vi> &to, vi &from, int s)
{
	REP(i, from.size())
	{
		to[i / s].push_back(from[i]);
	}
}

