const int INF = 1001001001;
int main() {
    TreapArray<int, INF> a;
    int n, q;
    cin >> n >> q;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        a.push_back(x);
    }

    auto rotate = [&](int L, int R) {
        int len = R - L + 1;
        Treap<int, INF>::Node *l, *m1, *m2, *r;
        tie(l, r) = a.split(a.root, L);
        tie(m1, r) = a.split(r, len);
        tie(m1, m2) = a.split(m1, len - 1);
        m1 = a.merge(m2, m1);
        r = a.merge(m1, r);
        a.root = a.merge(l, r);
    };

    while (q--) {
        int x, y, z;
        cin >> x >> y >> z;
        if (x == 0) {
            rotate(y, z);
        } else if (x == 1) {
            cout << a.query(y, z + 1) << endl;
        } else {
            a.change(y, z);
        }
    }
    return 0;
}

