struct SplayTree{
	struct Node{
		int x,sz,mini;
		Node *l,*r,*p;
		Node(int x,Node *p):x(x),sz(1),mini(x),p(p),l(NULL),r(NULL){}
	};

	Node *root;

	SplayTree():root(NULL){}

	void Update(Node *n){
		if(n==NULL) return;
		n->mini=n->x;
		n->sz=1;
		if(n->l!=NULL){
			n->mini=min(n->mini,n->l->mini);
			n->sz+=n->l->sz;
		}
		if(n->r!=NULL){
			n->mini=min(n->mini,n->r->mini);
			n->sz+=n->r->sz;
		}
	}

	void Rotate(Node *n){
		Node *p=n->p,*pp=p->p;

		n->p=pp;
		if(pp==NULL) root=n;
		else{
			if(p==pp->l) pp->l=n;
			else pp->r=n;
		}

		p->p=n;
		if(p->l==n){
			p->l=n->r;
			if(n->r!=NULL) n->r->p=p;
			n->r=p;
		}else{
			p->r=n->l;
			if(n->l!=NULL) n->l->p=p;
			n->l=p;
		}
		Update(p);
		Update(n);
	}

	void Splay(Node *n){
		while(n->p){
			Node *p=n->p;
			if(!p->p){
				//zig
				Rotate(n);
			}else{
				Node *pp=p->p;
				if(pp->l==p){
					if(p->l==n){
						//zig-zig
						Rotate(p);
						Rotate(n);
					}else{
						//zig-zag
						Rotate(n);
						Rotate(n);
					}
				}else if(pp->r==p){
					if(p->l==n){
						//zig-zag
						Rotate(n);
						Rotate(n);
					}else{
						//zig-zig
						Rotate(p);
						Rotate(n);
					}
				}
			}
		}
	}

	Node* Find(Node *t,int k){	//1-indexed
		if(t==NULL) return NULL;
		int l_sz=Size(t->l),r_sz=Size(t->r);

		if(l_sz+1==k) return t;
		if(k<=l_sz) return Find(t->l,k);
		return Find(t->r,k-l_sz-1);
	}

	void Insert(Node *t,int k,int x){
		Node *p=Find(t,k);
		if(p==NULL){ //木が空
			root=new Node(x,NULL);
			return;
		}

		Splay(p);
		dump(p->x);
		Node *n=new Node(x,p);
		n->r=p->r;
		p->r=n;
		//ShowTree(n);
		Splay(n);
	}

	void Erase(Node *t,int k){
		Node *n=Find(t,k+1);
		if(n==NULL) return;
		Splay(n);

		if(n->l==NULL){
			root=n->r;
			n->r->p=NULL;
			delete n;
			return;
		}

		Node *new_root=Max(n->l);
		Node *p=new_root->p;
		new_root->p->r=NULL;
		new_root->p=NULL;
		new_root->r=n->r;
		n->r->p=new_root;
		root=new_root;
		while(p!=NULL){
			Update(p);
			p=p->p;
		}
	}

	Node *Max(Node *t){
		if(t==NULL) return NULL;
		while(t->r!=NULL) t=t->r;
		return t;
	}

	Node* Merge(Node *l,Node *r){
		if(l==NULL) return r;
		else if(r==NULL) return l;
		l=Max(l);
		Splay(l);
		Splay(r);
		l->r=r;
		r->p=l;
		Update(l);
		return l;
	}

	pair<Node*,Node*> Split(Node *t,int k){ //[,k),[k,)
		Node *l=Find(t,k);
		if(l==NULL){
			dump("split failed");
