}

Node* initNode(Node* base, Node* left, Node* right) {
#ifdef Persistent
  //Node *res = new Node;
  Node *res = nheap.next();
#else
  Node *res = base != nullptr ? base : nheap.next();
#endif
  res->left = left;
  res->right = right;
  res->num = 0;
  res->value = 0;
  res->min = (1 << 30);
  return res;
}

bool isLeaf(Node* p) {
  if( p == nullptr ) return false;
  return p->left == nullptr and p->right == nullptr;
}

