pii place(vector<vi> &v, int p)
{
	int cnt = 0;
	for(int i = 0;; i++)
	{
		if (cnt + v[i].size() <= p)
		{
			cnt += v[i].size();
		}
		else return pii(i, p - cnt);
	}
}

void copy(vector<vi> &to, vi &from, int s)
{
	REP(i, from.size())
	{
		to[i/s].push_back(from[i]);
	}
}

