int count(node *t) { return t ? t->size : 0; }
int que(node *t) { return t ? t->all : id; }

node *new_leaf(T v) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(v);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(v);
	return pool + it++;
}

node *new_node(node *l, node *r) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(l, r);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(l, r);
	return pool + it++;
}

void delete_node(node* t) {
	deleted.push(t - pool);
}

node *update(node *t) {
	t->dep = max(depth(t->ch[0]), depth(t->ch[1])) + 1;
	t->all = op(que(t->ch[0]), op(t->val, que(t->ch[1])));
	t->size = count(t->ch[0]) + count(t->ch[1]) + (!t->ch[0] || !t->ch[1]);
	return t;
}

node *rotate(node *t, int b) {
	node *s = t->ch[1 - b];
	t->ch[1 - b] = s->ch[b];
	s->ch[b] = t;
	t = update(t);
	s = update(s);
	return s;
}

node *fix(node *t) {
	if (!t) return t;
	int dd = depth(t->ch[0]) - depth(t->ch[1]);
	if (abs(dd) < 2) return t;
	int b = dd < 0;
	if (depth(t->ch[b]->ch[!b]) > depth(t->ch[b]->ch[b])) {
		t->ch[b] = rotate(t->ch[b], b);
	}
	return rotate(t, !b);
}

node *merge(node *l, node *r) {
	if (!l) return r;
	if (!r) return l;
	if (l->dep == r->dep) return new_node(l, r);
	if (l->dep < r->dep) {
		r->ch[0] = merge(l, r->ch[0]);
		return fix(update(r));
	}
	l->ch[1] = merge(l->ch[1], r);
	return fix(update(l));
}

pair<node*, node*> split(node *t, int k) {
	if (!t) return make_pair(nullptr, nullptr);
	if (k == 0) return make_pair(nullptr, t);
	if (k >= count(t)) return make_pair(t, nullptr);
	int c = count(t->ch[0]);
	node *l = t->ch[0], *r = t->ch[1];
	delete_node(t);
	if (k < c) {
		pair<node*, node*> p = split(l, k);
		return make_pair(p.first, merge(p.second, r));
	}
	if (k > c) {
		pair<node*, node*> p = split(r, k - c);
		return make_pair(merge(l, p.first), p.second);
	}
	return make_pair(l, r);
}

node *insert(node *t, int k, T v) {
	pair<node*, node*> s = split(t, k);
	return merge(merge(s.first, new_leaf(v)), s.second);
}

node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	return merge(s1.first, s2.second);
}

node *find(node *t, int k) {
	if (!t) return t;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	return c == 0 && b ? t : k < c ? find(t->ch[0], k) : find(t->ch[1], k - c - b);
}

T find(node *t, int l, int r) {
	if (!t) return id;
	if (r < 0 || l >= count(t)) return id;
	if (l <= 0 && r >= t->size) return t->all;
	int c = count(t->ch[0]), d = c + (!t->ch[0] || !t->ch[1]);
	return op(!t->ch[0] ? id : find(t->ch[0], l, r), op(l <= c && c < r ? t->val : id, !t->ch[1] ? id : find(t->ch[1], l - d, r - d)));
}

void update(node *t, int k, T val) {
	if (!t) return;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	if (c == 0 && b) {
		t->val = val;
	}
	else if (k < c) {
		update(t->ch[0], k, val);
	}
	else {
		update(t->ch[1], k - c - b, val);
	}
	update(t);
}

node* build(const vector<T>& a, int lb, int ub) {
	if (ub - lb == 1) return new_leaf(a[lb]);
	int m = (lb + ub) >> 1;
	return merge(build(a, lb, m), build(a, m, ub));
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q;
	cin >> n >> q;
	vector<T> a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	node* root = build(a, 0, n);
	while (q--) {
		int x, y, z;
		cin >> x >> y >> z;
		if (x == 0) {
			int val = find(root, z)->val;
			root = insert(erase(root, z), y, val);
		}
		else if (x == 1) {
			printf("%d\n", find(root, y, z + 1));
		}
		else {
			update(root, y, z);
		}
	}
	return 0;
}

