int main(){
  const int n = getInt();
  const int q = getInt();

  const int c = n / floor(sqrt(n) + 1e-9);
  const int m = n / c + (n % c == 0 ? 0 : 1);

  vector<deque<int> > v(m);
  vector<multiset<int> > s(m);

  REP(i,n){
    const int a = getInt();
    v[i / c].push_back(a);
    s[i / c].insert(a);
  }

  REP(qq, q){
    const int x = getInt();
    const int y = getInt();
    const int z = getInt();

    if(x == 1){
      const int lIdx = y / c;
      const int rIdx = z / c;

      int ans = INT_MAX;
      if(lIdx == rIdx){
        for(int i = y % c; i <= z % c; i++)
          ans = min(ans, v[lIdx][i]);
      }else{
        for(int i = y % c; i < c; i++)
          ans = min(ans, v[lIdx][i]);

        for(int i = 0; i <= z % c; i++)
          ans = min(ans, v[rIdx][i]);

        for(int i = lIdx + 1; i < rIdx; i++)
          ans = min(ans, *s[i].begin());
      }

      printf("%d\n", ans);
    }else if(x == 0){
      const int lIdx = y / c;
      const int rIdx = z / c;

      const int rmemo = v[rIdx][z % c];

      v[rIdx].erase(v[rIdx].begin() + z % c);
      s[rIdx].erase(s[rIdx].find(rmemo));

      for(int i = rIdx; i > lIdx; i--){
        v[i].push_front(v[i - 1][c - 1]);
        s[i].insert(v[i - 1][c - 1]);

        s[i - 1].erase(s[i - 1].find(v[i - 1][c - 1]));
        v[i - 1].pop_back();
      }

      v[lIdx].insert(v[lIdx].begin() + y % c, rmemo);
      s[lIdx].insert(rmemo);

      // REP(i,n) printf("%d ", v[i / c][i % c]); puts("");
    }else{
      const int original = v[y / c][y % c];
      v[y / c][y % c] = z;
      s[y / c].erase(s[y / c].find(original));
      s[y / c].insert(z);
    }
  }

  return 0;
}

