using namespace std;


int db[200010];

void CircularShift(int begin, int end)
{   
    int temp;

    for (int i = begin; i < end; ++i) {
        temp = db[i + 1];

        db[i + 1] = db[i];
    }

    db[begin] = temp;
}

int SearchMin(int begin, int end)
{
    int ans = db[begin];

    for (int i = begin; i < end; ++i) {
        ans = min(ans, db[i + 1]);
    }

    return ans;
}

void Update(int pos, int val)
{
    db[pos] = val;
}

int main()
{
    int n, q;

    cin >> n >> q;

    for (int i = 0; i < n; ++i) {
        cin >> db[i];
    }

    int quary;
    int begin, end, pos, val;

    for (int i = 0; i < q; ++i) {
        cin >> quary;

        switch (quary) {
            case 0:
                cin >> begin >> end;

                CircularShift(begin, end);

                break;

            case 1:
                cin >> begin >> end;

                cout << SearchMin(begin, end) << endl;

                break;

            case 2:
                cin >> pos >> val;

                Update(pos, val);

                break;

            default:
                break;
        }
    }

    return 0;
}

