#define MAX_NQ 200000

void CS(int a[],int l,int r){
	int tmp, i;
	tmp = a[r];
	for(i = r;i > l;i--)
		a[i] = a[i - 1];
	a[l] = tmp;
}

int min_l_to_r(int a[],int l,int r){
	int i, min = 0x7FFFFFFF;
	for(i = l;i <= r;i++)
		if(min > a[i]) min = a[i];
	return min;
}

void renew(int a[],int pos,int val){
	a[pos] = val;
}


int main(void){
	int i, j;
	int n, q, a[MAX_NQ], x, y, z;
	scanf("%d%d",&n,&q);
	for(i = 0;i < n;i++)
		scanf("%d",&a[i]);
	for(i = 0;i < q;i++){
		scanf("%d%d%d",&x,&y,&z);
		if(!x)
			CS(a,y,z);
		else if(x == 1)
			printf("%d\n",min_l_to_r(a,y,z));
		else
			renew(a,y,z);
	}
	return 0;
}

