template<typename T>
class randomized_binary_search_tree {
public:
	struct node {
		node(T val): val(val), min(val), size(1){}
		T val, min;
		node *lch, *rch;
		size_t size;
	};

	randomized_binary_search_tree(): root(nullptr){}

	size_t size(){
		return size(root);
	}

	void insert(size_t k, T val){
		root = insert(root, k, val);
	}

	void erase(size_t k){
		root = erase(root, k);
	}

	node *find(size_t k){
		node *v = root;
		while (v){
			size_t s = size(v->lch);
			if (s == k) return v;
			if (s < k) v = v->lch;
			else {
				v = v->rch;
				k -= s + 1;
			}
		}
		return v;
	}

private:
	size_t size(node *t){
		return !t ? 0 : t->size;
	}

	T min(node *t){
		return !t ? 1001001001 : t->min;
	}

	node *update(node *t){
		t->size = size(t->lch) + size(t->rch) + 1;
		t->min = ::min({min(t->lch), min(t->rch), t->val});
		return t;
	}

	node *merge(node *s, node *t){
		if (!s) return t;
		if (!t) return s;
		if (size(s) < rand() % (size(s) + size(t))){
			s->rch = merge(s->rch, t);
			return update(s);
		}
		else {
			t->lch = merge(s, t->lch);
			return update(t);
		}
	}

	pair<node*, node*> split(node *t, size_t k){
		if (!t) return make_pair(nullptr, nullptr);
		if (k <= size(t->lch)){
			auto s = split(t->lch, k);
			t->lch = s.second;
			return make_pair(s.first, update(t));
		}
		else {
			auto s = split(t->rch, k - size(t->lch) - 1);
			t->rch = s.first;
			return make_pair(update(t), s.second);
		}
	}

	node *insert(node *t, size_t k, T val){
		auto s = split(t, k);
		t = merge(s.first, new node(val));
		t = merge(t, s.second);
		return update(t);
	}

	node *erase(node *t, size_t k){
		pair<node*, node*> u, v;
		u = split(t, k + 1);
		v = split(u.first, k);
		t = merge(v.first, u.second);
		return update(t);
	}

	node *root;

public:
	void query0(size_t l, size_t r){
		auto a = split(root, l);
		auto b = split(a.second, r - l - 1);
		auto c = split(b.second, 1);
		auto t = merge(a.first, c.first);
		t = merge(t, b.first);
		t = merge(t, c.second);
		root = t;
	}

	T query1(size_t l, size_t r){
		return query1(l, r, root, 0, size());
	}

	T query1(size_t l, size_t r, node *t, size_t a, size_t b){
		if (r <= a || b <= l) return 1001001001;
		if (l <= a && b <= r) return min(t);
		return ::min({
			t->val,
			query1(l, r, t->lch, a, a + size(t->lch)),
			query1(l, r, t->rch, a + size(t->lch) + 1, b)
		});
	}

	void query2(size_t p, T v){
		erase(p);
		insert(p, v);
	}
};

