using namespace std;

struct Node{
	Node *l,*r;
	int d,s,mn;
};

using NP=Node*;

const int poolSize=1000000;
Node buf[poolSize];
stack<NP> pool;
void InitPool(){
	REP(i,poolSize)
		pool.push(buf+i);
}

int Depth(NP x){
	return x?x->d:0;
}

int Size(NP x){
	return x?x->s:0;
}

const int inf=1145141919;

int Mini(NP x){
	return x?x->mn:inf;
}

void delNode(NP x){
	pool.push(x);
}

NP newNode(NP l,NP r,int v=inf){
	NP x=pool.top();
	pool.pop();
	*x=Node{l,r,max(Depth(l),Depth(r))+1,Size(l)+Size(r),min({v,Mini(l),Mini(r)})};
	return x;
}

Node Merge1(NP a,NP b,NP c){
	if(abs(max(Depth(a),Depth(b))+1-Depth(c))<=1)
		return Node{newNode(a,b),c};
	else if(abs(max(Depth(b),Depth(c))+1-Depth(a))<=1)
		return Node{a,newNode(b,c)};
	Node ret=Node{newNode(a,b->l),newNode(b->r,c)};
	delNode(b);
	return ret;
}

Node Merge2(NP a,NP b){
	if(Depth(a)==Depth(b))
		return Node{a,b};
	else if(Depth(a)>Depth(b)){
		Node m=Merge2(a->r,b);
		Node ret=Merge1(a->l,m.l,m.r);
		delNode(a);
		return ret;
	}else{
		Node m=Merge2(a,b->l);
		Node ret=Merge1(m.l,m.r,b->r);
		delNode(b);
		return ret;
	}
}

NP Merge(NP a,NP b){
	if(!a)
		return b;
	if(!b)
		return a;
	Node m=Merge2(a,b);
	return newNode(m.l,m.r);
}

Node Split(NP x,int k){
	if(k<=0)
		return Node{NULL,x};
	if(Size(x)<=k)
		return Node{x,NULL};
	if(k<=Size(x->l)){
		Node s=Split(x->l,k);
		Node ret=Node{s.l,Merge(s.r,x->r)};
		delNode(x);
		return ret;
	}else{
		Node s=Split(x->r,k-Size(x->l));
		Node ret=Node{Merge(x->l,s.l),s.r};
		delNode(x);
		return ret;
	}
}

void Update(NP x,int k,int v){
	if(Size(x)==1){
		x->mn=v;
		return;
	}
	if(k<Size(x->l))
		Update(x->l,k,v);
	else
		Update(x->r,k-Size(x->l),v);
	x->mn=min(Mini(x->l),Mini(x->r));
}

