using namespace std;

typedef int ut;
const int INF = 1<<29;

struct Node {
	ut value, minum;
	//ut sum;
	int size;
	Node* lch;
	Node* rch;
	Node(ut v) : value(v), minum(v), size(1),lch(NULL), rch(NULL) {
		//sum = v;
	}
};

typedef pair<Node*, Node*> npr;

struct RBST {
	Node* root;

	RBST(){
		srand(time(NULL));
	}

	int size(Node* t) { return !t ? NULL : t->size; }
	//int sum(Node* t) { return !t ? NULL : t->sum; }
	int minum(Node* t) { return !t ? INF : t->minum; }

	Node* update(Node* t){
		t->size = size(t->lch) + size(t->rch) + 1;
		t->minum = min(t->value, min(minum(t->lch), minum(t->rch)));
		//t->sum = sum(t->lch) + sum(t->rch) + t->value;
		return t;
	}

	Node* merge(Node* l, Node* r){
		if(!l || !r)
			return !l ? r : l;

		int m = l->size, n = r->size;
		if(rand() % (m + n) < m){
			l->rch = merge(l->rch, r);
			return update(l);
		}
		else{
			r->lch = merge(l, r->lch);
			return update(r);
		}
	}

	npr split(Node* t, int k){ // [0, k), [k, n)
		if(!t)
			return npr(NULL, NULL);
		if(k <= size(t->lch)){
			npr s = split(t->lch, k);
			t->lch = s.second;
			return npr(s.first, update(t));
		}
		else{
			npr s = split(t->rch, k - size(t->lch) - 1);
			t->rch = s.first;
			return npr(update(t), s.second);
		}
	}

	Node* insert(Node* t, int k, ut v){
		npr tmp = split(t, k);
		Node *p = new Node(v);
		return merge(merge(tmp.first, p), tmp.second);
	}

	Node* erase(Node* t, int k){
		npr tmp = split(t, k);
		return merge(tmp.first, split(tmp.second, 1).second);
	}

	void shift(int l, int r){
		npr a = split(root, r);
		npr b = split(a.first, l);
		npr c = split(a.second, 1);

		root = merge(merge(b.first, c.first), merge(b.second, c.second));
	}

	ut min_query(int l, int r){
		npr a = split(root, l);
		npr b = split(a.second, r-l+1);
		ut ans = b.first->minum;
		root = merge(a.first, merge(b.first, b.second));
		return ans;
	}

	void update_value(int k, int v){
		root = erase(root, k);
		root = insert(root, k, v);
	}
};

int main() {
	RBST* rbst = new RBST();
	int N, Q, a, x, y, z;
	cin >> N >> Q;
	for(int i = 0; i < N; ++i){
		scanf("%d", &a);
		rbst->root = rbst->insert(rbst->root, i, a);
	}

	for(int i = 0; i < Q; ++i){
		scanf("%d%d%d", &x, &y, &z);
		if(x == 0){
			rbst->shift(y, z);
		}
		else if(x == 1){
			printf("%d\n", rbst->min_query(y, z));
		}
		else{
			rbst->update_value(y, z);
		}
	}
	return 0;
}

