}

#include<iostream>
#include<algorithm>
#include<utility>
using namespace std;

#define INF (1<<30)


class DynamicRMQ {
	struct Node {
		int bf;//balance factor left-right
		Node *left, *right;
		int size;
		int val, minsub;

		Node(int k, int v)
			:bf(0), left(0), right(0), size(1), val(v), minsub(v) {}
		~Node() {
			if (left)delete left;
			if (right)delete right;
		}
		Node *rotate_left() {
			Node *s = right;
			right = s->left;
			s->left = this;
			s->left->update();
			return s;
		}
		Node *rotate_right() {
			Node *s = left;
			left = s->right;
			s->right = this;
			s->right->update();
			return s;
		}
		Node *balance_left() {
			if (left->bf > 0)return rotate_right();
			else {
				left = left->rotate_left();
				return rotate_right();
			}
		}
		Node *balance_right() {
			if (right->bf < 0)return rotate_left();
			else {
				right = right->rotate_right();
				return rotate_left();
			}
		}
		pair<bool,Node*> insert(int k, int v) {
			if (!this)return make_pair(true,new Node(k, v));
			int si = left ? left->size : 0;
			pair<bool, Node*> res;
			if (k <= si) {
				res = left->insert(k, v);
				left = res.second;
				if (res.first && ++bf==2) {
					bf = 0;
					return make_pair(false, balance_left()->update());
				}
			}
			else {//key < k
				res = right->insert(k - si - 1, v);
				right = res.second;
				if (res.first && --bf == -2) {
					bf = 0;
					return make_pair(false, balance_right()->update());
				}
			}
			return make_pair(false,update());
		}

		pair<bool, Node*> erase(int k) {
			if (!this)return make_pair(false,(Node*)NULL);
			int si = left ? left->size : 0;
			pair<bool, Node*> res;
			if (k == si) {
				Node *le = left,*ri = right;
				left = right = NULL;
				delete this;
				if (!le) {
					return make_pair(true,ri);
				}
				if (!ri) {
					return make_pair(true,le);
				}
				Node *t;
				res = le->erase_max(&t);
				t->left = res.second;
				t->right = ri;
				if (res.first && --bf == -2) {
					bf = 0;
					return make_pair(true, balance_right()->update());
				}
			}
			if (k < si) {
				res = left->erase(k);
				left = res.second;
				if (res.first && --bf == -2) {
					bf = 0;
					return make_pair(true, balance_right()->update());
				}
			}
			else if (si < k) {
				res = right->erase(k - si - 1);
				right = res.second;
				if (res.first && ++bf == 2) {
					bf = 0;
					return make_pair(true, balance_left()->update());
				}
			}
			return make_pair(false,update());
		}
		int min(int a, int b, int l, int r)const {
			if (!this || r<a || b<l)return INF;
			if (a <= l && r <= b)return minsub;
			int si = left ? left->size : 0;
			int res = a <= l + si&&l + si<b ? val : INF;
			res = std::min(res, left->min(a, b, l, l + si));
			res = std::min(res, right->min(a, b, l + si + 1, r));
			return res;
		}
		Node *update() {
			update_size();
			update_min();
			return this;
		}
		void update_size() {
			if (!this)return;
			size = 1 + (left ? left->size : 0) + (right ? right->size : 0);
		}
		void update_min() {
			if (!this)return;
			minsub = val;
			if (left)minsub = std::min(minsub, left->minsub);
			if (right)minsub = std::min(minsub, right->minsub);
		}
		pair<bool, Node*> erase_max(Node **maxnode) {
			if (right) {
				pair<bool, Node*> res = right->erase_max(maxnode);
				right = res.second;
				if (res.first && --bf==-2) {
					bf = 0;
					return make_pair(true, rotate_right()->update());
				}
				return make_pair(false,update());
			}
			else {
				*maxnode = this;
				return make_pair(true,left);
			}
		}
	} *root;
public:
	DynamicRMQ() :root(0) {}
	~DynamicRMQ() { if (root)delete root; }
	void insert(int k, int v) {
		root = root->insert(k, v).second;
	}
	void erase(int k) {
		root = root->erase(k).second;
	}
	void set(int k, int v) {
		root = root->erase(k).second;
		root = root->insert(k, v).second;
	}
	int min(int a, int b)const {//半開区間[a,b)
		return root->min(a, b, 0, root->size);
	}
};




int main() {
	int n, q;
	DynamicRMQ rmq;
	cin >> n >> q;
	for (int i = 0; i<n; i++) {
		int a;
		cin >> a;
		rmq.insert(i, a);
	}
	for (int i = 0; i<q; i++) {
		int x, y, z;
		cin >> x >> y >> z;
		if (x == 0) {
			int v = rmq.min(z, z + 1);
			rmq.erase(z);
			rmq.insert(y, v);
		}
		else if (x == 1) {
			cout << rmq.min(y, z + 1) << endl;
		}
		else {
			rmq.erase(y);
			rmq.insert(y, z);
		}
	}
	return 0;
}

