struct Splay {
	Splay *lch, *rch;
	int d, val;
	Splay(int _val = 0) : lch(0), rch(0), d(1), val(_val) {}
};
typedef pair<Splay*, Splay*> P;

Splay* update(Splay* x) {
	x->d = x->lch->d + x->rch->d;
	x->val = min(x->lch->val, x->rch->val);
	return x;
}

Splay* rotr(Splay* x) {
	Splay* y = x->lch;
	x->lch = y->rch;
	y->rch = x;
	update(x);
	return update(y);
}

Splay* rotl(Splay* x) {
	Splay* y = x->rch;
	x->rch = y->lch;
	y->lch = x;
	update(x);
	return update(y);
}

