struct Node
{
    Node *par, *lch, *rch;
    int val, mini, cnt;
    Node() {
        par = lch = rch = NULL;
        val = mini = 0;
        cnt = 1;
    }
};

typedef pair<Node*, Node*> PPNode;

int getcnt(Node *t) { return t ? t->cnt : 0; }
int getmin(Node *t) { return t ? t->mini : 1 << 29; }

Node* update(Node *t)
{
    t->cnt = getcnt(t->lch) + getcnt(t->rch) + 1;
    t->mini = min(min(getmin(t->lch), getmin(t->rch)), t->val);
    return t;
}

void rotate(Node *t)
{
    Node *p = t->par;
    if (p->lch == t) {
        p->lch = t->rch; t->rch = p;
        if (p->lch) p->lch->par = p;
    } else {
        p->rch = t->lch; t->lch = p;
        if (p->rch) p->rch->par = p;
    }
    t->par = p->par; p->par = t;
    if (t->par) (t->par->lch == p ? t->par->lch : t->par->rch) = t;
    update(p);
}

Node* splay(Node *t) 
{
    while (t->par) {
        Node *p = t->par, *g = p->par;
        if (g) rotate((p->lch == t) == (g->lch == p) ? p : t);
        rotate(t);
    }
    return update(t);
}

Node* find(Node *t, int k)
{
    int c = getcnt(t->lch);
    if (k == c)     return t;
    else if (k < c) return find(t->lch, k);
    else            return find(t->rch, k - c - 1);
}

Node* merge(Node *l, Node *r)
{
    if (!l || !r) return l ? l : r;
    r = splay(find(r, 0));
    l->par = r; r->lch = l;
    return update(r);
}

PPNode split(Node *t, int k)
{
    if (k == t->cnt) return PPNode(t, NULL);
    t = splay(find(t, k));
    Node *s = t->lch;
    if (s) s->par = t->lch = NULL;
    return PPNode(s, update(t));
}

