struct MinMonoid {
  using T = int;
  static T op(const T& lhs, const T& rhs) { return min(lhs, rhs); }
  static constexpr T e() { return numeric_limits<T>::max(); }
};

template<class Monoid> struct RandomizedBinarySearchTree {
  using M = Monoid;
  using T = typename M::T;
  struct Node;
  using Tree = Node*;

  struct Node {
    T a, val;
    Tree cl, cr;
    int n;
    Node(const T& a = M::e()) : a(a), val(a), cl(nullptr), cr(nullptr), n(1) {}
  };

  static Tree merge(Tree tl, Tree tr) {
    if (!tr) return tl;
    if (!tl) return tr;
    if (rng(0, tl->n + tr->n) < tl->n) {
      tl->cr = merge(tl->cr, tr);
      return update(tl);
    } else {
      tr->cl = merge(tl, tr->cl);
      return update(tr);
    }
  }

  static pair<Tree, Tree> split(Tree t, int i) {
    if (!t) return {nullptr, nullptr};
    int nl = t->cl ? t->cl->n : 0;
    if (i <= nl) {
      Tree resl;
      tie(resl, t->cl) = split(t->cl, i);
      return {resl, update(t)};
    } else {
      Tree resr;
      tie(t->cr, resr) = split(t->cr, i - nl - 1);
      return {update(t), resr};
    }
  }

  static Tree insert(Tree t, int i, const T& a) {
    Tree tl, tr;
    tie(tl, tr) = split(t, i);
    return merge(merge(tl, new Node(a)), tr);
  }

  static Tree erase(Tree t, int i) {
    Tree tl, tr;
    tie(tl, tr) = split(t, i);
    tr = split(tr, 1).second;
    return merge(tl, tr);
  }

private:
  template<class Int> static Int rng(Int a, Int b) {
    static mt19937 mt(chrono::steady_clock().now().time_since_epoch().count());
    assert(a < b);
    return uniform_int_distribution<Int>(a, b - 1)(mt);
  }

  static Tree update(Tree t) {
    t->n = (t->cl ? t->cl->n : 0) + 1 + (t->cr ? t->cr->n : 0);
    t->val = M::op(M::op(t->cl ? t->cl->val : M::e(), t->a), t->cr ? t->cr->val : M::e());
    return t;
  }
};

using RBST = RandomizedBinarySearchTree<MinMonoid>;

