// AOJ 1508 RMQ

#include <bits/stdc++.h>
using namespace std;

template<class T, class Updater, T init>
class RBST {
private:
	static mt19937 engine;
	static Updater func;

	struct node {
		typedef node * Ptr;

		T value, res;
		int size;
		Ptr left, right;

		node(const T &v):value(v), res(v), size(1), left(nullptr), right(nullptr) {}

		inline void update() {
			size = 1;
			res = value;

			if(left) {
				size += left->size;
				res = func(res, left->res);
			}

			if(right) {
				size += right->size;
				res = func(res, right->res);
			}
		}
	};

	typedef typename RBST<T, Updater, init>::node::Ptr Ptr;
	Ptr root;

	inline static int node_size(const Ptr x) {
		return x ? x->size : 0;
	}

	Ptr merge(Ptr x, Ptr y) {
		if(!x) return y;
		if(!y) return x;

		if(engine() % (x->size + y->size) < x->size) {
			x->right = merge(x->right, y);
			x->update();
			return x;
		}
		else {
			y->left = merge(x, y->left);
			y->update();
			return y;
		}
	}

	typedef pair<Ptr , Ptr> P;

	P split(Ptr x, const int num) {
		if(!x) return P(nullptr, nullptr);

		const int l_size = node_size(x->left);
		if(l_size < num) {
			const P tmp = split(x->right, num - l_size - 1);
			x->right = tmp.first;
			x->update();
			return P(x, tmp.second);
		}
		else {
			const P tmp = split(x->left, num);
			x->left = tmp.second;
			x->update();
			return P(tmp.first, x);
		}
	}

	Ptr insert(Ptr x, const int pos, const T &value) {
		Ptr new_node(new node(value));
		const P tmp = split(x, pos);
		return merge(merge(tmp.first, new_node), tmp.second);
	}

	Ptr erase(Ptr x, const int pos) {
		P tmp = split(x, pos);
		Ptr left = tmp.first;
		tmp = split(tmp.second, 1);
		delete tmp.first;
		return merge(left, tmp.second);
	}

	// [l, r)
	T query(const Ptr x, const int l, const int r) const {
		if(!x) return init;
		if(r <= 0 || x->size <= l) return init;
		if(l <= 0 && x->size <= r) return x->res;

		const int l_size = node_size(x->left);
		const T res = (l <= l_size && l_size < r ? x->value : init);
		const T vl = query(x->left, l, r);
		const T vr = query(x->right, l - l_size - 1, r - l_size - 1);
		return func(res, func(vl, vr));
	}

public:
	RBST():root(nullptr) {}
	inline void erase(const int pos) { root = erase(root, pos); }
	inline void insert(const int pos, const T &value) { root = insert(root, pos, value); }
	inline T query(const int l, const int r) const { return query(root, l, r); }
};

template<class T, class Updater, T init> mt19937 RBST<T, Updater, init>::engine((random_device())());
template<class T, class Updater, T init> Updater RBST<T, Updater, init>::func;

template<class T>struct min_ob{inline T operator()(const T&a, const T&b)const{return min<T>(a,b);}};
template<class T> using range_minimum_query = RBST<T, min_ob<T>, numeric_limits<T>::max()>;

int main() {
	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	enum { SHIFT, QUERY, UPDATE };

	int n, q;
	cin >> n >> q;

	range_minimum_query<int> rmq;
	for(int i = 0; i < n; ++i) {
		int a;
		cin >> a;
		rmq.insert(i, a);
	}

	while(q--) {
		int x, y, z;
		cin >> x >> y >> z;
		switch(x) {
		case SHIFT:
		{
			const auto value = rmq.query(z, z + 1);
			rmq.erase(z);
			rmq.insert(y, value);
			break;
		}
		case QUERY:
		{
			cout << rmq.query(y, z + 1) << '\n';
			break;
		}
		case UPDATE:
		{
			rmq.erase(y);
			rmq.insert(y, z);
			break;
		}
		default: assert(false);
		}
	}

	return EXIT_SUCCESS;
}

