#define INF (1<<30)


class DynamicRMQ{
	static const int nil=INF;
	static int func(int a,int b){
		return min(a,b);
	}

	struct Node{
		int height;
		Node *left,*right;
		int size;
		int val,sub;

		Node(int k,int v)
			:height(1),left(0),right(0),size(1),val(v),sub(v){}
		~Node(){
			if(left)delete left;
			if(right)delete right;
		}
		Node *rotate_right(){
			Node *s=left;
			left=s->right;
			s->right=this;
			return s;
		}
		Node *rotate_left(){
			Node *s=right;
			right=s->left;
			s->left=this;
			return s;
		}
		Node *insert(int k,int v){
			if(!this)return new Node(k,v);
			int si=left?left->size:0;
			if(k <= si){
				left = left->insert(k,v);
			}else {//key < k
				right = right->insert(k-si-1,v);
			}
			return balance();
		}

		Node *erase(int k){
			if(!this)return NULL;
			int si=left?left->size:0;
			if(k==si){
				Node *le=left,*ri=right;
				left=right=NULL;
				delete this;
				if(!le){
					return ri;
				}
				if(!ri){
					return le;
				}
				Node *t;
				le = le->erase_max(&t);
				t->left = le;
				t->right = ri;
				return t->balance();
			}
			if(k < si){
				left = left->erase(k);
			}else if(si < k){
				right = right->erase(k-si-1);
			}
			return balance();
		}
		int query(int a,int b,int l,int r)const{
			if(!this || r<a || b<l)return nil;
			if(a<=l && r<=b)return sub;
			int si=left?left->size:0;
			int res=a<=l+si&&l+si<b?val:nil;
			res = func(res,left->query(a,b,l,l+si));
			res = func(res,right->query(a,b,l+si+1,r));
			return res;
		}
		Node *balance(){
			int bf = (right?right->height:0)-(left?left->height:0);
			if(2==bf){
				Node *t=right;
				if((t->right?t->right->height:0) < (t->left?t->left->height:0)){
					right = t->rotate_right();
				}
				return rotate_left()->update();
			}else if(bf==-2){
				Node *t=left;
				if((t->right?t->right->height:0) > (t->left?t->left->height:0)){
					left = t->rotate_left();
				}
				return rotate_right()->update();
			}
			updates();
			return this;
		}
		Node *update(){
			if(left)left->updates();
			if(right)right->updates();
			updates();
			return this;
		}
		void updates(){
			update_height();
			update_size();
			update_value();
		}
		void update_height(){
			if(!this)return;
			if(right){
				if(left && right->height < left->height)height=left->height+1;
				else height=right->height+1;
			}else if(left)height=left->height+1;
			else height=1;
		}
		void update_size(){
			if(!this)return;
			size = 1 + (left?left->size:0) + (right?right->size:0);
		}
		void update_value(){
			if(!this)return;
			sub = val;
			if(left)sub=func(sub,left->sub);
			if(right)sub=func(sub,right->sub);
		}
		Node* erase_max(Node **maxnode){
			if(right){
				right = right->erase_max(maxnode);
				return balance();
			}else{
				*maxnode=this;
				return left;
			}
		}
	} *root;
public:
	DynamicRMQ():root(0){}
	~DynamicRMQ(){if(root)delete root;}
	void insert(int k,int v){
		root=root->insert(k,v);
	}
	void erase(int k){
		root=root->erase(k);
	}
	int query(int a,int b)const{//半開区間[a,b)
		return root->query(a,b,0,root->size);
	}
};


int main(){
	int n,q;
	DynamicRMQ rmq;
	cin>>n>>q;
	for(int i=0;i<n;i++){
		int a;
		cin>>a;
		rmq.insert(i,a);
	}
	for(int i=0;i<q;i++){
		int x,y,z;
		cin>>x>>y>>z;
		if(x==0){
			int v=rmq.query(z,z+1);
			rmq.erase(z);
			rmq.insert(y,v);
		}else if(x==1){
			cout<<rmq.query(y,z+1)<<endl;
		}else{
			rmq.erase(y);
			rmq.insert(y,z);
		}
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

using T = int;
const T id = INT_MAX;
T op(T l, T r) {
	return min(l, r);
}

enum COL { BLACK, RED };

struct node;
node *update(node *t);
struct node {
	T val, all;
	node *ch[2];
	COL color;
	int level;
	int size;
	node() {}
	void init(T v) {
		val = v;
		all = v;
		color = BLACK;
		level = 0;
		size = 1;
		ch[0] = ch[1] = nullptr;
	}
	void init(node *l, node *r) {
		val = id;
		color = RED;
		ch[0] = l;
		ch[1] = r;
		update(this);
	}
};

const int pmax = 1e6;
node pool[pmax];
queue<int> deleted;
int it = 0;

int count(node *t) { return !t ? 0 : t->size; }

T que(node *t) { return !t ? id : t->all; }

node *update(node *t) {
	t->size = count(t->ch[0]) + count(t->ch[1]) + (!t->ch[0] || !t->ch[1]);
	t->all = op(que(t->ch[0]), op(t->val, que(t->ch[1])));
	t->level = (t->ch[0] ? t->ch[0]->level + (t->ch[0]->color == BLACK) : 0);
	return t;
}

node *new_leaf(T v) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(v);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(v);
	return pool + it++;
}

node *new_node(node *l, node *r) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(l, r);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(l, r);
	return pool + it++;
}

void delete_node(node* t) {
	deleted.push(t - pool);
}

node *rotate(node *t, int b) {
	node *s = t->ch[1 - b];
	t->ch[1 - b] = s->ch[b];
	s->ch[b] = t;
	update(t);
	return update(s);
}

node *submerge(node *l, node *r) {
	if (l->level < r->level) {
		node *c = submerge(l, r->ch[0]);
		r->ch[0] = c;
		if (r->color == BLACK && c->color == RED && c->ch[0] && c->ch[0]->color == RED) {
			if (r->ch[1]->color == BLACK) {
				r->color = RED;
				c->color = BLACK;
				return rotate(r, 1);
			}
			c->color = BLACK;
			r->ch[1]->color = BLACK;
			r->color = RED;
		}
		return update(r);
	}
	if (l->level > r->level) {
		node *c = submerge(l->ch[1], r);
		l->ch[1] = c;
		if (l->color == BLACK && c->color == RED && c->ch[1] && c->ch[1]->color == RED) {
			if (l->ch[0]->color == BLACK) {
				l->color = RED;
				c->color = BLACK;
				return rotate(l, 0);
			}
			l->ch[0]->color = BLACK;
			c->color = BLACK;
			l->color = RED;
		}
		return update(l);
	}
	return new_node(l, r);
}

node *merge(node *l, node *r) {
	if (!l) return r;
	if (!r) return l;
	node *c = submerge(l, r);
	c->color = BLACK;
	return c;
}

pair<node*, node*> split(node *t, int k) {
	if (!t) return make_pair(nullptr, nullptr);
	if (k == 0) return make_pair(nullptr, t);
	if (k >= count(t)) return make_pair(t, nullptr);
	int c = count(t->ch[0]);
	node *l = t->ch[0], *r = t->ch[1];
	delete_node(t);
	if (k < c) {
		pair<node*, node*> p = split(l, k);
		return make_pair(p.first, merge(p.second, r));
	}
	if (k > c) {
		pair<node*, node*> p = split(r, k - c);
		return make_pair(merge(l, p.first), p.second);
	}
	return make_pair(l, r);
}

node *insert(node *t, int k, T v) {
	pair<node*, node*> s = split(t, k);
	return merge(merge(s.first, new_leaf(v)), s.second);
}

node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	return merge(s1.first, s2.second);
}

T find(node *t, int l, int r) {
	if (!t) return id;
	if (r < 0 || l >= count(t)) return id;
	if (l <= 0 && r >= t->size) return t->all;
	int c = count(t->ch[0]), d = c + (!t->ch[0] || !t->ch[1]);
	return op(!t->ch[0] ? id : find(t->ch[0], l, r), op(l <= c && c < r ? t->val : id, !t->ch[1] ? id : find(t->ch[1], l - d, r - d)));
}

node *find(node *t, int k) {
	if (!t) return t;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	return c == 0 && b ? t : k < c ? find(t->ch[0], k) : find(t->ch[1], k - c - b);
}

void update(node *t, int k, T val) {
	if (!t) return;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	if (c == 0 && b) {
		t->val = val;
	}
	else if (k < c) {
		update(t->ch[0], k, val);
	}
	else {
		update(t->ch[1], k - c - b, val);
	}
	update(t);
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q;
	cin >> n >> q;
	node* root = nullptr;
	for (int i = 0; i < n; i++) {
		int a;
		cin >> a;
		root = insert(root, i, a);
	}
	while (q--) {
		int x, y, z;
		cin >> x >> y >> z;
		if (x == 0) {
			int val = find(root, z)->val;
			root = erase(root, z);
			root = insert(root, y, val);
		}
		else if (x == 1) {
			printf("%d\n", find(root, y, z + 1));
		}
		else {
			update(root, y, z);
		}
	}
	return 0;
}

