        if (t == NULL)return;
        dump(t->lch);
        cout << t->val << " ";
        dump(t->rch);
    }
    void push_back(Node *t) {
        root = merge(root, t);
    }

    void shift(int l, int r) { // [l,r]?????????????????????????????????(????????????????§????)
        Node *a, *b, *c;
        tie(a, b, c) = split3(l, r);

        Node *ba, *bb;
        tie(ba, bb) = split(b, r - l);

        root = merge(root, a, bb, ba, c);
    }

    int query(int l, int r) {
        Node *a, *b, *c;
        tie(a, b, c) = split3(l, r);

        int res = b->mi;

        root = merge(root, a, b, c);

        return res;
    }
};
