struct Splay {
	Splay *lch, *rch;
	int d, val;
	Splay(int _val = 0) : lch(0), rch(0), d(1), val(_val) {}
};
typedef pair<Splay*, Splay*> P;

Splay* update(Splay* x) {
	x->d = x->lch->d + x->rch->d;
	x->val = min(x->lch->val, x->rch->val);
	return x;
}

/*
void propagate(Splay* x) {
	x->lch->dval += x->dval;
	x->rch->dval += x->dval;
	x->dval = 0;
}
*/

Splay* splay(Splay* x, int m) {
	if (m == 0 || m == x->d) return x;
	// propagate(x);
	int dl = x->lch->d;
	if (m < dl) {
		Splay* y = splay(x->lch, m);
		x->lch = y->rch;
		y->rch = x;
		update(x);
		return update(y);
	}
	else if (m > dl) {
		Splay* y = splay(x->rch, m - dl);
		x->rch = y->lch;
		y->lch = x;
		update(x);
		return update(y);
	}
	else return x;
}

Splay* merge(Splay* x, Splay* y) {
	if (!x) return y;
	if (!y) return x;
	Splay* z = new Splay();
	z->lch = x;
	z->rch = y;
	return update(z);
}

Splay* merges(vector<Splay*> xs) {
    Splay* x = NULL;
    for (Splay* y: xs) x = merge(x, y);
    return x;
}

P split(Splay* x, int m) {
	if (m == 0) return P(NULL, x);
	if (m == x->d) return P(x, NULL);
	x = splay(x, m);
	P p(x->lch, x->rch);
	delete x;
	return p;
}

vector<Splay*> splits(Splay* x, vector<int> is) {
    reverse(is.begin(), is.end());
    vector<Splay*> xs;
    for (int i: is) {
        P p = split(x, i);
        x = p.first;
        xs.pb(p.second);
    }
    xs.pb(x);
    reverse(xs.begin(), xs.end());
    return xs;
}

int get_val(Splay*& x, int i) {
	P p = split(x, i);
	cout << p.second->d << endl;
	P q = split(p.second, 1);
	cout << q.first << endl;
	int val = q.first->val;
	x = merge(p.first, merge(q.first, q.second));
	return val;
}

