#include <bits/stdc++.h>

using key_type = int;

enum { L, R };
struct avl_node {
    key_type key;
    std::array<avl_node*, 2> ch;
    int size;
    int height;
    int min;

    static avl_node* const nil;

    avl_node() : avl_node(-1) { }
    avl_node(key_type key) : avl_node(key, nil, nil, 1, 1, key) { }
    avl_node(const key_type key, avl_node *left, avl_node *right, int size, int height, key_type min)
        : key(key), ch({{left, right}}), size(size), height(height), min(min) { }

    void *operator new(size_t) {
        static int p = 0;
        static avl_node pool[400010];
        return pool + p++;
    }
};

avl_node *const avl_node::nil = new avl_node(key_type(), nullptr, nullptr, 0, 0, 1e9);
avl_node *const nil = avl_node::nil;
namespace trush { auto ___ = []() { return nil->ch = {{nil, nil}}; }; };

using np = avl_node*;
using cnp = const avl_node*;

// ok
np update(np n) {
    n->size = n->ch[L]->size + 1 + n->ch[R]->size;
    n->height = std::max(n->ch[L]->height, n->ch[R]->height) + 1;
    n->min = std::min({n->ch[L]->min, n->key, n->ch[R]->min});
    return n;
}

// ok
template <int dir>
np rotate(np n) {
    assert(n->ch[!dir] != nil);
    np root = n->ch[!dir];
    n->ch[!dir] = root->ch[dir];
    root->ch[dir] = n;
    update(n);
    update(root);
    return root;
}

// ok
int bfactor(np n) {
    assert(n != nil);
    return n->ch[R]->height - n->ch[L]->height;
}

// ok
np balance(np n) {
    assert(abs(bfactor(n)) <= 2);
    if (bfactor(n) == +2) {
        if (bfactor(n->ch[R]) < 0) n->ch[R] = rotate<R>(n->ch[R]);
        return rotate<L>(n);
    } else if (bfactor(n) == -2) {
        if (bfactor(n->ch[L]) > 0) n->ch[L] = rotate<L>(n->ch[L]);
        return rotate<R>(n);
    } else {
        return n;
    }
}

// ok
np insert_at(np n, int k, key_type x) {
    assert(0 <= k && k <= n->size);
    if (n == nil) return new avl_node(x);
    int sl = n->ch[L]->size;
    if (k <= sl) n->ch[L] = insert_at(n->ch[L], k, x);
    else n->ch[R] = insert_at(n->ch[R], k - sl - 1, x);
    return balance(update(n));
}

// ok
template <int dir>
std::pair<np, np> remove_most(np n) {
    assert(n != nil);
    if (n->ch[dir] != nil) {
        np most;
        std::tie(n->ch[dir], most) = remove_most<dir>(n->ch[dir]);
        return {balance(update(n)), most};
    } else {
        np res = n->ch[!dir];
        n->ch[!dir] = nil;
        return {res, update(n)};
    }
}

// ok
std::pair<np, key_type> remove_at(np n, int k) {
    assert(n != nil);
    int sl = n->ch[L]->size;
    if (k < sl) {
        key_type most;
        std::tie(n->ch[L], most) = remove_at(n->ch[L], k);
        return {balance(update(n)), most};
    } if (k == sl) {
        if (n->ch[R] == nil) {
            return {n->ch[L], n->key};
        } else {
            np most;
            std::tie(n->ch[R], most) = remove_most<L>(n->ch[R]);
            most->ch = n->ch;
            // delete n;
            return {balance(update(most)), n->key};
        }
    } else {
        key_type most;
        std::tie(n->ch[R], most) = remove_at(n->ch[R], k - sl - 1);
        return {balance(update(n)), most};
    }
}

// ok
template <typename Iterator>
np build(Iterator left, Iterator right) {
    int n = right - left;
    Iterator mid = left + n / 2;
    if (n == 0) return nil;
    np l = build(left, mid);
    np r = build(mid + 1, right);
    np m = new avl_node(*mid);
    m->ch = {{l, r}};
    return update(m);
}

void update_at(np n, int k, key_type x) {
    assert(0 <= k && k < n->size);
    int sl = n->ch[L]->size;
    if (k < sl) update_at(n->ch[L], k, x);
    else if (k == sl) n->key = x;
    else update_at(n->ch[R], k - sl - 1, x);
    update(n);
}

key_type range_min(np n, int l, int r) {
    assert(n != nil);
    assert(0 <= l && l <= r);
    assert(l <= r && r <= n->size);
    if (l == 0 && r == n->size) return n->min;
    int sl = n->ch[L]->size;
    key_type res = 1e9;
    if (l < sl) res = std::min(res, range_min(n->ch[L], l, std::min(r, sl)));
    if (l <= sl && sl < r) res = std::min(res, n->key);
    if (sl + 1 < r) res = std::min(res, range_min(n->ch[R], std::max(0, l - sl - 1), r - sl - 1));
    return res;
}

using namespace std;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    np root = build(a.begin(), a.end());
    for (int i = 0; i < q; ++i) {
        int t, x, y;
        cin >> t >> x >> y;
        if (t == 0) {
            int t;
            tie(root, t) = remove_at(root, y);
            root = insert_at(root, x, t);
        } else if (t == 1) {
            ++y;
            cout << range_min(root, x, y) << '\n';
        } else {
            update_at(root, x, y);
        }
    }
}

#include <bits/stdc++.h>
#define int long long
#define INF 1e+18
using namespace std;

unsigned int randxor(){
	static unsigned int x = 1239732;
	x ^= (x << 13);
	x ^= (x >> 7);
	x ^= (x << 17);
	return x;
}

struct node{
	int dat,val,size;
	node *lch,*rch;
	node(int v){
		dat = v;
		val = v;
		lch = 0;
		rch = 0;
		size = 1;
	}
};

int siz(node *t){
	if(!t) return 0;
	return t->size;
}

int dat(node *t){
	if(!t) return INF;
	return t->dat;
}

node* update(node *t){
	t->size = siz(t->lch) + siz(t->rch) + 1;
	t->dat = min(t->val,min(dat(t->lch),dat(t->rch)));
	return t;
}

node* merge(node *x,node *y){
	if(!x) return y;
	if(!y) return x;
	if(randxor() % (x->size + y->size) < x->size){
		x->rch = merge(x->rch,y);
		return update(x);
	}else{
		y->lch = merge(x,y->lch);
		return update(y);
	}
}

typedef pair<node*,node*> P;

P split(node *x,int k){
	if(!x) return P(0,0);
	if(k <= siz(x->lch)){
		P tmp = split(x->lch,k);
		x->lch = tmp.second;
		return P(tmp.first,update(x));
	}else{
		P tmp = split(x->rch,k - siz(x->lch) - 1);
		x->rch = tmp.first;
		return P(update(x),tmp.second);
	}
}

void insert(node **x,int k,node *v){
	P tmp = split(*x,k);
	*x = merge(tmp.first,merge(v,tmp.second));
}

node* erase(node **x,int k){
	P p1 = split(*x,k),p2 = split(p1.second,1);
	*x = merge(p1.first,p2.second);
	return p2.first;
}

void update(node **x,int k,int v){
	P p1 = split(*x,k),p2 = split(p1.second,1);
	p2.first->val = v;
	update(p2.first);
	*x = merge(p1.first,merge(p2.first,p2.second));
}

int get(node **x,int l,int r){
	P p1 = split(*x,l),p2 = split(p1.second,r - l);
	int ret = p2.first->dat;
	*x = merge(p1.first,merge(p2.first,p2.second));
	return ret;
}

signed main(){
	int n,q;
	node *tree = 0;
	cin >> n >> q;
	for(int i = 0;i < n;i++){
		int a;
		cin >> a;
		tree = merge(tree,new node(a));
	}
	for(int i = 0;i < q;i++){
		int x,l,r;
		cin >> x >> l >> r;
		if(!x) insert(&tree,l,erase(&tree,r));
		else if(x == 1) cout << get(&tree,l,r + 1) << endl;
		else update(&tree,l,r);
	}
	return 0;
}

