using namespace std;


#define INF (1<<30)

class Sequence{//AVLTree
	struct Node{
		int height;
		Node *left,*right;
		int size;
		int index,added;
		int val,minsub;

		Node(int k,int v)
			:height(1),index(k),added(0),left(0),right(0),size(1),val(v),minsub(v){}
		~Node(){
			if(left)delete left;
			if(right)delete right;
		}
		Node *rotate_right(){
			Node *s=left;
			int b=s->added,d=added;
			s->added += d;
			if(s->right)s->right->added += b;
			added += -b-d;
			left=s->right;
			s->right=this;
			return s;
		}
		Node *rotate_left(){
			Node *s=right;
			int b=s->added,d=added;
			s->added += d;
			if(s->left)s->left->added += b;
			added += -b-d;
			right=s->left;
			s->left=this;
			return s;
		}
		Node *insert(int k,int v){
			if(!this)return new Node(k,v);
			k-=added;
			if(k < index){
				left = left->insert(k,v);
			}else {//key < k
				right = right->insert(k,v);
			}
			return balance();
		}
		bool find(int k){
			if(!this)return false;
			k-=added;
			return k==index?
				true:k<index?left->find(k):right->find(k);
		}
		Node *erase(int k){
			if(!this)return NULL;
			k-=added;
			if(k==index){
				int a=added;
				Node *le=left,*ri=right;
				left=right=NULL;
				delete this;
				if(!le){
					if(ri)ri->added+=a;
					return ri;
				}
				if(!ri){
					if(le)le->added+=a;
					return le;
				}
				Node *t;
				le = le->erase_max(&t,a,a);
				t->left = le;
				t->right = ri;
				return t->balance();
			}
			if(k < index){
				left = left->erase(k);
			}else if(index < k){
				right = right->erase(k);
			}
			return balance();
		}
		int min(int a,int b,int l,int r,int s)const{
			if(!this || r<a || b<l)return INF;
			if(a<=l && r<=b)return minsub;
			s += added;
			int i=index+s;
			int res=a<=i&&i<=b?val:INF;
			res = std::min(res,left->min(a,b,l,i-1,s));
			res = std::min(res,right->min(a,b,i+1,r,s));
			return res;
		}
		void substitute(int k,int v){
			k -= added;
			if(k==index){
				val=v;
			}
			if(k < index){
				left->substitute(k,v);
			}else if(index < k){
				right->substitute(k,v);
			}
			updates();
		}


		void add_ge(int k,int v){
			if(!this)return;
			k-=added;
			if(k <= index){
				added += v;
				if(left){
					left->added -= v;
					left->add_ge(k-v ,v);
				}
			}else{
				right->add_ge(k,v);
			}
		}
		Node *balance(){
			int bf = (right?right->height:0)-(left?left->height:0);
			if(2==bf){
				Node *t=right;
				if((t->right?t->right->height:0) < (t->left?t->left->height:0)){
					right = t->rotate_right();
				}
				return rotate_left()->update();
			}else if(bf==-2){
				Node *t=left;
				if((t->right?t->right->height:0) > (t->left?t->left->height:0)){
					left = t->rotate_left();
				}
				return rotate_right()->update();
			}
			updates();
			return this;
		}
		Node *update(){
			if(left)left->updates();
			if(right)right->updates();
			updates();
			return this;
		}
		void updates(){
			update_height();
			update_size();
			update_min();
		}
		void update_height(){
			if(!this)return;
			if(right){
				if(left && right->height < left->height)height=left->height+1;
				else height=right->height+1;
			}else if(left)height=left->height+1;
			else height=1;
		}
		void update_size(){
			if(!this)return;
			size = 1 + (left?left->size:0) + (right?right->size:0);
		}
		void update_min(){
			if(!this)return;
			minsub = val;
			if(left)minsub=std::min(minsub,left->minsub);
			if(right)minsub=std::min(minsub,right->minsub);
		}
		Node* erase_max(Node **maxnode,int add,int s){
			s += added;
			if(right){
				right = right->erase_max(maxnode,add,s);
				return balance();
			}else{
				*maxnode=this;
				if(left)left->added += added;
				index = index+s-add;
				added = add;
				return left;
			}
		}
	} *root;
public:
	Sequence():root(0){}
	~Sequence(){if(root)delete root;}
	void insert(int k,int v){
		root->add_ge(k,1);
		root=root->insert(k,v);
	}
	void erase(int k){
		root=root->erase(k);	
		root->add_ge(k,-1);
	}
	int min(int a,int b)const{
		return root->min(a,b,0,root->size-1,0);
	}
	void substitute(int k,int v){
		root->substitute(k,v);
	}
};


int main(){
	int n,q;
	Sequence seq;
	cin>>n>>q;
	for(int i=0;i<n;i++){
		int a;
		cin>>a;
		seq.insert(i,a);
	}
	for(int i=0;i<q;i++){
		int x,y,z;
		cin>>x>>y>>z;
		if(x==0){
			int v=seq.min(z,z);
			seq.erase(z);
			seq.insert(y,v);
		}else if(x==1){
			cout<<seq.min(y,z)<<endl;
		}else{
			seq.substitute(y,z);
		}
	}
	return 0;
}

#include <bits/stdc++.h>
template <typename T>
constexpr T INF = numeric_limits<T>::max() / 10;

template <typename Monoid>
struct AccRandomizedBinarySearchTree {
public:
    static constexpr int POOL_SIZE = 200000;

private:
    struct Node {
        using BaseMonoid = Monoid;
        using T = typename BaseMonoid::T;
        using Ptr = Node*;
        using PtrPair = pair<Ptr, Ptr>;
        Node() : left{}, right{}, value{}, accum{}, size{1} {}
        Node(const T& value) : left{}, right{}, value{value}, accum{value}, size{1} {}
        Ptr left, right;
        T value;
        T accum;
        int size;

        static void serialize(Ptr a, vector<T>& v)
        {
            if (a == nullptr) {
                return;
            } else {
                serialize(a->left, v);
                v.push_back(a->value);
                serialize(a->right, v);
            }
        }
        static unsigned xor128()
        {
            static unsigned x = 123456789;
            static unsigned y = 362436069;
            static unsigned z = 521288629;
            static unsigned w = 88675123;
            const unsigned t = x ^ (x << 11);
            x = y;
            y = z;
            z = w;
            return w = (w ^ (w << 19)) ^ (t ^ (t >> 8));
        }

        static unsigned getRand(const int maximum)
        {
            return xor128() % maximum;
        }

        static T acc(const T& a, const T& b)
        {
            static const BaseMonoid ACC{};
            return ACC(a, b);
        }

        static int getSize(const Ptr a)
        {
            return (a == nullptr) ? 0 : a->size;
        }
        static T getAcc(const Ptr a)
        {
            return (a == nullptr) ? BaseMonoid::identity() : a->accum;
        }

        static Ptr update(Ptr a)
        {
            a->size = getSize(a->left) + getSize(a->right) + 1;
            a->accum = acc(acc(getAcc(a->left), getAcc(a->right)), a->value);
            return a;
        }

        static Ptr merge(Ptr a, Ptr b)
        {
            if (a == nullptr) {
                return b;
            } else if (b == nullptr) {
                return a;
            }
            const int asize = getSize(a);
            const int bsize = getSize(b);
            if (getRand(asize + bsize) < asize) {
                a->right = merge(a->right, b);
                return update(a);
            } else {
                b->left = merge(a, b->left);
                return update(b);
            }
        }

        static PtrPair split(Ptr a, const int k)  // size = (k,n-k)
        {
            if (a == nullptr) {
                return make_pair(Ptr{}, Ptr{});
            }
            if (k <= getSize(a->left)) {
                const PtrPair s = split(a->left, k);
                a->left = s.second;
                return make_pair(s.first, update(a));
            } else {
                const PtrPair s = split(a->right, k - getSize(a->left) - 1);
                a->right = s.first;
                return make_pair(update(a), s.second);
            }
        }
        static Ptr insert(Ptr a, const int k, Ptr b)
        {
            const PtrPair s = split(a, k);
            return merge(merge(s.first, b), s.second);
        }

        static PtrPair erase(Ptr a, const int k)
        {
            const PtrPair sr = split(a, k + 1);
            const PtrPair sl = split(sr.first, k);
            return make_pair(merge(sl.first, sr.second), sl.second);
        }
    };

    using Ptr = typename Node::Ptr;
    using PtrPair = typename Node::PtrPair;

    int head = 0;
    static Node pool[POOL_SIZE];
    Ptr alloc(const typename Node::T& x)
    {
        assert(head < POOL_SIZE);
        pool[head].value = x;
        pool[head].size = 1;
        pool[head].left = nullptr;
        pool[head].right = nullptr;
        pool[head].accum = x;
        head++;
        return pool + head - 1;
    }
    void garbage_collect()
    {
        vector<T> v;
        Node::serialize(root, v);
        head = 0;
        root = nullptr;
        rev_root = nullptr;
        for (int i = 0; i < v.size(); i++) {
            root = Node::insert(root, i, alloc(v[i]));
            rev_root = Node::insert(rev_root, v.size() - i - 1, alloc(v[i]));
        }
    }

    Ptr root;
    Ptr rev_root;

public:
    using BaseMonoid = Monoid;
    using T = typename Node::T;
    AccRandomizedBinarySearchTree() : root{}, rev_root{} {}

    int getSize() const
    {
        return Node::getSize(root);
    }
    void insert(const int k, const T& value)
    {
        const int s = Node::getSize(root);
        assert(0 <= k);
        assert(k <= s);
        if (head == POOL_SIZE) {
            garbage_collect();
        }
        root = Node::insert(root, k, alloc(value));
        rev_root = Node::insert(rev_root, s - k, alloc(value));
    }
    void erase(const int k)
    {
        const int s = Node::getSize(root);
        assert(0 <= k);
        assert(k < s);
        Ptr p;
        tie(root, p) = Node::erase(root, k);
        if (p != nullptr) {
            p->left = Ptr{};
            p->right = Ptr{};
        }
        tie(rev_root, p) = Node::erase(rev_root, s - k - 1);
        if (p != nullptr) {
            p->left = Ptr{};
            p->right = Ptr{};
        }
    }
    T get(int k) const
    {
        assert(0 <= k);
        assert(k < Node::getSize(root));
        Ptr v = root;
        while (v != nullptr) {
            const int s = Node::getSize(v->left);
            if (s > k) {
                v = v->left;
            } else if (s == k) {
                return v->value;
            } else {
                v = v->right;
                k -= s + 1;
            }
        }
        return v->value;
    }

    void set(const int k, const T& value)
    {
        const int s = Node::getSize(root);
        assert(0 <= k);
        assert(k < s);
        const PtrPair sr = Node::split(root, k + 1);
        const PtrPair sl = Node::split(sr.first, k);
        const Ptr lr = sl.second;
        lr->value = value;
        root = Node::merge(Node::merge(sl.first, lr), sr.second);

        const PtrPair rev_sr = Node::split(rev_root, s - k);
        const PtrPair rev_sl = Node::split(rev_sr.first, s - k - 1);
        const Ptr rev_lr = rev_sl.second;
        rev_lr->value = value;
        rev_root = Node::merge(Node::merge(rev_sl.first, rev_lr), rev_sr.second);
    }

    T accumulate(const int l, const int r)  // [l,r)
    {
        assert(0 <= l);
        assert(l < r);
        assert(r <= Node::getSize(root));
        const PtrPair sr = Node::split(root, r);
        const PtrPair sl = Node::split(sr.first, l);
        const T ans = Node::getAcc(sl.second);
        root = Node::merge(Node::merge(sl.first, sl.second), sr.second);
        return ans;
    }
    void reverse(const int l, const int r)  // [l,r)
    {
        const int s = Node::getSize(root);
        assert(0 <= l);
        assert(l < r);
        assert(r <= s);
        const int width = r - l;
        if (width > 1) {
            const PtrPair sr = Node::split(root, r);
            const PtrPair sl = Node::split(sr.first, l);

            const PtrPair rev_sr = Node::split(rev_root, s - l);
            const PtrPair rev_sl = Node::split(rev_sr.first, s - r);

            root = Node::merge(Node::merge(sl.first, rev_sl.second), sr.second);
            rev_root = Node::merge(Node::merge(rev_sl.first, sl.second), rev_sr.second);
        }
    }

    void shiftRight(const int l, const int r, const int count)  // [l,r)
    {
        const int s = Node::getSize(root);
        assert(0 <= l);
        assert(l < r);
        assert(r <= s);
        const int width = r - l;
        const int shift = count % width;

        if (shift > 0) {
            const PtrPair sr = Node::split(root, r);
            PtrPair sl = Node::split(sr.first, l);
            const PtrPair sm = Node::split(sl.second, width - shift);

            const PtrPair rev_sr = Node::split(rev_root, s - l);
            PtrPair rev_sl = Node::split(rev_sr.first, s - r);
            const PtrPair rev_sm = Node::split(rev_sl.second, shift);

            root = Node::merge(Node::merge(sl.first, sm.second), Node::merge(sm.first, sr.second));
            rev_root = Node::merge(Node::merge(rev_sl.first, rev_sm.second), Node::merge(rev_sm.first, rev_sr.second));
        }
    }

    void shiftLeft(const int l, const int r, const int count)  // [l,r)
    {
        assert(0 <= l);
        assert(l < r);
        assert(r <= Node::getSize(root));
        const int width = r - l;
        const int shift = count % width;
        if (shift > 0) {
            shiftRight(l, r, width - shift);
        }
    }
};
template <typename T>
typename AccRandomizedBinarySearchTree<T>::Node AccRandomizedBinarySearchTree<T>::pool[AccRandomizedBinarySearchTree::POOL_SIZE];

