#define INF 100000000000000

template <typename T>
struct segment {
  segment(std::size_t m) : m(m) {
    n = 1;
    while (n < m) n *= 2;
    data.resize(2 * n);
    for (std::size_t i = 0; i < 2 * n - 1; ++i) {
      data[i] = static_cast<T>(INF);
    }
  }

  void update(std::size_t idx, const T& value) {
    idx += n - 1;  // leaf
    data[idx] = value;
    while (idx > 0) {
      idx = (idx - 1) / 2;  // parent

      // RMQ
      data[idx] = std::min(data[idx * 2 + 1], data[idx * 2 + 2]);
    }
  }

  // [first, last)
  T query(std::size_t first, std::size_t last) {
    return query(first, last, 0, 0, n);
  }

  T query(std::size_t first, std::size_t last,
          std::size_t node, std::size_t l, std::size_t r) {
    if (r <= first || last <= l) return static_cast<T>(INF);
    if (first <= l && r <= last) return data[node];
    std::size_t m = (l + r) / 2;

    // RMQ
    return std::min(query(first, last, 2 * node + 1, l, m),
                    query(first, last, 2 * node + 2, m, r));
  }

  std::size_t size() const {
    return m;
  }

  T get(std::size_t idx) {
    idx += n - 1;
    return data[idx];
  }

  std::vector<T> data;
  std::size_t m;
  std::size_t n;
};

int N, Q;

int main() {
  cin >> N >> Q;
  segment<unsigned long long> segtree(N);

  for (int i = 0; i < N; ++i) {
    int tmp;
    cin >> tmp;
    segtree.update(i, tmp);
  }

  for (int i = 0; i < Q; ++i) {
    int x, y, z;
    cin >> x >> y >> z;

    if (x == 0) {
      int last = segtree.get(z);
      for (int j = z; j > y; --j) {
        segtree.update(j, segtree.get(j - 1));
      }
      segtree.update(y, last);
    } else if (x == 1) {
      cout << segtree.query(y, z + 1) << endl;
    } else {
      segtree.update(y, z);
    }
  }
}

