    Node(int v, int p) : val(v), pri(p), cnt(1), sum(v), min(v) {
        ch[0] = ch[1] = np;
    }
    // ~Node(){
    //     if(ch[0]) delete ch[0];
    //     if(ch[1]) delete ch[1];
    // }
    void * operator new(size_t sz){
        static int pos = 0;
        static char mem[400020*sizeof(Node)];
        Node * res = (Node*)(mem+pos);
        pos += sizeof(Node);
        return res;
    }
};


int count(Node * t){
    return t == np ? 0 : t->cnt;
}
int sum(Node * t){
    return t == np ? 0 : t->sum;
}
int min(Node * t){
    return t == np ? inf : t->min;
}

void show(Node * n, int ofs=0){
    if(!n) return;
    show(n->ch[0],ofs+1);
    rep(i,ofs*2) putchar(' ');
    printf("v:%d m:%d (%p)\n",n->val,n->min,n);
