#include <random>
#include <utility>
using namespace std;
template<typename T> class RBST {
public:
	struct node {
		T value;
		T min_val;
		int cnt;
		node *left,*right;
		node(T v):value(v),min_val(v),cnt(1) {
			left=right=NULL;
		}
	};
	random_device rnd;
	mt19937 mt;
	node *root;
	RBST():root(NULL) {mt.seed(rnd());}
	int count(node *t) {return !t?0:t->cnt;}
	node *update(node *t) {
		if(!t) return NULL;
		t->cnt=count(t->left)+count(t->right)+1;
		t->min_val=t->value;
		if(t->left) t->min_val=min(t->min_val,t->left->min_val);
		if(t->right) t->min_val=min(t->min_val,t->right->min_val);
		return t;
	}
	node *merge(node *l,node *r) {
		if(!l||!r) return !l?r:l;
		uniform_real_distribution<> x(0,l->cnt+r->cnt);
		if(x(mt)<l->cnt) {
			l->right=merge(l->right,r);
			return update(l);
		}else {
			r->left=merge(l,r->left);
			return update(r);
		}
	}
	pair<node*,node*> split(node *t,int k) {
		if(!t) return pair<node*,node*>(NULL,NULL);
		if(k<=count(t->left)) {
			pair<node*,node*> s=split(t->left,k);
			t->left=s.second;
			return make_pair(s.first,update(t));
		}else {
			pair<node*,node*> s=split(t->right,k-count(t->left)-1);
			t->right=s.first;
			return make_pair(update(t),s.second);
		}
	}
	node *insert(node *t,int k,T v) {
		pair<node*,node*> s=split(t,k);
		node *u=new node(v);
		t=merge(s.first,u);
		t=merge(t,s.second);
		return update(t);
	}
	void insert(int k,T v) {
		root=insert(root,k,v);
	}
	int lower_bound(node *t,T v) {
		if(!t) return 0;
		int c=count(t->left);
		if(t->value>v) {
			return lower_bound(t->left,v);
		}else if(t->value==v) {
			return c;
		}else {
			return c+1+lower_bound(t->right,v);
		}
	}
	int lower_bound(T v) {
		return lower_bound(root,v);
	}
	T get(node *t,int k) {
		int c=count(t->left);
		if(c==k) {
			return t->value;
		}else if(c>k) {
			return get(t->left,k);
		}else {
			return get(t->right,k-c-1);
		}
	}
	T get(int k) {
		return get(root,k);
	}
	node *erase(node *t,int k) {
		pair<node*,node*> u,v;
		u=split(t,k+1);
		v=split(u.first,k);
		t=merge(v.first,u.second);
		return update(t);
	}
	void erase(int k) {
		root=erase(root,k);
	}
};
