struct RBST{
	int count;
	int value;
	int minimum;
	RBST *l, *r;
	RBST(int value = 0):count(1), value(value), minimum(value), l(NULL), r(NULL){}
	static int size(RBST *a){
		return a ? a->count : 0;
	}
	static int get_min(RBST *a){
		return a ? a->minimum : INF;
	}
	RBST *update(){
		count = 1 + size(l) + size(r);
		minimum = min({get_min(l), get_min(r), value});
		return this;
	}
	// aとbを連結する(破壊的)
	static RBST *merge(RBST *a, RBST *b){
		if(!a || !b) return a?a:b;
		if( (int)(mt() % (size(a) + size(b))) < size(a)){ // aの方が優先度が高い
			a->r = merge(a->r, b);
			return a->update();
		}else{
			b->l = merge(a, b->l);
			return b->update();
		}
	}

	// [0,k)と[k,n)の2つの木に分割する
	static pair<RBST*,RBST*> split(RBST *a, int k){
		if(!a) return make_pair<RBST*,RBST*>(NULL, NULL);
		if(k <= size(a->l)){
			pair<RBST*,RBST*> t = split(a->l, k);
			a->l = t.second;
			return make_pair(t.first, a->update());
		}else{
			pair<RBST*,RBST*> t = split(a->r, k - size(a->l) - 1);
			a->r = t.first;
			return make_pair(a->update(), t.second);
		}
	}
};


