struct RBST{
    #define RBST_INF INT_MAX

    struct node{
        node *lch,*rch;
        int val,mi,cnt;
        node(int val):val(val),mi(val),cnt(1){
            lch=rch=NULL;
        }
    };

    RBST():root(NULL){srand(time(NULL));}
    node *root;

    inline int count(node *t){return !t?0:t->cnt;}
    inline int mini(node *t){return !t?RBST_INF:t->mi;}

    node *update(node *t){
        if(!t)return t;
        t->cnt=count(t->lch)+count(t->rch)+1;
        t->mi=min(min(mini(t->lch),mini(t->rch)),t->val);
        return t;
    }

    node *merge(node *a,node *b){
        if(!a)return b;
        if(!b)return a;

        if(rand()%(count(a)+count(b))<count(a)){
            a->rch=merge(a->rch,b);
            return update(a);
        }
        else{
            b->lch=merge(a,b->lch);
            return update(b);
        }
    }

    pair<node *,node *>split(node *t,int k){
        if(!t)return make_pair(t,t);
        if(k<=count(t->lch)){
            pair<node *,node *>s=split(t->lch,k);
            t->lch=s.second;
            return make_pair(s.first,update(t));
        }
        else{
            pair<node *,node *>s=split(t->rch,k-count(t->lch)-1);
            t->rch=s.first;
            return make_pair(update(t),s.second);
        }
    }

    void insert(int k,int val){
        pair<node *,node *>s=split(root,k);
        root=merge(s.first,new node(val));
        root=merge(root,s.second);
    }

    void erase(int k){
        pair<node *,node *>s1,s2;
        s1=split(root,k);
        s2=split(s1.second,1);

        root=merge(s1.first,s2.second);
    }

    int getMin(int l,int r){
        pair<node *,node *>s1,s2;
        int ret;

        s1=split(root,l);
        s2=split(s1.second,r-l);
        ret=mini(s2.first);
        root=merge(s1.first,s2.first);
        root=merge(root,s2.second);
        return ret;
    }

    void update(int k,int val){
        erase(k);
        insert(k,val);
    }

    void shift(int l,int r){
        pair<node *,node *>s1,s2,s3;

        s1=split(root,l);
        s2=split(s1.second,r-l-1);
        s3=split(s2.second,1);

        root=merge(s1.first,s3.first);
        root=merge(root,s2.first);
        root=merge(root,s3.second);
    }
};

