namespace Treap {

    static const int INF = 1e9;

    struct Node {
        int key;
        int priority;
        Node *left, *right;
        int size;
        int min;
    };

    using Np = Node*;
    using pair = std::pair<Np, Np>;

    int size(Np n) {
        return n != nullptr ? n->size : 0;
    }

    int min(Np n) {
        return n != nullptr ? n->min : INF;
    }

    void update(Np n) {
        n->size = 1 + size(n->left) + size(n->right);
        n->min = std::min({ min(n->left), n->key, min(n->right) });
    }

    void assign(Np n, int k, int x) {
        if (k < size(n->left)) {
            assign(n->left, k, x);
        } else if (size(n->left) == k) {
            n->key = x;
        } else {
            assign(n->right, k - size(n->left) - 1, x);
        }
        update(n);
    }

    int min(Np n, int l, int r) {
        l = std::max(l, 0);
        r = std::min(r, size(n));
        if (l >= r) return INF;
        if (l == 0 && r == size(n)) return min(n);

        int res = INF;
        int sl = size(n->left);
        res = std::min(res, min(n->left, l, r));
        res = std::min(res, min(n->right, l - sl - 1, r - sl - 1));
        if (l <= sl && sl < r) res = std::min(res, n->key);
        return res;
    }

    Np merge(Np l, Np r) {
        if (l == nullptr) return r;
        if (r == nullptr) return l;
        //assert(l->key <= r->key);
        if (l->priority > r->priority) {
            l->right = merge(l->right, r);
            update(l);
            return l;
        } else {
            r->left = merge(l, r->left);
            update(r);
            return r;
        }
    }

    pair split(Np n, int k) {
        if (n == nullptr) return{ nullptr, nullptr };
        if (k <= size(n->left)) {
            pair p = split(n->left, k);
            n->left = p.second;
            update(n);
            return{ p.first, n };
        } else {
            pair p = split(n->right, k - size(n->left) - 1);
            n->right = p.first;
            update(n);
            return{ n, p.second };
        }
    }

    Np shift(Np n, int l, int r) {
        Np a, b, c, d;
        std::tie(a, b) = split(n, l);
        std::tie(b, c) = split(b, r - l);
        std::tie(c, d) = split(c, 1);
        a = merge(a, c);
        a = merge(a, b);
        a = merge(a, d);
        return a;
    }

    Np append(Np n, int k) {
        Np a = new Node { k, rand(), nullptr, nullptr, 1, k };
        return merge(n, a);
    }

    void show(Np n, int ofs=0) {
        using namespace std;
        if (n == nullptr) return;
        show(n->left, ofs + 2);
        cout << '-' << string(ofs, ' ') << n->key << '(' << n->min << ')' << endl;
        show(n->right, ofs + 2);
    }
};

