    void shift(int l, int r){
        int tmp = root->at(r-1)->val;
        root = root->erase(r-1);
        root = root->insert(l, tmp);
    }
    void set(int k, int x){
        root->set(k, x);
    }
    int rangemin(int l, int r){
        return root->min(l,r);
    }
    void push_back(int x){
        if(size == 0) root = new Node(x,xor128()), size++;
        else root = root->insert(size++,x);
    }
};

