struct Splay {
	Splay *lch, *rch;
	int d, val;
	Splay(int _val = 0) : lch(0), rch(0), d(1), val(_val) {}
};
typedef pair<Splay*, Splay*> P;

Splay* update(Splay* x) {
	x->d = x->lch->d + x->rch->d;
	x->val = min(x->lch->val, x->rch->val);
	return x;
}

Splay* rotr(Splay* x) {
	Splay* y = x->lch;
	x->lch = y->rch;
	y->rch = x;
	update(x);
	return update(y);
}

Splay* rotl(Splay* x) {
	Splay* y = x->rch;
	x->rch = y->lch;
	y->lch = x;
	update(x);
	return update(y);
}

/*
void propagate(Splay* x) {
	x->lch->dval += x->dval;
	x->rch->dval += x->dval;
	x->dval = 0;
}
*/

Splay* splay(Splay* x, int m) {
	if (m == 0 || m == x->d) return x;
	int d1 = x->lch->d;
	if (m < d1) {
		int d2 = x->lch->lch->d;
		if (m < d2) {
			x->lch->lch = splay(x->lch->lch, m);
			return rotr(rotr(x));
		}
		else if (m > d2) {
			x->lch->rch = splay(x->lch->rch, m - d2);
			x->lch = rotl(x->lch);
			return rotr(x);
		}
		else {
			x->lch = splay(x->lch, m);
			return rotr(x);
		}
	}
	else if (m > d1) {
		int d2 = x->rch->lch->d;
		if (m < d1 + d2) {
			x->rch->lch = splay(x->rch->lch, m - d1);
			x->rch = rotr(x->rch);
			return rotl(x);
		}
		else if (m > d1 + d2) {
			x->rch->rch = splay(x->rch->rch, m - d1 - d2);
			return rotl(rotl(x));
		}
		else {
			x->rch = splay(x->rch, m - d1);
			return rotl(x);
		}
	}
	else return x;
}

Splay* merge(Splay* x, Splay* y) {
	if (!x) return y;
	if (!y) return x;
	Splay* z = new Splay();
	z->lch = x;
	z->rch = y;
	return update(z);
}

Splay* merges(vector<Splay*> xs) {
    Splay* x = NULL;
    for (Splay* y: xs) x = merge(x, y);
    return x;
}

P split(Splay* x, int m) {
	if (m == 0) return P(NULL, x);
	if (m == x->d) return P(x, NULL);
	x = splay(x, m);
	P p(x->lch, x->rch);
	delete x;
	return p;
}

vector<Splay*> splits(Splay* x, vector<int> is) {
    reverse(is.begin(), is.end());
    vector<Splay*> xs;
    for (int i: is) {
        P p = split(x, i);
        x = p.first;
        xs.pb(p.second);
    }
    xs.pb(x);
    reverse(xs.begin(), xs.end());
    return xs;
}

