			int left=buc[i1][j1],right=buc[i2][j2];
			buc[i2].erase(buc[i2].begin()+j2);
			S[i2].erase(S[i2].find(right));
			buc[i1].insert(buc[i1].begin()+j1,right);
			S[i1].insert(right);
			for(int i=i1;i<i2;i++){
				int tmp=buc[i].back();
				buc[i].pop_back();
				S[i].erase(S[i].find(tmp));
				buc[i+1].push_front(tmp);
				S[i+1].insert(tmp);
			}
		}
		else if(type==1){
