				for(int j=j1;j<=j2;j++) val=min(val,buc[i1][j]);
			}
			else{
				for(int j=j1;j< B;j++) val=min(val,buc[i1][j]);
				for(int j=j2;j>=0;j--) val=min(val,buc[i2][j]);
				for(int i=i1+1;i<i2;i++) val=min(val,*S[i].begin());
			}
		}
		else{
			int pos,val; scanf("%d%d",&pos,&val);
			int i;
			for(i=0;(i+1)*B<=pos;i++);
			int j=pos-i*B;
			int pre=buc[i][j];
			buc[i][j]=val;
			S[i].erase(S[i].find(pre));
			S[i].insert(val);
		}
	}

	return 0;
}

