class Node {
public:
  Node *left, *right;
  int num;
  int value;
  int min;
  Node() {}
};

Node *root;

Node* initLeaf(int v) {
  Node *res = new Node;
  res->left = res->right = nullptr;
  res->num = 1;
  res->value = v;
  res->min = v;
  return res;
}

Node* initNode(Node* left, Node* right) {
  Node *res = new Node;
  res->left = left;
  res->right = right;
  res->num = 0;
  res->value = 0;
  res->min = (1 << 30);
  return res;
}

bool isLeaf(Node* p) {
  if( p == nullptr ) return false;
  return p->left == nullptr and p->right == nullptr;
}


int getNum(Node* p) {
  if( p == nullptr ) return 0;
  if( isLeaf(p) ) return 1;
  return p->num;
}

Node* getLeft(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->left;
}

Node* getRight(Node* p) {
  if( p == nullptr ) return nullptr;
  return p->right;
}

int getValue(Node* p) {
  if( p == nullptr ) return (1 << 30);
  //assert( p != nullptr );
  return p->value;
}


// checker
void dump2(Node* node) {
  if( node == nullptr ) return;
  if( node->left == nullptr and node->right == nullptr ) {
    printf("{%d,%d}", node->value, node->min);
    return;
  }
  printf("(%d,%d)[", node->num, node->min);
  dump2(node->left);
  putchar(',');
  dump2(node->right);
  putchar(']');
}

Node* dump(Node* node) {
  dump2(node);
  putchar('\n');
  return node;
}

int maxDepth(Node* node) {
  if( node == nullptr ) return -1;
  if( isLeaf(node) ) return 0;
  return 1 + std::max(maxDepth(getLeft(node)), maxDepth(getRight(node)));
} 


Node* update(Node* p) {
  if( p == nullptr ) return nullptr;
  assert( not isLeaf(p) );
  p->num = getNum(getLeft(p)) + getNum(getRight(p));
  if( isLeaf(p) ) {
    p->min = p->value;
  }
  else {
    p->min = std::min(getValue(getLeft(p)), getValue(getRight(p)));
  }
  return p;
}

Node* merge(Node* left, Node* right) {
  if( left == nullptr and right == nullptr ) return nullptr;
  if( isLeaf(left) and isLeaf(right) ) return update(initNode(left, right));
  if( left == nullptr and isLeaf(right) ) return right;
  if( right == nullptr and isLeaf(left) ) return left;
  if( left == nullptr or right == nullptr ) return update(initNode(left, right));
  if( getNum(left) < getNum(right) or (getNum(left) == getNum(right) and rand() % 2 == 0) ) {
    if( isLeaf(right) ) return update(initNode(left, right));
    // left merged
    Node *w = merge(left, getLeft(right));
    Node *v = initNode(w, getRight(right));
    assert( not isLeaf(v) );
    if( isLeaf(w) ) return update(v);
    //rotate right only
    //right
    if( getNum(getLeft(w)) > getNum(getRight(v)) ) {
      v->left  = getRight(w);
      w->right = v;
      update(v);
      return update(w);
    }
    if( not isLeaf(getRight(w)) and std::abs(getNum(w) - getNum(getRight(v))) > std::abs((getNum(getLeft(w)) + getNum(getLeft(getRight(w)))) - (getNum(getRight(getRight(w))) + getNum(getRight(v)))) ) {
      Node *x = initNode(w, v);
      v->left  = getRight(getRight(w));
      w->right = getLeft(getRight(w));
      update(w);
      update(v);
      return update(x);
    }
    return update(v);
  }
  else {
    if( isLeaf(left) ) return update(initNode(left, right));
    Node *w = merge(getRight(left), right);
    Node *v = initNode(getLeft(left), w);
    assert( not isLeaf(v) );
    if( isLeaf(w) ) return update(v);
    // rotate left only
    // left
    if( getNum(getLeft(v)) < getNum(getRight(w)) ) {
      v->right = getLeft(w);
      w->left  = v;
      update(v);
      return update(w);
    }
    if( not isLeaf(getLeft(w)) and std::abs(getNum(getLeft(v)) - getNum(w)) > std::abs((getNum(getLeft(v)) + getNum(getLeft(getLeft(w)))) - (getNum(getRight(getLeft(w))) + getNum(getRight(w)))) ) {
      Node *x = initNode(v, w);
      v->right = getLeft(getLeft(w));
      w->left  = getRight(getLeft(w));
      update(v);
      update(w);
      return update(x);
    }
    return update(v);
  }
}

// [0, k), [k, size)
std::pair<Node*, Node*> split(Node* p, int k) {
  if( getNum(p) == k ) return std::pair<Node*, Node*>(p, nullptr);
  if( k == 0 ) return std::pair<Node*, Node*>(nullptr, p);
  if( k <= getNum(getLeft(p)) ) {
    Node *left, *right;
    std::tie(left, right) = split(getLeft(p), k);
    return std::pair<Node*, Node*>(left, merge(right, getRight(p)));
  }
  else {
    Node *left, *right;
    std::tie(left, right) = split(getRight(p), k - getNum(getLeft(p)));
    return std::pair<Node*, Node*>(merge(getLeft(p), left), right);
  }
}

// [l, r)
int minimum(Node* p, int l, int r) {
  if( isLeaf(p) ) return p->value;
  //if( l == 0 and r == getNum(p) ) return p->min;
  if( r <= getNum(getLeft(p)) ) {
    return minimum(getLeft(p), l, r);
  }
  else if( getNum(getLeft(p)) <= l ) {
    return minimum(getRight(p), l - getNum(getLeft(p)), r - getNum(getLeft(p)));
  }
  else {
    int leftmin  = minimum(getLeft(p), l, getNum(getLeft(p)));
    int rightmin = minimum(getRight(p), 0, r - getNum(getLeft(p)));
    return std::min(leftmin, rightmin);
  }
}


