struct Spray{
    Spray(int v){
	val = v;
	minimum = v;
	size = 1;
	l = r = p = 0;
    }
    int val, minimum, size;
    Spray *l, *r, *p;

    int state(){
	if(p == 0)return 0;
	if(p->l == this)return -1;
	if(p->r == this)return 1;
    }

    Spray *update(){
	size = (l?l->size:0) + (r?r->size:0) + 1;
	minimum = min(val, min((l?l->minimum:INF), (r?r->minimum:INF)));
	return this;
    }

    void rotate(){
	Spray *par = p, *mid;
	if(par->l == this){
	    mid = r;r = par;
	    par->l = mid;
	}
	if(par->r == this){
	    mid = l;l = par;
	    par->r = mid;
	}
	if(mid)mid->p = par;
	p = par->p; par->p = this;
	if(p && p->l == par)p->l = this;
	if(p && p->r == par)p->r = this;
	par->update();
	update();
    }

    void spray(){
	while(state()){
	    int st = state() * p->state();
	    if(st == -1)rotate();
	    if(st == 1)p->rotate();
	    rotate();
	}
    }
};

typedef pair<Spray*, Spray*> SprayP;
typedef SprayP P;

Spray* node(Spray *r, int pos){
    int lsize = (r->l)?r->l->size:0;
    int rsize = (r->r)?r->r->size:0;
    if(lsize == pos - 1)return r;
    if(lsize >  pos - 1)return node(r->l, pos);
    if(lsize <  pos - 1)return node(r->r, pos - lsize - 1);
}

SprayP split(Spray* r, int pos){
    if(pos == 0)return P(0, r);
    if(r->size == pos) return P(r, 0);
    r = node(r, pos);
    r->spray();
    Spray *right = r->r;
    r->r = 0; right->p = 0;
    return P(r->update(), right->update());
}

Spray *merge(Spray *a, Spray *b){
    if(a == 0)return b;
    if(b == 0)return a;
    a = node(a, a->size);
    a->spray();b->spray();
    a->r = b; b->p = a;
    a->update();
    return a->update();
}

SprayP delt(Spray *r, int pos){
    SprayP tmp1 = split(r, pos);
    SprayP tmp2 = split(tmp1.second, 1);
    return P(merge(tmp1.first, tmp2.second), tmp2.first);
}

Spray *insert(Spray *r, Spray *it, int pos){
    SprayP tmp = split(r, pos);
    return merge(merge(tmp.first, it), tmp.second);
}

Spray *shift(Spray *r, int left, int right){
    SprayP tmp = delt(r, right);
    return insert(tmp.first, tmp.second, left);
}

Spray *setnum(Spray *r, int pos, int val){
    r = node(r, pos + 1);
    r->spray();
    r->val = val;
    return r->update();
}

Spray *comb(Spray *r, Spray *l){
    l->l = r;
    if(r) r->p = l;
    return l->update();
}

