            x->r = y.first;
            y.first = x->update();
            return y;
        }
    }*/
    void insert(D x) {
        n = insert(n, lb(x), x);
    }
    void insert_idx(int k, D x) {
        n = insert(n, k, x);
    }
    void erase(D x) {
        n = remove(n, lb(x));
    }
    void remove(int k) {
        n = remove(n, k);
    }
    NP get_ptr(int k) {
        if (k < 0 || sz() <= k) return last;
        return n->get_ptr(k);
    }
    D at(int k) {
        assert(0 <= k && k < sz());
        return n->at(k);
    }
    int lb(D v) {
        return n->lb(v);
    }
    int ub(D v) {
        return n->ub(v);
    }
    int sz() {
        return n->sz;
    }
    D minv(int l, int r) {
        return n->minv(l, r);
    }
    void set(int k, D x) {
        n->set(k, x);
        return;
    }
    void tp() {
        n->tp();
        printf("\n");
    }
};
