int32_t xor128() {
  static uint32_t x = 123456789, y = 362436069, z = 521288629, w = time(0);
  uint32_t t = x ^ (x << 11);
  x = y;
  y = z;
  z = w;
  w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
  return w & 0x3FFFFFFF;
}

using key_t = int;
const key_t INF = 1000000000;
const int MAX_N = 5000010;
enum { L, R };
struct node {
  key_t key;
  node *ch[2];
  int size;
  key_t min;

  static node *const nil;

  node() : node(0) {}

  node(const key_t &x) : key(x), size(1), min(x) { ch[L] = ch[R] = node::nil; }

  node(node *left_, node *right_, int size_, const key_t &min_)
      : size(size_), min(min_) {
    ch[L] = left_;
    ch[R] = right_;
  }

  void *operator new(std::size_t) {
    static node pool[MAX_N];
    static int p = 0;
    return pool + p++;
  }

  bool is_leaf() const { return size == 1; }
};

using np = node *;
using cnp = const node *;
using npair = std::pair<np, np>;

node *const node::nil = new node(nullptr, nullptr, 0, INF);

struct rbst {
  np root;

  rbst() : root(node::nil) {}

  rbst(np root_) : root(root_) {}

  rbst(key_t *left, key_t *right) : root(make_tree(left, right)) {}

  np make_tree(key_t *left, key_t *right) {
    int sz = right - left;
    key_t *mid = left + sz / 2;
    if (sz == 0) {
      return node::nil;
    } else if (sz == 1) {
      return new node(*mid);
    } else {
      np lc = make_tree(left, mid);
      np rc = make_tree(mid, right);
      return new node(lc, rc, sz, std::min(lc->min, rc->min));
    }
  }

  int size() const { return root->size; }

  void set(int k, const key_t &x) { set(root, k, x); }

  void set(np n, int k, const key_t &x) {
    if (n->is_leaf()) {
      n->key = n->min = x;
    } else {
      if (k < n->ch[L]->size)
        set(n->ch[L], k, x);
      else
        set(n->ch[R], k - n->ch[L]->size, x);
      update(n);
    }
  }

  key_t get(cnp n, int k) const {
    if (n->size == 1)
      return n->key;
    else if (k < n->ch[L]->size)
      return get(n->ch[L], k);
    else
      return get(n->ch[R], k - n->ch[L]->size);
  }

  key_t range_min(int l, int r) const { return range_min(root, l, r); }

  key_t range_min(cnp n, int l, int r) const {
    l = std::max(l, 0);
    r = std::min(r, n->size);
    if (l >= r)
      return INF;
    if (l == 0 && r == n->size)
      return n->min;
    key_t res = INF;
    int sl = n->ch[L]->size;
    res = std::min(res, range_min(n->ch[L], l, r));
    res = std::min(res, range_min(n->ch[R], l - sl, r - sl));
    return res;
  }

  // ???????????????????????¨??¢??°??§??¨???????????¶???????????\??????
  np insert(np n, int k, const key_t &x) const {
    return n == node::nil ? new node(x) : insert_sub(n, k, x);
  }

  // ???????????????????????????
  np insert_sub(np n, int k, const key_t &x) const {
    if (n->is_leaf()) {
      return update(k == 0 ? new node(new node(x), n, 2, INF)
                           : new node(n, new node(x), 2, INF));
    } else {
      if (k < n->ch[L]->size)
        n->ch[L] = insert_sub(n->ch[L], k, x);
      else
        n->ch[R] = insert_sub(n->ch[R], k - n->ch[L]->size, x);
      return balance(update(n));
    }
  }

  // ???????????????????????¨??¢??°??§??¨???????????¶???????????\??????
  np erase(np n, int k) const {
    return n->is_leaf() ? node::nil : erase_sub(n, k);
  }

  // ???????????????????????????
  np erase_sub(np n, int k) const {
    // ?????????????????????????´???????????????????????????????
    if (k == 0 && n->ch[L]->is_leaf()) {
      return n->ch[R];
    } else if (k == n->size - 1 && n->ch[R]->is_leaf()) {
      return n->ch[L];
    } else {
      if (k < n->ch[L]->size)
        n->ch[L] = erase_sub(n->ch[L], k);
      else
        n->ch[R] = erase_sub(n->ch[R], k - n->ch[L]->size);
      return balance(update(n));
    }
  }

  np balance(np n) const {
    // size???????????°????????§?????¨??????????????°??????????????????-1??????
    int sl = n->ch[L]->size - 1, sr = n->ch[R]->size - 1;
    int rand = xor128() % (sl + 1 + sr);
    if (rand < sl)
      return rotate<R>(n);
    else if (rand > sl)
      return rotate<L>(n);
    else
      return n;
  }

  template <int dir> np rotate(np n) const {
    np par = n->ch[1 - dir];
    n->ch[1 - dir] = par->ch[dir];
    par->ch[dir] = update(n);
    return update(par);
  }

  np update(np n) const {
    assert(!n->is_leaf());
    n->size = n->ch[L]->size + n->ch[R]->size;
    n->min = std::min(n->ch[L]->min, n->ch[R]->min);
    return n;
  }

  void shift_erase_insert(int l, int r) {
    key_t x = get(root, r);
    root = erase(root, r);
    root = insert(root, l, x);
  }
};

