struct Node {
    Node* p;
    Node* l;
    Node* r;
    i64 sz;  // 部分木のサイズ

    i64 value;
    i64 minimum;

    Node() :
        p(nullptr), l(nullptr), r(nullptr), sz(1),
        value(0), minimum(0) {}
};

void splay_update(Node* node) {
    node->sz      = 1;
    node->minimum = node->value;
    if(node->l) {
        node->sz += node->l->sz;
        chmin(node->minimum, node->l->minimum);
    }
    if(node->r) {
        node->sz += node->r->sz;
        chmin(node->minimum, node->r->minimum);
    }
}

void splay_connect_l(Node* node, Node* c) {
    if(c) c->p = node;
    node->l = c;
    splay_update(node);
}

void splay_connect_r(Node* node, Node* c) {
    if(c) c->p = node;
    node->r = c;
    splay_update(node);
}

Node* splay_cut_l(Node* node) {
    Node* l = node->l;
    if(!l) return l;

    l->p    = nullptr;
    node->l = nullptr;
    splay_update(node);
    return l;
}

Node* splay_cut_r(Node* node) {
    Node* r = node->r;
    if(!r) return r;

    r->p    = nullptr;
    node->r = nullptr;
    splay_update(node);
    return r;
}

pair<Node*,Node*> splay_cut_lr(Node* node) {
    Node* l = node->l;
    Node* r = node->r;

    if(l) l->p = nullptr;
    if(r) r->p = nullptr;
    node->l = node->r = nullptr;
    splay_update(node);
    return {l,r};
}

void splay_rotate(Node* node) {
    ASSERT(node->p);
    Node* p  = node->p;
    Node* pp = p->p;

    // 下向きの辺(l,r)を更新
    Node* c;
    if(p->l == node) {
        c       = node->r;
        p->l    = c;
        node->r = p;
    }
    else {
        c       = node->l;
        p->r    = c;
        node->l = p;
    }
    if(pp && pp->l == p)
        pp->l = node;
    else if(pp && pp->r == p)
        pp->r = node;

    // 上向きの辺(p)を更新
    if(c) c->p = p;
    p->p    = node;
    node->p = pp;

    splay_update(p);
    splay_update(node);
}

void splay_splay(Node* node) {
    while(Node* p = node->p) {
        Node* pp = p->p;
        if(!pp) {
            splay_rotate(node);
            continue;
        }

        bool zigzig = (pp->l==p && p->l==node) || (pp->r==p && p->r==node);
        if(zigzig) {
            splay_rotate(p);
            splay_rotate(node);
        }
        else {
            splay_rotate(node);
            splay_rotate(node);
        }
    }
}

Node* splay_at(Node* node, i64 i) {
    ASSERT(0 <= i && i < node->sz);

    for(;;) {
        i64 lsz = node->l ? node->l->sz : 0;
        if(i == lsz) {
            splay_splay(node);
            return node;
        }

        if(i < lsz) {
            node = node->l;
        }
        else {  // i > lsz
            node  = node->r;
            i    -= lsz+1;
        }
    }
}

void splay_set(Node* node, i64 x) {
    node->value = x;
    splay_update(node);
}

Node* splay_merge(Node* l, Node* r) {
    ASSERT(l || r);
    if(!l) return r;
    if(!r) return l;

    Node* root = splay_at(l, l->sz-1);
    splay_connect_r(root, r);
    return root;
}

pair<Node*,Node*> splay_split(Node* node, i64 lsz) {
    if(lsz == 0)        return {nullptr, node};
    if(lsz == node->sz) return {node, nullptr};

    Node* r = splay_at(node, lsz);
    Node* l = splay_cut_l(r);

    return {l,r};
}

Node* splay_insert(Node* node, i64 i, Node* v) {
    Node *l,*r; tie(l,r) = splay_split(node, i);
    return splay_merge(splay_merge(l,v), r);
}

pair<Node*,Node*> splay_remove(Node* node, i64 i) {
    Node* v = splay_at(node, i);
    Node *l,*r; tie(l,r) = splay_cut_lr(v);
    return {splay_merge(l,r), v};
}

// [l,r)
Node* splay_shift(Node* node, i64 l, i64 r) {
    ASSERT(l < r);
    Node* v; tie(node,v) = splay_remove(node, r-1);
    return splay_insert(node, l, v);
}

pair<Node*,i64> splay_rmq(Node* node, i64 l, i64 r) {
    ASSERT(l < r);
    Node *lroot, *rroot;
    tie(node, rroot) = splay_split(node, r);
    tie(lroot, node) = splay_split(node, l);
    i64   res_min  = node->minimum;
    Node* res_root = splay_merge(splay_merge(lroot,node), rroot);
    return {res_root, res_min};
}

void splay_dump(Node* node, i64 indent) {
#if 0
    if(!node) return;
    splay_dump(node->l, indent+1);
    PRINT(string(indent,' '));
    PRINTLN(node->value);
    splay_dump(node->r, indent+1);
#endif
}

void solve() {
    i64 N = RD();
    i64 Q = RD();

    vector<Node> nodes(N);
    REP(i, N-1) {
        splay_connect_l(&nodes[i+1], &nodes[i]);
    }

    REP(i, N) {
        i64 a = RD();
        splay_set(&nodes[i], a);
    }

    Node* root = &nodes.back();
    splay_dump(root, 0);

    enum { CMD_SHIFT=0, CMD_RMQ=1, CMD_SET=2 };
    REP(_, Q) {
        i64 cmd = RD();
        if(cmd == CMD_SHIFT) {
            i64 l = RD();
            i64 r = RD(); ++r;  // [l,r)
            DBG(cmd,l,r);
            root = splay_shift(root, l, r);
        }
        else if(cmd == CMD_RMQ) {
            i64 l = RD();
            i64 r = RD(); ++r;  // [l,r)
            DBG(cmd,l,r);
            i64 ans; tie(root,ans) = splay_rmq(root, l, r);
            PRINTLN(ans);
        }
        else if(cmd == CMD_SET) {
            i64 i = RD();
            i64 x = RD();
            DBG(cmd,i,x);
            root = splay_at(root, i);
            splay_set(root, x);
        }
        else { ASSERT(false); }
        splay_dump(root, 0);
    }
}

signed main() {


    solve();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using T = int;
const T id = INT_MAX;
T op(T l, T r) {
	return min(l, r);
}

enum COL { BLACK, RED };

struct node;
node *update(node *t);
struct node {
	T val, all;
	node *ch[2];
	COL color;
	int level;
	int size;
	node() {}
	void init(T v) {
		val = v;
		all = v;
		color = BLACK;
		level = 0;
		size = 1;
		ch[0] = ch[1] = nullptr;
	}
	void init(node *l, node *r) {
		val = id;
		color = RED;
		ch[0] = l;
		ch[1] = r;
		update(this);
	}
};

const int pmax = 1e6;
node pool[pmax];
queue<int> deleted;
int it = 0;

int count(node *t) { return !t ? 0 : t->size; }

T que(node *t) { return !t ? id : t->all; }

node *update(node *t) {
	t->size = count(t->ch[0]) + count(t->ch[1]) + (!t->ch[0] || !t->ch[1]);
	t->all = op(que(t->ch[0]), op(t->val, que(t->ch[1])));
	t->level = (t->ch[0] ? t->ch[0]->level + (t->ch[0]->color == BLACK) : 0);
	return t;
}

node *new_leaf(T v) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(v);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(v);
	return pool + it++;
}

node *new_node(node *l, node *r) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(l, r);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(l, r);
	return pool + it++;
}

void delete_node(node* t) {
	deleted.push(t - pool);
}

node *rotate(node *t, int b) {
	node *s = t->ch[1 - b];
	t->ch[1 - b] = s->ch[b];
	s->ch[b] = t;
	update(t);
	return update(s);
}

node *submerge(node *l, node *r) {
	if (l->level < r->level) {
		node *c = submerge(l, r->ch[0]);
		r->ch[0] = c;
		if (r->color == BLACK && c->color == RED && c->ch[0] && c->ch[0]->color == RED) {
			if (r->ch[1]->color == BLACK) {
				r->color = RED;
				c->color = BLACK;
				return rotate(r, 1);
			}
			c->color = BLACK;
			r->ch[1]->color = BLACK;
			r->color = RED;
		}
		return update(r);
	}
	if (l->level > r->level) {
		node *c = submerge(l->ch[1], r);
		l->ch[1] = c;
		if (l->color == BLACK && c->color == RED && c->ch[1] && c->ch[1]->color == RED) {
			if (l->ch[0]->color == BLACK) {
				l->color = RED;
				c->color = BLACK;
				return rotate(l, 0);
			}
			l->ch[0]->color = BLACK;
			c->color = BLACK;
			l->color = RED;
		}
		return update(l);
	}
	return new_node(l, r);
}

node *merge(node *l, node *r) {
	if (!l) return r;
	if (!r) return l;
	node *c = submerge(l, r);
	c->color = BLACK;
	return c;
}

pair<node*, node*> split(node *t, int k) {
	if (!t) return make_pair(nullptr, nullptr);
	if (k == 0) return make_pair(nullptr, t);
	if (k >= count(t)) return make_pair(t, nullptr);
	int c = count(t->ch[0]);
	node *l = t->ch[0], *r = t->ch[1];
	delete_node(t);
	if (k < c) {
		pair<node*, node*> p = split(l, k);
		return make_pair(p.first, merge(p.second, r));
	}
	if (k > c) {
		pair<node*, node*> p = split(r, k - c);
		return make_pair(merge(l, p.first), p.second);
	}
	return make_pair(l, r);
}

node *insert(node *t, int k, T v) {
	pair<node*, node*> s = split(t, k);
	return merge(merge(s.first, new_leaf(v)), s.second);
}

node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	return merge(s1.first, s2.second);
}

T find(node *t, int l, int r) {
	if (!t) return id;
	if (r < 0 || l >= count(t)) return id;
	if (l <= 0 && r >= t->size) return t->all;
	int c = count(t->ch[0]), d = c + (!t->ch[0] || !t->ch[1]);
	return op(!t->ch[0] ? id : find(t->ch[0], l, r), op(l <= c && c < r ? t->val : id, !t->ch[1] ? id : find(t->ch[1], l - d, r - d)));
}

node *find(node *t, int k) {
	if (!t) return t;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	return c == 0 && b ? t : k < c ? find(t->ch[0], k) : find(t->ch[1], k - c - b);
}

void update(node *t, int k, T val) {
	if (!t) return;
	int c = count(t->ch[0]), b = (!t->ch[0] || !t->ch[1]);
	if (c == 0 && b) {
		t->val = val;
		return;
	}
	if (k < c) {
		update(t->ch[0], k, val);
	}
	else {
		update(t->ch[1], k - c - b, val);
	}
	update(t);
}

