struct node{
    node* l;
    node* r;
    int val;
    int top;
    int size;
    node(int n){
        l=r=nullptr;
        val=top=n;
        size=1;
    }
    void pull(){
        size=1;
        top=val;
        if(l){
            size+=l->size;
            top=min(top,l->top);
        }
        if(r){
            size+=r->size;
            top=min(top,r->top);
        }
        return ;
    }
    void out(){
        if(l){
            l->out();
            printf(" ");
        }
        printf("%d",val);
        if(r){
            printf(" ");
            r->out();
        }
        return ;
    }
    int lsize(){
        return l?l->size+1:1;
    }
};
node* merge(node* a,node* b){
    if(!a)return b;
    if(!b)return a;
    if(rand(a->size,b->size)){
        a->r=merge(a->r,b);
        a->pull();
        return a;
    }
    else{
        b->l=merge(a,b->l);
        b->pull();
        return b;
    }
}
void split(node* s,int n,node*&a,node*&b){
    if(!s){
        a=b=nullptr;
        return ;
    }
    if(s->lsize()>n){
        b=s;
        split(s->l,n,a,b->l);
        b->pull();
    }
    else{
        a=s;
        split(s->r,n-s->lsize(),a->r,b);
        a->pull();
    }
    return ;
}
int find(node* s,int pl,int pr,int L,int R){
    int ans=INF;
    if(L>pr||pl>R||!s)return ans;
    if(L<=pl){
        if(pr<=R)return s->top;
        if(s->lsize()+pl-1<=R){
            if(s->l)ans=min(ans,s->l->top);
            ans=min(ans,min(s->val,find(s->r,s->lsize()+pl,pr,L,R)));
        }
        else return find(s->l,pl,s->lsize()+pl-2,L,R);
    }
    else if(pr<=R){
        if(s->lsize()+pl-1>=L){
            if(s->r)ans=min(ans,s->r->top);
            ans=min(ans,min(s->val,find(s->r,pl,s->lsize()+pl-2,L,R)));
        }
        else return find(s->r,s->lsize()+pl,pr,L,R);
    }
    else{
        if(L<=s->lsize()+pl-1&&s->lsize()+pl-1<=R)ans=min(ans,s->val);
        ans=min(ans,min(find(s->l,pl,s->lsize()+pl-2,L,R),find(s->r,s->lsize()+pl,pr,L,R)));
    }
    return ans;
}
