#define rep(i,n) for(int i=0;i<(int)(n);i++)
#define rrep(i,n) for(int i=(int)(n)-1;i>=0;i--)
using namespace std;
typedef pair<int,int> pii;
typedef vector<pii> vp;
typedef vector<int> vi;

class SegmentTree{
  int n;
  vp node;
public:
  SegmentTree(vector<int> a){
    int n_ = a.size();
    n=1;
    while(n<n_)n*=2;
    node.resize(2*n-1, pii(1e9, 0));
    for(int i=0;i<n_;i++){
      node[n-1+i] = pii(a[i], (a[i]==1e9)?0:1);
    }
    for(int i=n-2;i>=0;i--){
      node[i].first = min(node[2*i+1].first, node[2*i+2].first);
      node[i].second = node[2*i+1].second + node[2*i+2].second;
    }
  }

  void update(int k, int v, int add){
    int cur = k + n-1;
    node[cur] = pii(v,add);
    while(cur>0){
      cur = (cur-1)/2;
      node[cur].first = min(node[cur*2+1].first,node[cur*2+2].first);
      node[cur].second = node[cur*2+1].second + node[cur*2+2].second;
    }
  }

  int RMQ(int a,int b,int k=0,int l=0,int r=0){
    if(l>=r)r = n;
    if(r<=a || b<=l)return 1e9;
    if(a<=l && r<=b)return node[k].first;
    int vl = RMQ(a,b,2*k+1,l,(l+r)/2);
    int vr = RMQ(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
  }

  int ith_smallest(int i,int k=0){
    if(k>=n-1)return k-(n-1);
    if(node[2*k+1].second > i)return ith_smallest(i,2*k+1);
    return ith_smallest(i-node[2*k+1].second,2*k+2);
  }
};

struct FenwickTree{
  int n;
  vi bit;
  FenwickTree(int x = 0):n(x){bit = vi(x+1,0);}

  void add(int i, int x){
    i++;
    while(i <= n){
      bit[i] += x;
      i += i & -i;
    }
  }

  int sum(int i){
    i++;
    int res = 0;
    while(i > 0){
      res += bit[i];
      i -= i & -i;
    }
    return res;
  }
};

int main(){
  int n,q;
  scanf("%d%d",&n,&q);

  vi a(n),x(q),y(q),z(q);
  rep(i,n)scanf("%d",&a[i]);
  FenwickTree bit1(n+1),bit2(n);
  rep(i,q){
    scanf("%d%d%d",&x[i],&y[i],&z[i]);
    if(x[i]==0){
      int l=-1,r=n;
      while(r-l>1){
	int m = (l+r)/2;
	if( m+bit1.sum(m)-bit2.sum(m) >= y[i])r = m;
	else l = m;
      }
      bit1.add(r,1);

      l=-1,r=n;
      while(r-l>1){
	int m = (l+r)/2;
	if( m+bit1.sum(m)-bit2.sum(m) >= z[i])r = m;
	else l = m;
      }
      bit2.add(r,-1);
    }
  }

  vi id(n);
  rep(i,n){
    id[i] = i + bit1.sum(i);
  }

  vi v(n+bit1.sum(n),1e9);
  rep(i,n)v[id[i]] = a[i];

  SegmentTree st(v);
  rep(i,q){
    if(x[i] == 0){
      int l = st.ith_smallest(y[i])-1, r = st.ith_smallest(z[i]);
      st.update(l,v[r],1); st.update(r,1e9,0);
      v[l] = v[r]; v[r] = 1e9;
    }else if(x[i] == 1){
      int l = st.ith_smallest(y[i]), r = st.ith_smallest(z[i]);
      printf("%d\n",st.RMQ(l,r+1));
    }else{
      int p = st.ith_smallest(y[i]);
      st.update(p,z[i],1);
      v[p] = z[i];
    }
  }
}

