		if (x == 0) {
			int val = tree.find(z);
			tree.erase(z);
			tree.insert(y, val);
		}
		else if (x == 1) {
			printf("%d\n", tree.find(y, z + 1));
		}
		else {
			tree.update(y, z);
		}
	}
	return 0;
}

