import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {

	private static final Integer MAX_VALUE = Integer.valueOf(10000000);
	private static final int BASE_SIZE = 200;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int nSize = in.nextInt();
		int qSize = in.nextInt();
		ArrayList<LinkedList<Integer>> all = new ArrayList<LinkedList<Integer>>();
		List<Integer> layerMin = new ArrayList<Integer>();
		{
			for (int n = 0; n < nSize; n++) {
				int layerIndex = n / BASE_SIZE;
				if (n % BASE_SIZE == 0) {
					layerMin.add(MAX_VALUE);
					all.add(new LinkedList<Integer>());
				}
				Integer val = Integer.valueOf(in.nextInt());
				all.get(layerIndex).add(val);
				if (layerMin.get(layerIndex).compareTo(val) > 0) {
					layerMin.set(layerIndex, val);
				}
			}
			//			testPrint(all, layerMin);
		}
		for (int q = 0; q < qSize; q++) {
			int queryNum = in.nextInt();
			int q1 = in.nextInt();
			int q2 = in.nextInt();
			//			System.out.println(queryNum + ":" + q1 + ":" + q2);
			{
				int layerIndexR = q2 / BASE_SIZE;
				int posiInLayerR = q2 % BASE_SIZE;
				int layerIndexL = q1 / BASE_SIZE;
				int posiInLayerL = q1 % BASE_SIZE;
				if (queryNum == 0) {
					Integer move = all.get(layerIndexR).remove(posiInLayerR);
					Integer removeInt = move;
					for (int i = layerIndexR; i > layerIndexL; i--) {
						Integer addInt = all.get(i - 1).removeLast();
						resetMin(all, layerMin, i, removeInt, addInt);
						all.get(i).addFirst(addInt);
						removeInt = addInt;
					}
					resetMin(all, layerMin, layerIndexL, removeInt, move);
					all.get(layerIndexL).add(posiInLayerL, move);
				} else if (queryNum == 1) {
					Integer min = MAX_VALUE;
					if (layerIndexL != layerIndexR) {
						List<Integer> subList;
						subList = all.get(layerIndexL).subList(posiInLayerL, all.get(layerIndexL).size());
						for (Integer v : subList) {
							min = min(min, v);
						}
						subList = all.get(layerIndexR).subList(0, posiInLayerR);
						for (Integer v : subList) {
							min = min(min, v);
						}
						subList = layerMin.subList(layerIndexL + 1, layerIndexR);
						for (Integer v : subList) {
							min = min(min, v);
						}
					} else {
						List<Integer> list = all.get(layerIndexL).subList(posiInLayerL, posiInLayerR + 1);
						for (Integer v : list) {
							min = min(min, v);
						}
					}
					System.out.println(min);
				}
			}
			if (queryNum == 2) {
				int layerIndex = q1 / BASE_SIZE;
				int posiInLayer = q1 % BASE_SIZE;
				Integer val = Integer.valueOf(q2);
				Integer removeInt = all.get(layerIndex).set(posiInLayer, val);
				resetMin(all, layerMin, layerIndex, removeInt, val);

			}

			//			testPrint(all, layerMin);
		}

	}

	private static Integer min(Integer o1, Integer o2) {
		if (o1.compareTo(o2) > 0) {
			return o2;
		}
		return o1;
	}

	private static void resetMin(ArrayList<LinkedList<Integer>> all, List<Integer> layerMin, int layerIndex,
			Integer removeInt, Integer addInt) {
		Integer min = layerMin.get(layerIndex);
		if (addInt.compareTo(min) < 0) {
			layerMin.set(layerIndex, addInt);
		} else if (removeInt.compareTo(min) == 0) {
			min = addInt;
			for (Integer v : all.get(layerIndex)) {
				min = min(min, v);
			}
			layerMin.set(layerIndex, min);
		}
	}

	private static void testPrint(ArrayList<LinkedList<Integer>> all, List<Integer> layerMin) {
		System.out.println("------------");
		int i = 0;
		for (List<Integer> list : all) {
			System.out.println(list + "(" + layerMin.get(i++) + ")");
		}
		System.out.println("------------");
	}
}

import java.util.Random;
import java.util.Scanner;

// Randomized Binary Search Tree
public class Main {

  static Random gen;
  static final long INF = 1 << 29;

  static class Node {

    public long v;
    public Node left, right;
    public int count;
    public long plus;
    public long minimum;

    public Node(long v) {
        this.v = v;
        this.plus = 0;
        update(this);
    }

    public Node clone() {
        Node n = new Node(this.v);
        n.left = this.left;
        n.right = this.right;
        n.plus = this.plus;
        return update(n);
    }

    public Node update(Node a) {
        if(a == null) return null;
        a.count = 1;
        if(a.left != null) a.count += a.left.count;
        if(a.right != null) a.count += a.right.count;
        a.minimum = Math.min(Math.min(a.left != null ? a.left.minimum : INF, a.right != null ? a.right.minimum : INF), a.v);
        return a;
    }

    public int count(Node a) {
        return a == null ? 0 : a.count;
    }
  }


  public static Node merge(Node a, Node b) {
    if(b == null) return a;
    if(a == null) return b;
    if(gen.nextInt(a.count + b.count) < a.count) { // a is larger
      Node ac = propagate(a);
      ac.right = merge(ac.right, b);
      return ac.update(ac);
    } else {
      Node bc = propagate(b);
      bc.left = merge(a, bc.left);
      return bc.update(bc);
    }
  }

   //[0,K)
  public static Node[] split(Node a, int K) {
    if(a == null) return new Node[]{null, null};
    Node ac = propagate(a);
    if(K <= a.count(a.left)) {
      Node[] s = split(ac.left, K);
      ac.left = s[1];
      s[1] = ac.update(ac);
      return s;
    } else {
      Node[] s = split(ac.right, K - ac.count(ac.left) - 1);
      ac.right = s[0];
      s[0] = ac.update(ac);
      return s;
    }
  }

  public static Node insert(Node a, int K, Node b) {
    if(a == null) return b;
    Node[] s = split(a, K);
    return merge(merge(s[0], b), s[1]);
  }

  // delayed-evaluation???split&merge)
  public static Node propagate(Node a) {
    if(a == null) return null;
    if(a.plus == 0) return a.clone();
    Node ac = a.clone();
    if(a.left != null) {
      Node acleft = a.left.clone();
      acleft.plus += a.plus;
      acleft.update(acleft);
      ac.left = acleft;
    }
    if(a.right != null) {
      Node acright = a.right.clone();
      acright.plus += a.plus;
      acright.update(acright);
      ac.right = acright;
    }
    ac.v += ac.plus;
    ac.plus = 0;
    return ac.update(ac);
  }

  public static Node erase(Node a, int K) {
    Node[] ac = split(a, K + 1);
    Node[] bc = split(ac[0], K);
    Node b = merge(bc[0], ac[1]);
    return b.update(b);
  }

  public static long query(Node a, int l, int r) {
    if(a == null || r <= 0 || a.count <= l) {
      return INF;
    }
    if(l <= 0 && a.count <= r) {
      return a.minimum;
    } else {
      int c = a.count(a.left);
      long lv = query(a.left, l, r);
      long rv = query(a.right, l - c - 1, r - c - 1);
      long ret = Math.min(lv, rv);
      if(l <= c && c < r) ret = Math.min(ret, a.v);
      return ret;
    }
  }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    gen = new Random(1);
    int n = sc.nextInt();
    int Q = sc.nextInt();
    int[] x = new int[n];

    for(int i = 0; i < n; i++) {
      x[i] = sc.nextInt();
    }

    Node root = null;

    for(int v : x) {
      root = insert(root, root == null ? 0 : root.count(root), new Node(v));
    }

    for(int i = 0; i < Q; i++) {
      int t = sc.nextInt();
      if(t == 0) {
        int l = sc.nextInt();
        int r = sc.nextInt();
        Node[] a = split(root, r + 1);
        Node[] b = split(a[0], r);
        Node[] c = split(b[0], l);
        root = merge(c[0], b[1]);
        root = merge(root, c[1]);
        root = merge(root, a[1]);
      } else if(t == 1) {
        int l = sc.nextInt();
        int r = sc.nextInt();
        System.out.println(query(root, l, r + 1));
      } else {
        int pos = sc.nextInt();
        int v = sc.nextInt();
        root = erase(root, pos);
        root = insert(root, pos, new Node(v));
      }
    }
  }
}

