    public void Solve()
    {
        Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
        int N = Reader.Int(), Q = Reader.Int();
        var A = Reader.IntArray(N);
        var tree = new Treap(N);
        for (int i = 0; i < N; i++) tree.Insert(i, A[i]);

        foreach (var q in Reader.IntTable(Q))
            if (q[0] == 0)
            {
                // b1, b2 -> b2, b1
                int L = q[1], R = q[2] + 1;
                int a, b, b1, b2, c, t;
                tree.Split(tree.Root, R, out t, out c);
                tree.Split(t, L, out a, out b);
                tree.Split(b, R - L - 1, out b1, out b2);
                tree.Root = tree.Merge(a, b2);
                tree.Root = tree.Merge(tree.Root, b1);
                tree.Root = tree.Merge(tree.Root, c);
            }
            else if (q[0] == 1)
                Console.WriteLine(tree.Min(q[1], q[2] + 1));
            else
                tree[q[1]] = q[2];
        Console.Out.Flush();
        Console.ReadLine();

    }

