            static readonly XorShift random = new XorShift();

            public Node(long val, uint priority = uint.MaxValue)
            {
                L = R = None; Val = val; Count = 1;
                Min = val;
                //Max = val;
                //Sum = val;
                Priority = (priority == uint.MaxValue) ? random.Next() : priority;
            }
        }
        public class XorShift
        {
            uint m = 2463534242;
            public uint Next() { m = m ^ m << 13; m = m ^ m >> 17; return m = m ^ m << 5; }
        }

        static readonly int None = 0;
        int nodesIndex = 1;
        public Node[] nodes;
        public int Root;
        public int Count { get { return nodes[Root].Count; } }
        public Treap(int size) { Init(size); }

        private void Init(int size)
        {
            nodes = new Node[size + 1];
            nodes[None].Min = long.MaxValue;
            //nodes[None].Max = long.MinValue;
        }
        int GenNode(long val, uint priority = uint.MaxValue)
        {
            int i = nodesIndex++;
            nodes[i] = new Node(val, priority);
            return i;
        }

        //[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
        int Update(int i)
        {
            nodes[i].Count = nodes[nodes[i].L].Count + nodes[nodes[i].R].Count + 1;
            nodes[i].Min = Math.Min(nodes[i].Val, Math.Min(nodes[nodes[i].L].Min, nodes[nodes[i].R].Min));
            //nodes[i].Max = Math.Max(nodes[i].Val, Math.Max(nodes[nodes[i].L].Max, nodes[nodes[i].R].Max));
            return i;
        }

