        {
            get
            {
                Debug.Assert(index >= 0 && index < nodes[Root].Count);
                int i = Root;
                while (index != nodes[nodes[i].L].Count)
                    if (index < nodes[nodes[i].L].Count) i = nodes[i].L;
                    else { index -= nodes[nodes[i].L].Count + 1; i = nodes[i].R; }
                return nodes[i].Val;
            }
            set
            {
                //if (index < nodes[Root].Count) RemoveAt(index);
