        void SetRec(int i, int index, long val)
        {
            int Lsize = nodes[nodes[i].L].Count;
            if (index == Lsize) nodes[i].Val = val;
            else if (index < Lsize) SetRec(nodes[i].L, index, val);
            else SetRec(nodes[i].R, index - Lsize - 1, val);
            Update(i);
        }

        public int Merge(int L, int R)
        {
            if (L == None) return R;
            if (R == None) return L;
            if (nodes[L].Priority > nodes[R].Priority)
            {
                nodes[L].R = Merge(nodes[L].R, R);
                return Update(L);
            }
            else
            {
                nodes[R].L = Merge(L, nodes[R].L);
                return Update(R);
            }
        }

        public void Split(int i, int index, out int L, out int R)
        {
            if (i == None) { L = R = None; return; }

            if (index == nodes[nodes[i].L].Count)
            {
                L = nodes[i].L;
                R = i;
                nodes[i].L = None;
                Update(i);
                return;
            }
            int a, b;
            if (index < nodes[nodes[i].L].Count)
            {
                Split(nodes[i].L, index, out a, out b);
                nodes[i].L = b;
                L = a;
                R = Update(i);
            }
            else
            {
                Split(nodes[i].R, index - nodes[nodes[i].L].Count - 1, out a, out b);
                nodes[i].R = a;
                L = Update(i);
                R = b;
            }
        }

        public void Insert(int index, long val) { Root = Insert(Root, GenNode(val), index); }
        public int Insert(int i, int newNodeIndex, int index)
        {
            if (i == None) return newNodeIndex;
            if (nodes[newNodeIndex].Priority > nodes[i].Priority)
            {
                int L, R;
                Split(i, index, out L, out R);
                i = Merge(L, newNodeIndex);
                i = Merge(i, R);
            }
            else
            {
                if (index <= nodes[nodes[i].L].Count)
                    nodes[i].L = Insert(nodes[i].L, newNodeIndex, index);
                else
                    nodes[i].R = Insert(nodes[i].R, newNodeIndex, index - nodes[nodes[i].L].Count - 1);
                Update(i);
            }
            return i;
        }


        public void RemoveAt(int index) { Root = RemoveAt(Root, index); }
        int RemoveAt(int i, int index)
        {
            if (index == nodes[nodes[i].L].Count)
                return Merge(nodes[i].L, nodes[i].R);
            if (index < nodes[nodes[i].L].Count)
                nodes[i].L = RemoveAt(nodes[i].L, index);
            else
                nodes[i].R = RemoveAt(nodes[i].R, index - nodes[nodes[i].L].Count - 1);
            return Update(i);
        }


