public class Program
{
    public void Solve()
    {
        Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
        int N = Reader.Int(), Q = Reader.Int();
        var A = Reader.IntArray(N);
        var tree = new Treap(N + Q);
        for (int i = 0; i < N; i++) tree.Insert(i, A[i]);

        foreach (var q in Reader.IntTable(Q))
            if (q[0] == 0)
            {
                // b1, b2 -> b2, b1
                int L = q[1], R = q[2] + 1;
                int a, b, b1, b2, c, t;
                tree.Split(tree.Root, R, out t, out c);
                tree.Split(t, L, out a, out b);
                tree.Split(b, R - L - 1, out b1, out b2);
                tree.Root = tree.Merge(a, b2);
                tree.Root = tree.Merge(tree.Root, b1);
                tree.Root = tree.Merge(tree.Root, c);
            }
            else if (q[0] == 1)
                Console.WriteLine(tree.Min(q[1], q[2] + 1));
            else
            {
                tree.RemoveAt(q[1]);
                tree.Insert(q[1], q[2]);
            }
        Console.Out.Flush();
        Console.ReadLine();

    }

    public class Treap
    {
        public struct Node
        {
            public int L, R;
            public int Count;
            public long Val;
            public long Min;
            public long Max;
            public long Sum;
            public readonly uint Priority;
            static readonly XorShift random = new XorShift();

            public Node(long val, uint priority = uint.MaxValue)
            {
                L = R = None; Val = val; Count = 1;
                Min = val;
                Max = val;
                Sum = val;
                Priority = (priority == uint.MaxValue) ? random.Next() : priority;
            }
        }
        public class XorShift
        {
            uint m = 2463534242;
            public uint Next() { m = m ^ m << 13; m = m ^ m >> 17; return m = m ^ m << 5; }
