        long RangeQuery(int i, int L, int R, long init, Func<int, long> nF, Func<long, long, long> F)
        {
            if (i == None || L >= R) return init;
            if (L == 0 && R == nodes[i].Count) return nF(i);
            long res = init;
            int Lsize = nodes[nodes[i].L].Count;
            if (Lsize >= L && Lsize < R)
                res = nodes[i].Val;
            if (L < Lsize)
                res = F(res, RangeQuery(nodes[i].L, L, Math.Min(R, Lsize), init, nF, F));
            if (R - Lsize - 1 > 0)
                res = F(res, RangeQuery(nodes[i].R, Math.Max(0, L - Lsize - 1), R - Lsize - 1, init, nF, F));
