    class OnlineJudge
    {
        static void Main()
        {
            Func<int[]> num = () => Console.ReadLine().Split().Select(p => int.Parse(p)).ToArray();
            var count = num();
            var value = Enumerable.Range(0, count[0]).Select(p => int.Parse(Console.ReadLine())).ToList();
