                (i1,i2) => {
                    int temp = value[i2];
                    for(int i=0;i < i2 - i1;++i){
                        value[i2 - i] = value[i2 - i - 1];
                    }
                    value[i1] = temp;
                },
                (i1,i2) => {
                    int min = value[i1];
                    for(int i = 1;i <= i2 - i1;++i){
                        min = min > value[i1 + i] ? value[i1 + i] : min;
                    }
                    Console.WriteLine(min);
                },
                (p,v) => value[p] = v,
            };
            Action query = () => {
                var val = num();
                proc[val[0]](val[1], val[2]);
            };
            for(int i=0; i < count[1]; ++i) {
                query();
            }
        }
    }
}

