                //Insert(index, value);

                int num = 0;
                int i = Root, Lsize;
                while ((Lsize = nodes[nodes[i].L].Count) != index)
                    if (index < Lsize) { setTmp[num++] = i; i = nodes[i].L; }
                    else { setTmp[num++] = ~i; index -= Lsize + 1; i = nodes[i].R; }
                nodes[i].Val = value;
                Update(i);
                while (--num >= 0)
                {
                    int v = setTmp[num];
                    if (v >= 0) nodes[v].L = i;
                    else { v = ~v; nodes[v].R = i; }
                    Update(v);
                    i = v;
                }
            }
