        {
            if (i == None) { L = R = None; return; }

            if (index == nodes[nodes[i].L].Count)
            {
                L = nodes[i].L;
                R = i;
                nodes[i].L = None;
                Update(i);
                return;
            }
            int a, b;
            if (index < nodes[nodes[i].L].Count)
            {
                Split(nodes[i].L, index, out a, out b);
                nodes[i].L = b;
                L = a;
                R = Update(i);
            }
            else
            {
                Split(nodes[i].R, index - nodes[nodes[i].L].Count - 1, out a, out b);
                nodes[i].R = a;
                L = Update(i);
                R = b;
            }
        }

