			@min
		else
			force if @unforced
			l_min = @left_child.min(x, [@left_child.range_max, y].min)
			r_min = @right_child.min([@right_child.range_min, x].max, y)
			[l_min, r_min].min
		end
	end

	def max(x = @range_min, y = @range_max)
		return -Float::INFINITY if x > y

		if x == @range_min && y == @range_max
			@max
		else
			force if @unforced
			l_max = @left_child.max(x, [@left_child.range_max, y].min)
			r_max = @right_child.max([@right_child.range_min, x].max, y)
			[l_max, r_max].max
		end
	end
end


